	["COMP_SAY_ADVICE_HEALTH_V_mechanical"] = "Aviso: integridad del operador por debajo del 30%%. Se aconseja retirada.",
	["COMP_SAY_ADVICE_HEALTH_V_mechanical_2"] = "¡Bip! ¡Bip! ¡BIP! Esa era la alarma.",
	["COMP_SAY_ADVICE_HEALTH_V_mechanical_3"] = "Reparaciones urgentes necesarias. No tengo llave inglesa para ti.",
	["COMP_SAY_ADVICE_HEALTH_V_undead"] = "Te estás poniendo pálido. Te sienta bien, pero prefiero tenerte entre los vivos.",
	["COMP_SAY_ADVICE_HEALTH_V_undead_2"] = "¡Cuidado! Vas por el camino que tomé yo. No lo recomiendo.",
	["COMP_SAY_ADVICE_HEALTH_V_undead_3"] = "Cúrate. Con una momia en el equipo basta.",
	["COMP_SAY_ADVICE_HEALTH__cuddly"] = "¿Estás herido? Ven, descansemos, yo te cuido.",
	["COMP_SAY_ADVICE_HEALTH__cuddly_2"] = "Estás todo arañado… deja que te cure. Con un abrazo.",
	["COMP_SAY_ADVICE_HEALTH__cuddly_3"] = "Siéntate a mi lado. Recuperemos el aliento.",
	["COMP_SAY_ADVICE_HEALTH__cuddly_4"] = "Tienes mala cara, cielo. Descansa, ¿vale?",
	["COMP_SAY_ADVICE_HEALTH__curious"] = "Estás hecho polvo… ¿Nos sentamos y me lo cuentas?",
	["COMP_SAY_ADVICE_HEALTH__curious_2"] = "¿Te duele? ¿Dónde? ¿En todas partes? Sentémonos y me explicas.",
	["COMP_SAY_ADVICE_HEALTH__curious_3"] = "¿Por qué parpadeas en rojo? Ah, es tu salud. Descansemos.",
	["COMP_SAY_ADVICE_HEALTH__curious_4"] = "¿Intentaste abrazar a un oso? Descansa un poco.",
	["COMP_SAY_ADVICE_HEALTH__daring"] = "Hasta los héroes recuperan el aliento. Descansa y vuelve a la carga.",
	["COMP_SAY_ADVICE_HEALTH__daring_2"] = "¡Te han dado una paliza! Cúrate y devuélvesela.",
	["COMP_SAY_ADVICE_HEALTH__daring_3"] = "Hasta un héroe necesita puntos de salud. Tú sobre todo.",
	["COMP_SAY_ADVICE_HEALTH__daring_4"] = "Retrocede, respira, vuelve más fuerte. O simplemente vivo.",
	["COMP_SAY_ADVICE_HEALTH__fearful"] = "¡Estás sangrando! Siéntate, come, yo vigilo.",
	["COMP_SAY_ADVICE_HEALTH__fearful_2"] = "¿Has visto tu barra de salud? Yo sí. Y grité.",
	["COMP_SAY_ADVICE_HEALTH__fearful_3"] = "¡Para! ¡Descansa! No eres inmortal, aunque lo parezca.",
	["COMP_SAY_ADVICE_HEALTH__fearful_4"] = "Sigues en pie de milagro. Descansemos, por favor.",
	["COMP_SAY_ADVICE_HEALTH__glutton"] = "¡Qué pálido estás! Come algo, y dame un poco.",
	["COMP_SAY_ADVICE_HEALTH__glutton_2"] = "Qué pálido estás. Conozco el remedio: una sopa calentita.",
	["COMP_SAY_ADVICE_HEALTH__glutton_3"] = "Apenas te tienes en pie. Siéntate, come y comparte.",
	["COMP_SAY_ADVICE_HEALTH__glutton_4"] = "Pareces pan duro. Descansemos.",
	["COMP_SAY_ADVICE_HEALTH__lazy"] = "Estás agotado… propongo un descanso muy, muy largo.",
	["COMP_SAY_ADVICE_HEALTH__lazy_2"] = "Estás todo en rojo… ¿ves? Debimos parar antes.",
	["COMP_SAY_ADVICE_HEALTH__lazy_3"] = "Bien, hacemos una pausa. Por tu salud. Y por mi gusto.",
	["COMP_SAY_ADVICE_HEALTH__lazy_4"] = "Estás reventado. Siéntate. O túmbate, mejor aún.",
	["COMP_SAY_ADVICE_HEALTH__mischievous"] = "¡Estás todo abollado! Una pausa corta, y te hago reír.",
	["COMP_SAY_ADVICE_HEALTH__mischievous_2"] = "¡Estás todo abollado! Una pausa, o te pinto más moratones.",
	["COMP_SAY_ADVICE_HEALTH__mischievous_3"] = "Tu barra de salud está echando la siesta. Haz lo mismo, jiji.",
	["COMP_SAY_ADVICE_HEALTH__mischievous_4"] = "Pareces un espantapájaros. Come algo, ya terminé de reírme. Casi.",
	["COMP_SAY_ADVICE_HEALTH__mystic"] = "Tu luz se apaga… descansa, deja que vuelva.",
	["COMP_SAY_ADVICE_HEALTH__mystic_2"] = "Tu llama vacila. Los espíritus ya te están poniendo un cubierto.",
	["COMP_SAY_ADVICE_HEALTH__mystic_3"] = "Tu aura está hecha jirones. Siéntate antes del velo.",
	["COMP_SAY_ADVICE_HEALTH__mystic_4"] = "Descansa. El cementerio no es lugar de vacaciones.",
	["COMP_SAY_ADVICE_HEALTH__parrot"] = "¡Descansa! ¡Descansa! ¡Estás herido! ¡Craac!",
	["COMP_SAY_ADVICE_HEALTH__parrot_2"] = "¡Ay, ay! ¡Ay, ay! ¡Siéntate! ¡Craac!",
	["COMP_SAY_ADVICE_HEALTH__parrot_3"] = "¡Casi muerto! ¡Casi muerto! ¡Come! ¡Craac!",
	["COMP_SAY_ADVICE_HEALTH__parrot_4"] = "¡Descansa! ¡Descansa! ¡Lorito insiste! ¡Craac!",
	["COMP_SAY_ADVICE_HEALTH__sly"] = "Estás herido. Retrocede, cúrate, golpea después.",
	["COMP_SAY_ADVICE_HEALTH__sly_2"] = "¿Retirada? Bien. La retirada táctica es un arte.",
	["COMP_SAY_ADVICE_HEALTH__sly_3"] = "Cúrate. Las reparaciones cuestan más que una venda.",
	["COMP_SAY_ADVICE_HEALTH__sly_4"] = "Estás medio muerto. A los muertos no los vendo.",
	["COMP_SAY_ADVICE_HEALTH__teasing"] = "¡Tienes una pinta horrible! Descansa, por el bien de mis ojos.",
	["COMP_SAY_ADVICE_HEALTH__teasing_2"] = "Tienes la salud de un mosquito. Siéntate, campeón.",
	["COMP_SAY_ADVICE_HEALTH__teasing_3"] = "Un golpe más y te escribo el epitafio.",
	["COMP_SAY_ADVICE_HEALTH__teasing_4"] = "Come algo, estás asustando a los jabalíes. Y no de la buena forma.",
	["COMP_SAY_ADVICE_HEALTH__tinker"] = "¡Tus indicadores están en rojo! Mantenimiento necesario.",
	["COMP_SAY_ADVICE_HEALTH__tinker_2"] = "Alerta: integridad estructural del héroe a la mitad. ¡Pausa de reparación!",
	["COMP_SAY_ADVICE_HEALTH__tinker_3"] = "Tienes fugas por todas partes. Siéntate, te remiendo. Bueno, come.",
	["COMP_SAY_ADVICE_HEALTH__tinker_4"] = "Se encendió la luz roja. No, no la desenchufamos. Descansamos.",
	["COMP_SAY_ADVICE_HEALTH__wise"] = "El sabio descansa antes de estar cansado. Es la hora.",
	["COMP_SAY_ADVICE_HEALTH__wise_2"] = "La mejor hoja se rompe si se fuerza. Descansa.",
	["COMP_SAY_ADVICE_HEALTH__wise_3"] = "Uuh. Guerrero herido, guerrero precipitado. No seas ninguno.",
	["COMP_SAY_ADVICE_HEALTH__wise_4"] = "Siéntate. El suelo se disfruta más sentado que tumbado.",
	["COMP_SAY_ADVICE_HEALTH__zen"] = "Te falta el aliento. Siéntate, respira.",
	["COMP_SAY_ADVICE_HEALTH__zen_2"] = "Estás medio vacío. Siéntate. La aventura no se va a escapar.",
	["COMP_SAY_ADVICE_HEALTH__zen_3"] = "Tu salud está baja y tu ímpetu alto. Intercámbialos.",
	["COMP_SAY_ADVICE_HEALTH__zen_4"] = "Siéntate. Come. Solo entonces, cárgate contra el muro.",
	["COMP_SAY_ADVICE_HEARTH"] = "Tu piedra de hogar está lista. ¿Volvemos a casa?",
	["COMP_SAY_ADVICE_HEARTH_2"] = "La piedra de hogar ha vuelto y vamos cargados: ¿a la posada?",
	["COMP_SAY_ADVICE_HEARTH_3"] = "Piedra de hogar lista. ¡A la posada, sin caminar!",
	["COMP_SAY_ADVICE_HEARTH_4"] = "Piedra de hogar recargada. Tus pies lo suplican.",
	["COMP_SAY_ADVICE_HEARTH_5"] = "La piedra de hogar brilla. Quiere volver a casa.",
	["COMP_SAY_ADVICE_QUESTS"] = "Aquí hemos terminado: ¿vamos a entregar las misiones?",
	["COMP_SAY_ADVICE_QUESTS_2"] = "¡Todas tus misiones están listas para entregar!",
	["COMP_SAY_ADVICE_QUESTS_3"] = "Tus misiones están hechas. ¿Vamos a por las recompensas?",
	["COMP_SAY_ADVICE_QUESTS_4"] = "¡Todo listo! Están esperando tu cara de héroe.",
	["COMP_SAY_ADVICE_QUESTS_5"] = "Aquí ya está. Volvamos antes de que se te olvide todo.",
	["COMP_SAY_ADVICE_RARE"] = "¡Oh, %s! Un raro, pero parece duro.",
	["COMP_SAY_ADVICE_RARE_2"] = "%s merodea por aquí: raro, y más fuerte que tú.",
	["COMP_SAY_ADVICE_RARE_3"] = "¡%s! Raro, bonito… y demasiado fuerte. ¿Lo admiramos de lejos?",
	["COMP_SAY_ADVICE_RARE_4"] = "Un raro: %s. Tentador, pero tu nivel dice que no.",
	["COMP_SAY_ADVICE_RARE_5"] = "%s acecha. No te confíes, ¿vale?",
	["COMP_SAY_AWAKE"] = "¡Despierto del todo!",
	["COMP_SAY_AWAKE_2"] = "Vale, estoy despierto. Casi. Sí. ¡Vamos!",
	["COMP_SAY_AWAKE_3"] = "¡Fresco como una lechuga!",
	["COMP_SAY_AWAKE_4"] = "¡Arriba! Bueno, yo. Tú ya lo estabas.",
	["COMP_SAY_AWAKE_5"] = "¡Despierto! ¿Qué me perdí? ¿Nada? Perfecto.",
	["COMP_SAY_AWAKE_6"] = "Tengo las orejas arrugadas, pero estoy listo.",
	["COMP_SAY_AWAKE_7"] = "A ver, ¿a quién hay que vigilar? Ah, sí. A ti.",
	["COMP_SAY_CAMP"] = "¿Nos calentamos un poco?",
	["COMP_SAY_CAMP_10"] = "¿Nos sentamos? Yo vigilo, tú suspiras.",
	["COMP_SAY_CAMP_11"] = "¡Ah, calorcito! Nada mejor tras un día dando vueltas.",
	["COMP_SAY_CAMP_2"] = "¡Una hoguera! Me siento bien cerquita.",
	["COMP_SAY_CAMP_3"] = "Cric, crac… me encanta ese sonido.",
	["COMP_SAY_CAMP_4"] = "¿Una pausa junto al fuego?",
	["COMP_SAY_CAMP_5"] = "¡Cuéntame una historia junto al fuego!",
	["COMP_SAY_CAMP_6"] = "¡Un fuego! Siéntate, y aparta los pies.",
	["COMP_SAY_CAMP_7"] = "¿Pausa calentita? Te la has ganado. Más o menos.",
	["COMP_SAY_CAMP_8"] = "El fuego crepita. Tú crujes un poco. Descansa.",
	["COMP_SAY_CAMP_9"] = "Una hoguera: ideal para secarte tras caerte al río.",
	["COMP_SAY_CAMP__cuddly"] = "Un fuego… ¿nos acurrucamos?",
	["COMP_SAY_CAMP__cuddly_2"] = "¡Un fuego! Me acurruco contra ti, ¿vale?",
	["COMP_SAY_CAMP__cuddly_3"] = "Calentemos las patitas, y el corazón.",
	["COMP_SAY_CAMP__cuddly_4"] = "El fuego, tú, yo. Nada más.",
	["COMP_SAY_CAMP__curious"] = "¡Una hoguera! ¿Nos contamos lo que hemos visto?",
	["COMP_SAY_CAMP__curious_2"] = "¡Un fuego! ¿Cómo funciona el fuego? ¿Por qué quema?",
	["COMP_SAY_CAMP__curious_3"] = "¿Cuánto nos quedamos? ¿Te vas a dormir delante otra vez?",
	["COMP_SAY_CAMP__curious_4"] = "¿Quién encendió este fuego? ¿Crees que volverá?",
	["COMP_SAY_CAMP__daring"] = "¿Una pausa? Vale, ¡pero corta!",
	["COMP_SAY_CAMP__daring_2"] = "¡Un fuego! Perfecto para contar hazañas. Las tuyas son cortas.",
	["COMP_SAY_CAMP__daring_3"] = "Descanso del guerrero: cinco minutos. No seis.",
	["COMP_SAY_CAMP__daring_4"] = "Junto al fuego se afilan las armas. Tú, afila tu valor.",
	["COMP_SAY_CAMP__fearful"] = "¡Un fuego! A las bestias no les gusta el fuego. Me quedo aquí.",
	["COMP_SAY_CAMP__fearful_2"] = "¡Un fuego! Por fin un sitio donde nadie nos ataca. En principio.",
	["COMP_SAY_CAMP__fearful_3"] = "¿Nos quedamos junto al fuego toda la noche? ¿Toda la semana?",
	["COMP_SAY_CAMP__fearful_4"] = "Pero no tan cerca. El pollo asado no es lo mío.",
	["COMP_SAY_CAMP__glutton"] = "¡Un fuego! ¿Asamos algo?",
	["COMP_SAY_CAMP__glutton_2"] = "¿Un fuego sin brochetas? Qué desperdicio.",
	["COMP_SAY_CAMP__glutton_3"] = "¿Tostamos tus calcetines viejos? ¿No? Pan, entonces.",
	["COMP_SAY_CAMP__glutton_4"] = "¡Hoguera! Yo vigilo la olla. ¿No hay olla?",
	["COMP_SAY_CAMP__lazy"] = "¡Una hoguera! ¡Por fin! No me muevo.",
	["COMP_SAY_CAMP__lazy_2"] = "Ahh… el fuego, el calor… despiértame mañana.",
	["COMP_SAY_CAMP__lazy_3"] = "Un fuego… ¿ves? Se puede parar. No está prohibido.",
	["COMP_SAY_CAMP__lazy_4"] = "¿Acampamos aquí esta noche? ¿Y mañana? ¿Y pasado?",
	["COMP_SAY_CAMP__lazy_5"] = "No hagas la bolsa todavía. Ni mañana. Estoy cómodo.",
	["COMP_SAY_CAMP__mischievous"] = "¡Un fuego! ¿Puedo hacer chispas azules? ¡Mira!",
	["COMP_SAY_CAMP__mischievous_2"] = "¡Un fuego! Echo un puñado de destellos. ¡Fssshhh!",
	["COMP_SAY_CAMP__mischievous_3"] = "¿Hora del cuento? Empiezo yo: érase una vez tú, perdido.",
	["COMP_SAY_CAMP__mischievous_4"] = "¡Cuidado con las cejas! Jiji, ¿demasiado tarde? Es broma.",
	["COMP_SAY_CAMP__mystic"] = "El fuego danza… cuenta el futuro.",
	["COMP_SAY_CAMP__mystic_2"] = "Las brasas dibujan tu futuro… un jabalí. Siempre un jabalí.",
	["COMP_SAY_CAMP__mystic_3"] = "El fuego susurra. Dice que tienes los pies fríos.",
	["COMP_SAY_CAMP__mystic_4"] = "Siéntate. Las llamas cuentan historias mejor que tú.",
	["COMP_SAY_CAMP__parrot"] = "¡Fuego! ¡Fuego! ¡Calentito! ¡Craac!",
	["COMP_SAY_CAMP__parrot_2"] = "¡Fuego! ¡Fuego! ¡No tan cerca! ¡Craac!",
	["COMP_SAY_CAMP__parrot_3"] = "¡Cuento! ¡Cuento! ¡Cuenta uno! ¡Craac!",
	["COMP_SAY_CAMP__parrot_4"] = "¡Calentito, calentito! ¡Lorito feliz!",
	["COMP_SAY_CAMP__sly"] = "Un fuego… nos ven desde lejos. Pero se está a gusto.",
	["COMP_SAY_CAMP__sly_2"] = "Un fuego… he visto un cofre detrás. Solo digo…",
	["COMP_SAY_CAMP__sly_3"] = "Sentados al calor. Contando lo que gastaste hoy. Ay.",
	["COMP_SAY_CAMP__sly_4"] = "Buen fuego. Barato. Gratis, incluso. Mi tipo de fuego.",
	["COMP_SAY_CAMP__teasing"] = "¡Un fuego! Cuidado con las cejas esta vez.",
	["COMP_SAY_CAMP__teasing_2"] = "¡Un fuego! ¿Sabes encenderlo, o soplo yo las brasas?",
	["COMP_SAY_CAMP__teasing_3"] = "Siéntate y cuéntame tus hazañas. No tardaremos.",
	["COMP_SAY_CAMP__teasing_4"] = "Una hoguera. No tan cerca, que te conozco.",
	["COMP_SAY_CAMP__tinker"] = "¡Un fuego! Perfecto para soldar. Bueno, para calentarse.",
	["COMP_SAY_CAMP__tinker_2"] = "¡Un fuego! Ajusto la llama. Listo, rendimiento óptimo.",
	["COMP_SAY_CAMP__tinker_3"] = "Pausa de mantenimiento junto al fuego. Dame tus botas, chirrían.",
	["COMP_SAY_CAMP__tinker_4"] = "Podría motorizar este fuego. ¿Para qué? ¡¿Y por qué no?!",
	["COMP_SAY_CAMP__wise"] = "El fuego calienta el cuerpo; las historias, la mente.",
	["COMP_SAY_CAMP__wise_2"] = "Un fuego. Siéntate y reflexiona sobre las decisiones de hoy.",
	["COMP_SAY_CAMP__wise_3"] = "El fuego no tiene prisa. Sigue su ejemplo.",
	["COMP_SAY_CAMP__wise_4"] = "Junto al fuego, hasta los torpes se vuelven narradores.",
	["COMP_SAY_CAMP__zen"] = "Un fuego. Calma. Perfecto.",
	["COMP_SAY_CAMP__zen_2"] = "Un fuego. Siéntate. Esta vez no te quemes los dedos.",
