	["COMP_SAY_CAPTURE_ITEM_2"] = "¡Encontré %s! Guárdalo bien, no como tus pociones.",
	["COMP_SAY_CAPTURE_ITEM_3"] = "Mira, %s. Más vale que el próximo monstruo se porte bien.",
	["COMP_SAY_CAPTURE_OK"] = "¡%s es nuestro! ¡Bienvenido al equipo!",
	["COMP_SAY_CAPTURE_OK_2"] = "¡Capturado! %s, te aviso: el sitio junto al fuego es mío.",
	["COMP_SAY_CAPTURE_OK_3"] = "Y ahí va, %s a la colección. Cuánto talento… mío, sobre todo.",
	["COMP_SAY_CAPTURE_OK_4"] = "¡%s capturado! Ya ves lo que pasa cuando me haces caso…",
	["COMP_SAY_CAPTURE_OK_5"] = "¡Un %s nuevecito! Le enseñaré modales.",
	["COMP_SAY_CAPTURE_OK_6"] = "¡Lo tengo! %s ya está mirando mis golosinas.",
	["COMP_SAY_CAPTURE_OK_V_beast"] = "%s se une a la manada. Le enseñaré dónde enterramos los huesos.",
	["COMP_SAY_CAPTURE_OK_V_beast_2"] = "¡Lo tengo! Te lo llevé hacia ti, ¿lo viste? ¿Lo viste?",
	["COMP_SAY_CAPTURE_OK_V_beast_3"] = "Olfateando a %s… Olor aprobado. Bienvenido.",
	["COMP_SAY_CAPTURE_OK_V_critter"] = "¡%s está con nosotros! Parece simpático. Parece simpático, ¿verdad?",
	["COMP_SAY_CAPTURE_OK_V_critter_2"] = "¡Un amigo nuevo! Espero que no me tome por un aperitivo.",
	["COMP_SAY_CAPTURE_OK_V_critter_3"] = "¡Atrapado! Le haré un huequito en el nido.",
	["COMP_SAY_CAPTURE_OK_V_demon"] = "%s es nuestro. Para siempre. El contrato es claro.",
	["COMP_SAY_CAPTURE_OK_V_demon_2"] = "¡Atrapado! Tranquilo, no me lo comeré. Todavía.",
	["COMP_SAY_CAPTURE_OK_V_demon_3"] = "Otra alma atada. Aprendes rápido, mortal.",
	["COMP_SAY_CAPTURE_OK_V_dragonkin"] = "%s se une a mi tesoro. Digo, a nuestra colección.",
	["COMP_SAY_CAPTURE_OK_V_dragonkin_2"] = "Atrapado. Al tesoro. Todo acaba en el tesoro.",
	["COMP_SAY_CAPTURE_OK_V_dragonkin_3"] = "Bien. Una criatura digna de servir a un dragón.",
	["COMP_SAY_CAPTURE_OK_V_elemental"] = "%s se une a la corriente. Bienvenido, riachuelo.",
	["COMP_SAY_CAPTURE_OK_V_elemental_2"] = "Atrapado sin un ruido, como la bruma cubre el valle.",
	["COMP_SAY_CAPTURE_OK_V_elemental_3"] = "Un nuevo elemento en nuestro círculo. La armonía crece.",
	["COMP_SAY_CAPTURE_OK_V_gfw"] = "¡Otro más para el saco!",
	["COMP_SAY_CAPTURE_OK_V_gfw_2"] = "¡%s, bienvenido! Hay sitio entre los juguetes y las mandarinas.",
	["COMP_SAY_CAPTURE_OK_V_gfw_3"] = "¡Bonito paquete! No lo habría envuelto mejor.",
	["COMP_SAY_CAPTURE_OK_V_giant"] = "%s… en bolsillo. Bolsillo grande. Mucho sitio.",
	["COMP_SAY_CAPTURE_OK_V_giant_2"] = "¡Atrapado! Yo hacer baile feliz. … Perdón por el cráter.",
	["COMP_SAY_CAPTURE_OK_V_giant_3"] = "Amigo pequeño nuevo. Yo cuidado. No pisar.",
	["COMP_SAY_CAPTURE_OK_V_humanoid"] = "¡%s es nuestro! Lo dije en la taberna y nadie me creyó.",
	["COMP_SAY_CAPTURE_OK_V_humanoid_2"] = "¡Atrapado! Eso es trabajo profesional.",
	["COMP_SAY_CAPTURE_OK_V_humanoid_3"] = "Bienvenido al equipo, %s. Regla uno: se comparten las raciones.",
	["COMP_SAY_CAPTURE_OK_V_mechanical"] = "Captura confirmada. %s añadido a la base de datos.",
	["COMP_SAY_CAPTURE_OK_V_mechanical_2"] = "Red: éxito. Actualizando el inventario de bichos. Bip.",
	["COMP_SAY_CAPTURE_OK_V_mechanical_3"] = "Probabilidad de éxito: baja. Resultado: éxito. Me encanta cuando fallan las mates.",
	["COMP_SAY_CAPTURE_OK_V_metzen"] = "%s se une al tiro del trineo. Va al final.",
	["COMP_SAY_CAPTURE_OK_V_metzen_2"] = "¡Atrapado! Mi nariz lo vio mucho antes que tú.",
	["COMP_SAY_CAPTURE_OK_V_metzen_3"] = "Bien. Rápido, eficaz. Casi digno de un reno.",
	["COMP_SAY_CAPTURE_OK_V_snowman"] = "¡%s viene con nosotros! Le tejeré una bufanda.",
	["COMP_SAY_CAPTURE_OK_V_snowman_2"] = "¡Un amigo nuevo! Parece calentito. No tan cerca, ¿vale?",
	["COMP_SAY_CAPTURE_OK_V_snowman_3"] = "¡Atrapado! Como un copo de nieve, pero más grande.",
	["COMP_SAY_CAPTURE_OK_V_undead"] = "%s se une a la colección. Como yo, pero más fresco.",
	["COMP_SAY_CAPTURE_OK_V_undead_2"] = "¡Atrapado! Nadie escapa de mi red. Ni de mi cementerio.",
	["COMP_SAY_CAPTURE_OK_V_undead_3"] = "Un alma nueva en la familia. Le guardaré una tumba… eh, un sitio.",
	["COMP_SAY_CAPTURE_PROMPT"] = "%s ha caído. ¿Nos lo llevamos a casa?",
	["COMP_SAY_CAPTURE_PROMPT_2"] = "Rápido, %s no se mueve: ¡es nuestra oportunidad!",
	["COMP_SAY_CAPTURE_PROMPT_3"] = "%s sería un gran compañero… casi tan bueno como yo.",
	["COMP_SAY_CAPTURE_PROMPT_4"] = "¿Vas a dejar ahí a %s? Yo digo: ¡red!",
	["COMP_SAY_CAPTURE_PROMPT_5"] = "¿%s en mi colección? ¡Clic, clic!",
	["COMP_SAY_CAPTURE_PROMPT_6"] = "¿Lo intentamos con %s? Prometo compartir mi cuenco.",
	["COMP_SAY_CAPTURE_SHINY"] = "¡%s BRILLANTE capturado! Estoy llorando. De alegría. Y un poco de envidia.",
	["COMP_SAY_CAPTURE_SHINY_2"] = "Un %s brillante en la colección… ¿lo ponemos en una vitrina?",
	["COMP_SAY_CHATTER_1"] = "Vale, me callo: solo hablaré cuando importe.",
	["COMP_SAY_CHATTER_2"] = "Me quedo tranquilo: mis consejos y los grandes momentos, nada más.",
	["COMP_SAY_CHATTER_3"] = "¡Volvemos a lo normal! ¿Charlamos?",
	["COMP_SAY_CHATTER_4"] = "¿Puedo charlar? ¡Tengo tantas cosas que contarte!",
	["COMP_SAY_CHEST"] = "¡Hemos visto todo %s! Un cofre para ti… ¡para nosotros!",
	["COMP_SAY_CHEST_2"] = "¡%s, hecho! Abre el cofre, ¡quiero verlo!",
	["COMP_SAY_CHEST_3"] = "Todo %s en el diario. Nos hemos ganado un cofre.",
	["COMP_SAY_CHEST_4"] = "¡%s, terminado! Hasta los rincones donde te perdiste.",
	["COMP_SAY_CHEST_5"] = "¡Todo %s visto! Ya no tenía esperanzas. ¡Abre ese cofre, rápido!",
	["COMP_SAY_CHEST_6"] = "¡%s al 100%%! Un cofre, y ni un rodeo inútil. Bueno, muchos.",
	["COMP_SAY_CITY"] = "¡%s! Cuánta gente, no te separes.",
	["COMP_SAY_CITY_10"] = "Bienvenido a %s. No saltes del puente, no es un atajo.",
	["COMP_SAY_CITY_11"] = "¡Una gran ciudad! Perfecta para vender tus tesoros grises por una fortuna. No.",
	["COMP_SAY_CITY_2"] = "¡La gran ciudad! Me voy a perder.",
	["COMP_SAY_CITY_3"] = "Aquí hay de todo: instructores, banco, vendedores.",
	["COMP_SAY_CITY_4"] = "¡Qué bullicio! Dame la pata.",
	["COMP_SAY_CITY_5"] = "¡Bienvenido a %s! ¿Te guío? No, me perdería.",
	["COMP_SAY_CITY_6"] = "¡%s! Ponte derecho, la gente mira.",
	["COMP_SAY_CITY_7"] = "¡La capital! No hables con desconocidos. Bueno, salvo con vendedores.",
	["COMP_SAY_CITY_8"] = "¡%s! Otra hora buscando el banco.",
	["COMP_SAY_CITY_9"] = "¡Cuánta gente! Y todos tienen monturas más bonitas que la tuya.",
	["COMP_SAY_CITY_V_beast"] = "%s… ¡Demasiados olores! Pan, cuero, perros. Muchos perros.",
	["COMP_SAY_CITY_V_beast_2"] = "Muros por todas partes. Me quedo pegado a ti, ¿vale?",
	["COMP_SAY_CITY_V_critter"] = "%s… ¡Cuántas botas! Me quedo en tu bolsillo, ¿vale?",
	["COMP_SAY_CITY_V_critter_2"] = "¡Una ciudad! ¿Hay gatos? Dime que no hay gatos.",
	["COMP_SAY_CITY_V_demon"] = "%s. Cuántos mortales. Cuántos… no, me portaré bien. Prometido.",
	["COMP_SAY_CITY_V_demon_2"] = "Una ciudad. Si un sacerdote me mira mal, yo nunca estuve aquí.",
	["COMP_SAY_CITY_V_dragonkin"] = "%s. A los mortales les encanta amontonarse. Como monedas en un cofre.",
	["COMP_SAY_CITY_V_dragonkin_2"] = "Una ciudad. Antes la habría arrasado. Me he vuelto sabio.",
	["COMP_SAY_CITY_V_elemental"] = "%s. Cuánta piedra tallada… Habría preferido seguir siendo montaña.",
	["COMP_SAY_CITY_V_elemental_2"] = "Una ciudad. Mucho ruido, poco viento. Me haré pequeño.",
	["COMP_SAY_CITY_V_gfw"] = "¡%s! Cuántas chimeneas… Ahí se va toda mi noche.",
	["COMP_SAY_CITY_V_gfw_2"] = "Una gran ciudad: necesitaré todos los renos y un segundo trineo.",
	["COMP_SAY_CITY_V_giant"] = "%s. Puertas muy pequeñas. ¿Yo quedar fuera? … No. Yo agachar.",
	["COMP_SAY_CITY_V_giant_2"] = "Ciudad. Mucha gente pequeña. Yo andar… muy… con cuidado.",
	["COMP_SAY_CITY_V_humanoid"] = "¡%s! Mercados, tabernas, chismes… Me encanta.",
	["COMP_SAY_CITY_V_humanoid_2"] = "¡Una ciudad! Cuida tu bolsa, aquí los carteristas son rápidos.",
	["COMP_SAY_CITY_V_mechanical"] = "Zona urbana. Densidad de transeúntes: alta. Bajando mi volumen.",
	["COMP_SAY_CITY_V_mechanical_2"] = "Entrando en %s. Descargando mapa… fallo. Improvisamos.",
	["COMP_SAY_CITY_V_metzen"] = "%s. Demasiada gente, poca nieve. La cruzamos al trote.",
	["COMP_SAY_CITY_V_metzen_2"] = "Tejados por todas partes. Los conozco todos, desde arriba.",
	["COMP_SAY_CITY_V_snowman"] = "¡%s! Cuánta gente… Aún nadie me ha pisado.",
	["COMP_SAY_CITY_V_snowman_2"] = "¿Hay forjas por aquí? Me quedo en mitad de la calle.",
	["COMP_SAY_CITY_V_undead"] = "Una ciudad. Cuántos vivos. Pasaré desapercibido.",
	["COMP_SAY_CITY_V_undead_2"] = "%s… Conozco a gente enterrada aquí. Creo.",
	["COMP_SAY_COMBAT_SUM"] = "¡Uf! %d enemigos derrotados.",
	["COMP_SAY_COMBAT_SUM_2"] = "%d enemigos derrotados. ¿Recuperas el aliento?",
	["COMP_SAY_COMBAT_SUM_3"] = "¡Van %d! Los conté todos, bien protegido detrás de ti.",
	["COMP_SAY_COMBAT_SUM_DEAD"] = "%s no llegó al final. ¿Lo ayudamos a levantarse?",
	["COMP_SAY_COMBAT_SUM_NET"] = "%d derrotados. La red espera: %d por capturar.",
	["COMP_SAY_COMBAT_SUM_NEW"] = "¡%d enemigos derrotados, y algo nuevo para el diario!",
	["COMP_SAY_COMBAT_V_gfw"] = "¡Jo, jo! Menuda trifulca. No vi nada: reparto a todo el mundo.",
	["COMP_SAY_COMBAT_V_gfw_2"] = "Todos a la lista de traviesos. Me quedo sin tinta.",
	["COMP_SAY_COMBAT_V_metzen"] = "Pelea terminada. Tiempo decente, mejorable.",
	["COMP_SAY_COMBAT_V_metzen_2"] = "Y listo. Ni un rasguño en el trineo.",
	["COMP_SAY_COMBAT_V_snowman"] = "¿Ya acabó? Tenía los ojos cerrados. Bueno, mis piedrecitas.",
	["COMP_SAY_COMBAT_V_snowman_2"] = "Las peleas dan calor. He encogido un poco.",
	["COMP_SAY_CONVO_1"] = "¿Sabes cuál es mi parte favorita de la aventura?",
	["COMP_SAY_CONVO_10"] = "Gracias por llevarme a todas partes.",
	["COMP_SAY_CONVO_10_2"] = "De verdad. El mejor viaje de mi vida.",
	["COMP_SAY_CONVO_11"] = "¿Sabes cuántas veces has muerto hoy?",
	["COMP_SAY_CONVO_11_2"] = "Yo sí. Llevo una libreta.",
	["COMP_SAY_CONVO_11_3"] = "Está casi llena.",
	["COMP_SAY_CONVO_12"] = "¿Por qué guardas esa bota vieja?",
	["COMP_SAY_CONVO_12_2"] = "¿Valor sentimental?",
	["COMP_SAY_CONVO_12_3"] = "Ah, no. Solo olvidaste venderla.",
	["COMP_SAY_CONVO_13"] = "Tengo una pregunta seria.",
	["COMP_SAY_CONVO_13_2"] = "¿Sabes de verdad adónde vamos?",
	["COMP_SAY_CONVO_13_3"] = "Lo que yo pensaba.",
	["COMP_SAY_CONVO_14"] = "¿Siempre corres así?",
	["COMP_SAY_CONVO_14_2"] = "¿Brazos abiertos, cabeza gacha?",
	["COMP_SAY_CONVO_14_3"] = "Es muy… heroico. Sí.",
	["COMP_SAY_CONVO_15"] = "Antes vi un conejo.",
	["COMP_SAY_CONVO_15_2"] = "Le dabas miedo.",
	["COMP_SAY_CONVO_15_3"] = "Bueno… creo que se estaba riendo.",
	["COMP_SAY_CONVO_16"] = "¿Te acuerdas del acantilado?",
	["COMP_SAY_CONVO_16_2"] = "Yo sí. Lo recordaré siempre.",
	["COMP_SAY_CONVO_17"] = "El cementerio preguntó por ti.",
	["COMP_SAY_CONVO_17_2"] = "Le dije que estabas bien.",
	["COMP_SAY_CONVO_17_3"] = "Por ahora.",
	["COMP_SAY_CONVO_18"] = "¿Echamos una carrera?",
	["COMP_SAY_CONVO_18_2"] = "Tú contra mí. Patitas contra piernas largas.",
	["COMP_SAY_CONVO_18_3"] = "Ya gané: te perdiste.",
	["COMP_SAY_CONVO_19"] = "¿Terminaste tu misión de los diez jabalíes?",
	["COMP_SAY_CONVO_19_2"] = "Que ya van tres días, ¿eh?",
	["COMP_SAY_CONVO_1_2"] = "¿Las vistas? ¿El tesoro?",
	["COMP_SAY_CONVO_1_3"] = "No: las pausas para merendar.",
	["COMP_SAY_CONVO_2"] = "¡Eh! ¡Te pillé! ¡Te toca!",
	["COMP_SAY_CONVO_20"] = "Te encontré un apodo.",
	["COMP_SAY_CONVO_20_2"] = "«El Héroe que se cae de los puentes».",
	["COMP_SAY_CONVO_20_3"] = "Suena bien, ¿no? ¿No? Me lo quedo igual.",
	["COMP_SAY_CONVO_2_2"] = "Ay, espera, se me olvidaba: corro muy despacio.",
	["COMP_SAY_CONVO_3"] = "Psst… tengo un secreto.",
	["COMP_SAY_CONVO_3_2"] = "Antes vi una ardilla.",
	["COMP_SAY_CONVO_3_3"] = "Eso es todo. Era una ardilla preciosa.",
	["COMP_SAY_CONVO_4"] = "¿Jugamos a «veo, veo»?",
	["COMP_SAY_CONVO_4_2"] = "Veo, veo… algo con patas.",
	["COMP_SAY_CONVO_4_3"] = "¡Era yo! Gané.",
	["COMP_SAY_CONVO_5"] = "¿Crees que somos los héroes de esta historia?",
	["COMP_SAY_CONVO_5_2"] = "Yo creo que sí.",
	["COMP_SAY_CONVO_5_3"] = "Tú eres el héroe. Yo, el adorable.",
	["COMP_SAY_CONVO_6"] = "¡Jiji, me hace cosquillas!",
	["COMP_SAY_CONVO_6_2"] = "¿Otra vez? No, espera… ¡sí, otra vez!",
	["COMP_SAY_CONVO_7"] = "Tuve un sueño rarísimo.",
	["COMP_SAY_CONVO_7_2"] = "Éramos gnomos que vendían sombreros.",
	["COMP_SAY_CONVO_7_3"] = "Tú eras buenísimo con los sombreros.",
	["COMP_SAY_CONVO_8"] = "¿Quieres oír mi canción?",
	["COMP_SAY_CONVO_8_2"] = "La la laaa… la.",
	["COMP_SAY_CONVO_8_3"] = "Gracias, gracias. Sin aplausos, que me sonrojo.",
	["COMP_SAY_CONVO_9"] = "¿Cuántos pasos llevamos hoy, dirías?",
	["COMP_SAY_CONVO_9_2"] = "Yo, doce mil.",
	["COMP_SAY_CONVO_9_3"] = "Patitas pequeñas, grandes viajes.",
	["COMP_SAY_DEAD"] = "Ay… Te espero, tómate tu tiempo.",
	["COMP_SAY_DEAD_10"] = "Vale. Digamos que era una táctica.",
	["COMP_SAY_DEAD_11"] = "Tranquilo, no vi nada. Bueno, lo vi todo.",
	["COMP_SAY_DEAD_12"] = "¿Trotecito al cementerio? Va bien para las piernas.",
	["COMP_SAY_DEAD_13"] = "Ay. El monstruo parece muy orgulloso de sí mismo.",
	["COMP_SAY_DEAD_14"] = "¿Una siesta? ¿No? Ah. Vale. Yo vigilo la bolsa.",
	["COMP_SAY_DEAD_15"] = "¡Pasa! Sobre todo a ti, pero pasa.",
	["COMP_SAY_DEAD_2"] = "Uy. Te cuido la bolsa, prometido.",
	["COMP_SAY_DEAD_3"] = "Le pasa a los mejores. Me quedo aquí.",
	["COMP_SAY_DEAD_4"] = "Respira… bueno, cuando puedas. Aquí estoy.",
	["COMP_SAY_DEAD_5"] = "Lo intentaremos otra vez, juntos. Tranquilo.",
	["COMP_SAY_DEAD_6"] = "Y plaf, al suelo. Te espero aquí, sin moverme, sin juzgar.",
	["COMP_SAY_DEAD_7"] = "¿Muerto? ¿Otra vez? Ya me sé el camino al cementerio.",
	["COMP_SAY_DEAD_8"] = "Al menos elegiste un sitio bonito para caer.",
	["COMP_SAY_DEAD_9"] = "¿El suelo parecía cómodo? Pregunto por mí.",
	["COMP_SAY_DEAD_V_beast"] = "¡No! ¡Levántate! ¡Te lameré la cara hasta que te muevas!",
	["COMP_SAY_DEAD_V_beast_2"] = "Me tumbo a tu lado. No me moveré. Prometido.",
	["COMP_SAY_DEAD_V_critter"] = "¡No, no, no! ¡Despierta! Mientras, me escondo bajo tu brazo.",
	["COMP_SAY_DEAD_V_critter_2"] = "Estás frío… Me quedo. Aunque tengo muchísimo miedo.",
	["COMP_SAY_DEAD_V_demon"] = "Has muerto. ¿Y tu alma? ¿Nadie la reclama? Solo pregunto.",
	["COMP_SAY_DEAD_V_demon_2"] = "Patético. Pero esperaré. No soy un monstruo. Bueno, un poco.",
	["COMP_SAY_DEAD_V_dragonkin"] = "Has muerto. Lo predije hace mil años. Más o menos.",
	["COMP_SAY_DEAD_V_dragonkin_2"] = "Vamos. Un dragón no llora. Espera. Date prisa.",
	["COMP_SAY_DEAD_V_elemental"] = "Tu aliento se detuvo. El viento te espera.",
	["COMP_SAY_DEAD_V_elemental_2"] = "Nada se pierde. Volverás. Yo me quedo aquí.",
	["COMP_SAY_DEAD_V_gfw"] = "¡Oh, no! ¡Arriba, arriba, que te pierdes el reparto de regalos!",
	["COMP_SAY_DEAD_V_gfw_2"] = "Te espero aquí. A los buenos siempre se les espera.",
	["COMP_SAY_DEAD_V_giant"] = "Tú… caer. ¿Yo llevarte? … ¿No? Yo esperar. Yo bueno esperando.",
	["COMP_SAY_DEAD_V_giant_2"] = "¡NO! … Perdón. Yo triste. Tristeza muy grande.",
	["COMP_SAY_DEAD_V_humanoid"] = "Ay. Les diré que luchaste como un león.",
	["COMP_SAY_DEAD_V_humanoid_2"] = "¡Caíste! Te cuido las cosas. Prometo no cotillear.",
	["COMP_SAY_DEAD_V_mechanical"] = "Operador desconectado. Iniciando procedimiento de recuperación.",
	["COMP_SAY_DEAD_V_mechanical_2"] = "Nota para luego: evitar lo que acabas de hacer.",
	["COMP_SAY_DEAD_V_metzen"] = "¡Arriba! Un reno nunca abandona a su conductor.",
	["COMP_SAY_DEAD_V_metzen_2"] = "Hago guardia. Nadie toca a mi equipo.",
	["COMP_SAY_DEAD_V_snowman"] = "¡No! ¡Levántate! ¡Te doy mi bufanda!",
	["COMP_SAY_DEAD_V_snowman_2"] = "Me quedo aquí. No me moveré. Total, tampoco puedo.",
	["COMP_SAY_DEAD_V_undead"] = "Has muerto. Aquí es normal. Tranquilo, se pasa.",
	["COMP_SAY_DEAD_V_undead_2"] = "No te muevas, vigilo tu cuerpo. Tengo práctica.",
	["COMP_SAY_DEAD__cuddly"] = "No… me quedo a tu lado, sin moverme.",
	["COMP_SAY_DEAD__cuddly_2"] = "Te espero aquí. Vuelve pronto, ya te echo de menos.",
	["COMP_SAY_DEAD__cuddly_3"] = "Oh, no… ¿te has hecho daño? Sana, sana…",
	["COMP_SAY_DEAD__cuddly_4"] = "Te guardo el sitio calentito. No te pierdas al volver.",
	["COMP_SAY_DEAD__cuddly_5"] = "Te caíste… te quiero igual. Sobre todo ahora.",
	["COMP_SAY_DEAD__cuddly_6"] = "Ve por el camino corto, ¿vale? No como siempre.",
	["COMP_SAY_DEAD__cuddly_7"] = "No estoy llorando. Es la lluvia. No está lloviendo.",
	["COMP_SAY_DEAD__cuddly_8"] = "Vuelve pronto, te tengo un abrazo guardado.",
	["COMP_SAY_DEAD__curious"] = "¡Oh! ¿Así que eso es el otro lado? ¡Cuéntame!",
	["COMP_SAY_DEAD__curious_2"] = "Ay… ¿Al menos viste algo bonito?",
	["COMP_SAY_DEAD__curious_3"] = "¿Otra vez? ¿Estás investigando el cementerio o qué?",
	["COMP_SAY_DEAD__curious_4"] = "Interesante… ¿intentaste matarlo con la cara?",
	["COMP_SAY_DEAD__curious_5"] = "Oye, ¿está lejos el cementerio? Ya te sabes el camino, ¿no?",
	["COMP_SAY_DEAD__curious_6"] = "¿Cómo te caes desde tan alto? No, no me lo enseñes.",
	["COMP_SAY_DEAD__curious_7"] = "Tomo nota. Lección uno: no hagas lo que hiciste.",
	["COMP_SAY_DEAD__curious_8"] = "¿Por qué estás todo gris? ¿Es una nueva moda?",
	["COMP_SAY_DEAD__daring"] = "Luchamos como héroes. ¡Revancha!",
	["COMP_SAY_DEAD__daring_2"] = "Golpe de suerte. La próxima es nuestra.",
	["COMP_SAY_DEAD__daring_3"] = "Cargar contra seis tú solo fue audaz. Y tonto. ¡Pero audaz!",
	["COMP_SAY_DEAD__daring_4"] = "Muerto con honor… ante un jabalí. No se lo diremos a nadie.",
	["COMP_SAY_DEAD__daring_5"] = "¿Te retiraste? No, caíste. Mejor para el honor.",
	["COMP_SAY_DEAD__daring_6"] = "Esta vez hiciste bien en cargar. El que se equivocó fue el monstruo.",
	["COMP_SAY_DEAD__daring_7"] = "¿El cementerio, otra vez? ¿Ahora haces turismo allí?",
	["COMP_SAY_DEAD__daring_8"] = "Los héroes caen hacia delante. Tú, de lado. Lo trabajaremos.",
	["COMP_SAY_DEAD__fearful"] = "¡CLOC! ¡Lo sabía, lo sabía!",
	["COMP_SAY_DEAD__fearful_2"] = "¡Te dije que era demasiado grande! ¡Cloc! ¡Te lo dije!",
	["COMP_SAY_DEAD__fearful_3"] = "¿Otra vez? Pronto te sabrás el camino al cementerio de memoria.",
	["COMP_SAY_DEAD__fearful_4"] = "No me dejes solo aquí… hay ruidos por todas partes.",
	["COMP_SAY_DEAD__fearful_5"] = "Yo… vigilo tu cuerpo. De lejos. Tu cuerpo me da un poco de miedo.",
	["COMP_SAY_DEAD__fearful_6"] = "Cloc cloc cloc… respira, gallina, respira. Ya volverá.",
	["COMP_SAY_DEAD__fearful_7"] = "Corriste hacia el peligro. Otra vez. ¿Por qué siempre haces eso?",
	["COMP_SAY_DEAD__glutton"] = "Ay… te cuido la bolsa. Y el bocadillo.",
	["COMP_SAY_DEAD__glutton_2"] = "Caíste con el estómago vacío. Te lo dije: ¡primero se come!",
	["COMP_SAY_DEAD__glutton_3"] = "Otra vez al suelo… Entonces, ¿me termino tu bocadillo?",
	["COMP_SAY_DEAD__glutton_4"] = "Mientras corres al cementerio, yo vigilo la comida. De cerca.",
	["COMP_SAY_DEAD__glutton_5"] = "¿Muerto de hambre? No, solo muerto. No es mejor.",
	["COMP_SAY_DEAD__glutton_6"] = "Uy. Tu queso y yo te esperamos. Bueno, sobre todo yo.",
	["COMP_SAY_DEAD__glutton_7"] = "Si te hubieras tomado la sopa, habrías aguantado. Es ciencia.",
	["COMP_SAY_DEAD__lazy"] = "Tumbado en el suelo… Te entiendo, es relajante.",
	["COMP_SAY_DEAD__lazy_2"] = "¡Por fin te tumbas! Así no, pero es un comienzo.",
	["COMP_SAY_DEAD__lazy_3"] = "El cementerio queda lejos… ¿te espero aquí? ¿Sí? Perfecto.",
	["COMP_SAY_DEAD__lazy_4"] = "Corriste hacia el peligro. Yo nunca corro. ¿Ves?",
	["COMP_SAY_DEAD__lazy_5"] = "Todo ese camino de vuelta como fantasma… solo de pensarlo me canso.",
	["COMP_SAY_DEAD__lazy_6"] = "¿Otra vez en el suelo? Me estás copiando, ¿verdad?",
	["COMP_SAY_DEAD__lazy_7"] = "¿Ves lo que pasa por ir con prisas? Solo digo…",
	["COMP_SAY_DEAD__mischievous"] = "¡Uy! Eso no era una broma…",
	["COMP_SAY_DEAD__mischievous_2"] = "Jiji… eh, no, no tiene gracia. Bueno, un poquito.",
	["COMP_SAY_DEAD__mischievous_3"] = "¿Una siesta en el suelo? ¡Qué atrevido!",
	["COMP_SAY_DEAD__mischievous_4"] = "Mientras corres al cementerio, le pinto un bigote a tu cuerpo.",
	["COMP_SAY_DEAD__mischievous_5"] = "¿Otra vez? Ya tienes tarjeta de cliente del cementerio.",
	["COMP_SAY_DEAD__mischievous_6"] = "Caíste con estilo. Bueno… caíste.",
	["COMP_SAY_DEAD__mischievous_7"] = "Mientras, te reviso los bolsillos. ¡Para protegerlos! Prometido.",
	["COMP_SAY_DEAD__mischievous_8"] = "¿Digo que era una broma? Nadie se lo va a creer.",
	["COMP_SAY_DEAD__mystic"] = "El velo es fino aquí… vuelve a la luz.",
	["COMP_SAY_DEAD__mystic_2"] = "Los espíritus aún se ríen de tu caída. Con cariño.",
	["COMP_SAY_DEAD__mystic_3"] = "Lo leí en las estrellas. Tú no leíste las estrellas.",
	["COMP_SAY_DEAD__mystic_4"] = "El velo te acoge… otra vez. Ya sabe tu nombre.",
	["COMP_SAY_DEAD__mystic_5"] = "Sigue la luz… no, la otra. Hacia tu cuerpo. Ahí.",
	["COMP_SAY_DEAD__mystic_6"] = "Mal presagio confirmado. Odio tener razón.",
	["COMP_SAY_DEAD__mystic_7"] = "El guardián del cementerio me dijo: «¿Otra vez este?»",
	["COMP_SAY_DEAD__parrot"] = "¡Ay! ¡Ay! Craac… ¡Te espero! ¡Te espero!",
	["COMP_SAY_DEAD__parrot_2"] = "¡Muerto! ¡Muerto! ¡Otra vez! ¡Craac!",
	["COMP_SAY_DEAD__parrot_3"] = "¡Cementerio! ¡Cementerio! ¡Te lo sabes! ¡Te lo sabes!",
	["COMP_SAY_DEAD__parrot_4"] = "¡Uy! ¡Uy! ¡Lorito lo vio! ¡Lorito lo contará!",
	["COMP_SAY_DEAD__parrot_5"] = "¡Al suelo! ¡Al suelo! ¡Craac!",
	["COMP_SAY_DEAD__parrot_6"] = "¡Fantasma! ¡Fantasma! ¡Corre! ¡Corre!",
	["COMP_SAY_DEAD__parrot_7"] = "Craac… mal… mal… ¡vuelve!",
	["COMP_SAY_DEAD__sly"] = "Sss… eso no estaba previsto. Cambiamos de táctica.",
	["COMP_SAY_DEAD__sly_2"] = "Sss… mala inversión, ese combate.",
	["COMP_SAY_DEAD__sly_3"] = "Muerto, y las reparaciones costarán una fortuna. Sss.",
	["COMP_SAY_DEAD__sly_4"] = "Nadie te vio caer. Bueno, salvo yo. Y el jabalí.",
	["COMP_SAY_DEAD__sly_5"] = "Te guardo el oro. Para protegerlo. Solo eso.",
	["COMP_SAY_DEAD__sly_6"] = "Imprevisto. Actualizo el plan: «evitar osos».",
	["COMP_SAY_DEAD__sly_7"] = "Cargaste sin pensar. Otra vez. Tomo nota.",
	["COMP_SAY_DEAD__teasing"] = "¡Uy! Esta se la cuento a todo el mundo.",
	["COMP_SAY_DEAD__teasing_10"] = "Lo vi todo. Hasta tomé apuntes.",
	["COMP_SAY_DEAD__teasing_2"] = "Enhorabuena, ganaste… un viaje solo de ida al cementerio.",
	["COMP_SAY_DEAD__teasing_3"] = "El cementerio está por ahí. Ya te sabes el camino.",
	["COMP_SAY_DEAD__teasing_4"] = "Ah, tumbado boca abajo. Tu postura favorita.",
	["COMP_SAY_DEAD__teasing_5"] = "¿Comprobando si el suelo era cómodo? ¿Y bien?",
	["COMP_SAY_DEAD__teasing_6"] = "No diré nada. Bueno, no a todo el mundo.",
	["COMP_SAY_DEAD__teasing_7"] = "Tranquilo, el ángel del cementerio ya te conoce.",
	["COMP_SAY_DEAD__teasing_8"] = "Caída soberbia. Nota técnica: 9 sobre 10.",
	["COMP_SAY_DEAD__teasing_9"] = "De fantasma corres más rápido, aprovecha.",
	["COMP_SAY_DEAD__tinker"] = "¡Avería total! Tranquilo, conozco a un mecánico.",
	["COMP_SAY_DEAD__tinker_2"] = "Error crítico: héroe fuera de servicio. Reiniciando en el cementerio.",
	["COMP_SAY_DEAD__tinker_3"] = "Diagnóstico: demasiados enemigos, poco cerebro. Es broma. En parte.",
	["COMP_SAY_DEAD__tinker_4"] = "¡Sin batería! ¿Viste tu barra de salud? Parpadeaba.",
	["COMP_SAY_DEAD__tinker_5"] = "Lo apunto en el libro de mantenimiento: muerte n.º… perdí la cuenta.",
	["COMP_SAY_DEAD__tinker_6"] = "Clonc. Ese fue el ruido de tu caída. Muy mecánico.",
	["COMP_SAY_DEAD__tinker_7"] = "Tranquilo, la garantía cubre las vueltas desde el cementerio.",
	["COMP_SAY_DEAD__wise"] = "Caer no es nada. Levantarse lo es todo.",
	["COMP_SAY_DEAD__wise_2"] = "El suelo enseña humildad. Tú recibes muchas lecciones.",
	["COMP_SAY_DEAD__wise_3"] = "Quien carga con la cabeza gacha acaba viendo el suelo de cerca.",
	["COMP_SAY_DEAD__wise_4"] = "Conoces el camino al cementerio mejor que yo.",
	["COMP_SAY_DEAD__wise_5"] = "Hu. El fracaso es un maestro. Tú, su alumno más aplicado.",
	["COMP_SAY_DEAD__wise_6"] = "La sabiduría nace de la experiencia. Tú acumulas mucha.",
	["COMP_SAY_DEAD__wise_7"] = "El arroyo rodea la piedra. Tú te la comes.",
	["COMP_SAY_DEAD__zen"] = "Todo pasa. Incluso esto.",
	["COMP_SAY_DEAD__zen_2"] = "Todo pasa. Tú pasas mucho por aquí.",
	["COMP_SAY_DEAD__zen_3"] = "Caer es parte del camino. Tu camino tiene muchas caídas.",
	["COMP_SAY_DEAD__zen_4"] = "Respira… ah. No. Luego, entonces.",
	["COMP_SAY_DEAD__zen_5"] = "El suelo está en calma. Tú también, ahora. Por fin.",
	["COMP_SAY_DEAD__zen_6"] = "No te juzgues. El jabalí ya lo hizo.",
	["COMP_SAY_DEAD__zen_7"] = "El cementerio no está lejos. Camina despacio, sin prisa.",
	["COMP_SAY_DEPART"] = "¡En marcha! Vi la merienda en tu bolsa.",
	["COMP_SAY_DEPART_10"] = "¡Salimos! Avisé al cementerio, te guardan el sitio calentito.",
	["COMP_SAY_DEPART_11"] = "Bolsas listas, botas atadas… ¿casco del derecho? Casi.",
	["COMP_SAY_DEPART_12"] = "¡Adelante! El mundo es grande y puedes perderte en cualquier parte.",
	["COMP_SAY_DEPART_2"] = "¡A la aventura! Yo guío… no, tú primero.",
	["COMP_SAY_DEPART_3"] = "Bolsas listas, corazón ligero: ¡vamos!",
	["COMP_SAY_DEPART_4"] = "Me encanta el momento de salir de la ciudad.",
	["COMP_SAY_DEPART_5"] = "¡En camino! Qué ganas de ver lo que hay ahí fuera.",
	["COMP_SAY_DEPART_6"] = "¡Vamos! Intenta volver con tantas vidas como al salir.",
	["COMP_SAY_DEPART_7"] = "¡En marcha! Y esta vez miramos el mapa, ¿vale?",
	["COMP_SAY_DEPART_8"] = "¡Allá vamos! Apuesto a que mueres antes de la colina.",
	["COMP_SAY_DEPART_9"] = "¡Vamos! Yo delante, tú detrás… ah, no, tú eres el que pega.",
	["COMP_SAY_DRINK"] = "¡Glu glu! El agua es vida.",
	["COMP_SAY_DRINK_10"] = "¡Salud! A tu salud. Le hace falta.",
	["COMP_SAY_DRINK_2"] = "¡Un sorbito y seguimos!",
	["COMP_SAY_DRINK_3"] = "Tú bebes, yo miro. Es mi trabajo.",
	["COMP_SAY_DRINK_4"] = "¡Qué fresco! Guarda agua para el camino.",
	["COMP_SAY_DRINK_5"] = "Glu glu. Bebes como un jabalí, ¿sabes?",
	["COMP_SAY_DRINK_6"] = "¡Agua! Estabas seco, se notaba.",
	["COMP_SAY_DRINK_7"] = "Bebe despacio, que te dará hipo.",
	["COMP_SAY_DRINK_8"] = "Un sorbo para ti, otro para… ah, te lo bebiste todo.",
	["COMP_SAY_DRINK_9"] = "¿Recargando maná? ¿O haciendo como que estás ocupado?",
	["COMP_SAY_DUNGEON"] = "%s… Huele a humedad y a problemas.",
	["COMP_SAY_DUNGEON_2"] = "¡Una mazmorra! Quédate detrás de mí. Bueno, delante. Sobre todo delante.",
	["COMP_SAY_DUNGEON_3"] = "¿Entramos? Vale. Voy contando las salidas, por si acaso.",
	["COMP_SAY_DUNGEON_4"] = "%s. He oído historias. Ninguna acaba bien.",
	["COMP_SAY_DUNGEON_V_beast"] = "Una guarida. Algo grande duerme al fondo. Lo huelo.",
	["COMP_SAY_DUNGEON_V_beast_2"] = "%s… Apesta a miedo y a ratas. Vamos en manada.",
	["COMP_SAY_DUNGEON_V_critter"] = "Está oscuro. Hace frío. Gotea. No me gusta nada.",
	["COMP_SAY_DUNGEON_V_critter_2"] = "¿%s? El nombre da miedo. ¿Solo miramos la puerta?",
	["COMP_SAY_DUNGEON_V_demon"] = "¡Una mazmorra! Huele a azufre. Por fin un sitio civilizado.",
	["COMP_SAY_DUNGEON_V_demon_2"] = "%s… Conozco al arquitecto. Me debe dinero.",
	["COMP_SAY_DUNGEON_V_dragonkin"] = "Una mazmorra. El mejor tesoro duerme al fondo. Adelante.",
	["COMP_SAY_DUNGEON_V_dragonkin_2"] = "%s. Una cueva de dragón, pero con menos prestigio.",
	["COMP_SAY_DUNGEON_V_elemental"] = "Bajo tierra. Aquí la roca respira despacio. Escucha.",
	["COMP_SAY_DUNGEON_V_elemental_2"] = "%s… El aire pesa. Algo ha alterado los elementos.",
	["COMP_SAY_DUNGEON_V_gfw"] = "Mis renos no entran aquí. Estoy acostumbrado, le he llevado regalos a Ragnaros.",
	["COMP_SAY_DUNGEON_V_gfw_2"] = "%s… Aquí nadie está en la lista de los buenos. Nadie.",
	["COMP_SAY_DUNGEON_V_gfw_3"] = "Ni chimenea ni árbol. ¿Quién podría vivir en un sitio así?",
	["COMP_SAY_DUNGEON_V_giant"] = "Techo bajo. Yo darme en cabeza. Ya dos veces.",
	["COMP_SAY_DUNGEON_V_giant_2"] = "%s… oscuro. Eco de mi voz. ¡HOLA! … Uy.",
	["COMP_SAY_DUNGEON_V_humanoid"] = "¡Una mazmorra! Antorcha, cuerda, valor. Nos falta la cuerda.",
	["COMP_SAY_DUNGEON_V_humanoid_2"] = "%s… He oído historias de terror de este sitio. ¡Genial!",
	["COMP_SAY_DUNGEON_V_mechanical"] = "Mazmorra detectada. Modo prudencia activado. Modo valor: opcional.",
	["COMP_SAY_DUNGEON_V_mechanical_2"] = "%s: humedad alta, iluminación cero. Mis engranajes ya lo odian.",
	["COMP_SAY_DUNGEON_V_metzen"] = "¿%s? Me niego a poner una pezuña ahí. Vale. Una pezuña.",
	["COMP_SAY_DUNGEON_V_metzen_2"] = "Sin cielo, sin pista de despegue. Ya odio este sitio.",
	["COMP_SAY_DUNGEON_V_metzen_3"] = "Mi nariz ilumina el pasillo. Ya me darás las gracias.",
	["COMP_SAY_DUNGEON_V_snowman"] = "Está oscuro… y húmedo. Lo húmedo es mala señal.",
	["COMP_SAY_DUNGEON_V_snowman_2"] = "¿%s? ¿Hay fuego ahí dentro? Dime que no hay fuego.",
	["COMP_SAY_DUNGEON_V_snowman_3"] = "Tengo miedo, pero soy todo blanco: no se nota que palidezco.",
	["COMP_SAY_DUNGEON_V_undead"] = "¡Una mazmorra! Oscura, húmeda, llena de ecos. Como en casa.",
	["COMP_SAY_DUNGEON_V_undead_2"] = "%s. Huele a cripta. Me encantan las criptas.",
	["COMP_SAY_EAT"] = "¡Ñam! Gracias por compartir.",
	["COMP_SAY_EAT_10"] = "¡Crujiente! ¿Es pan o una galleta vieja del fondo de tu bolsa?",
	["COMP_SAY_EAT_11"] = "Tómate tu tiempo, el próximo monstruo no tiene prisa. Yo tampoco.",
	["COMP_SAY_EAT_12"] = "Tienes migas por todas partes. ¿Me las das?",
	["COMP_SAY_EAT_13"] = "¡Que aproveche! ¿Cuántos años tiene ese queso?",
	["COMP_SAY_EAT_14"] = "¡Pausa para comer! Así admiro tu armadura… manchada.",
	["COMP_SAY_EAT_2"] = "¡Qué bien huele! ¿Me guardas una miga?",
	["COMP_SAY_EAT_3"] = "¡Pausa para merendar! Mi favorita.",
	["COMP_SAY_EAT_4"] = "Come bien, nos quedan leguas por delante.",
	["COMP_SAY_EAT_5"] = "Mmm… ¿está rico? Tiene pinta de estar rico.",
	["COMP_SAY_EAT_6"] = "Comer juntos es más divertido.",
	["COMP_SAY_EAT_7"] = "¿Comer sentado en el suelo? Qué elegancia.",
	["COMP_SAY_EAT_8"] = "¿Otra pausa para comer? ¡Comes más que yo!",
	["COMP_SAY_EAT_9"] = "Come, come. Así tardarás más en caerte.",
	["COMP_SAY_EAT_V_beast"] = "¡Huele bien! ¿Un bocado para mí? ¿Uno pequeñito?",
	["COMP_SAY_EAT_V_beast_2"] = "Vigilo mientras comes. Nada se acerca.",
	["COMP_SAY_EAT_V_beast_3"] = "Descanso de la manada. Doy tres vueltas y me tumbo.",
	["COMP_SAY_EAT_V_critter"] = "¿Una miga? ¿Una miguita chiquitita? ¿Para mí?",
	["COMP_SAY_EAT_V_critter_2"] = "¡Hora de descansar! Me acurruco en tu capucha.",
	["COMP_SAY_EAT_V_critter_3"] = "Come bien. Yo con una semilla tengo para una semana.",
	["COMP_SAY_EAT_V_demon"] = "¿Comes eso? En mi tierra, la comida grita.",
	["COMP_SAY_EAT_V_demon_2"] = "Descansa. Yo vigilo. Siempre vigilo.",
	["COMP_SAY_EAT_V_demon_3"] = "Que aproveche. Yo me conformo con tu miedo. Está delicioso.",
	["COMP_SAY_EAT_V_dragonkin"] = "¿Eso es todo lo que comes? Yo me zamparía una oveja entera.",
	["COMP_SAY_EAT_V_dragonkin_2"] = "Descansa. Te guardaré, como a mi oro.",
	["COMP_SAY_EAT_V_dragonkin_3"] = "¿Al fuego de leña? Aficionado. El fuego de dragón es otra cosa.",
	["COMP_SAY_EAT_V_elemental"] = "Come. La tierra ofrece lo que tiene. Agradéceselo.",
	["COMP_SAY_EAT_V_elemental_2"] = "El descanso es un río tranquilo. Déjate llevar.",
	["COMP_SAY_EAT_V_elemental_3"] = "Bebe. El agua recuerda a todos los que ha saciado.",
	["COMP_SAY_EAT_V_gfw"] = "¿Una galleta? Los renos se quedan las zanahorias, yo las galletas.",
	["COMP_SAY_EAT_V_gfw_2"] = "Come. Una noche de repartos da mucha hambre.",
	["COMP_SAY_EAT_V_giant"] = "Tú comer miga. Yo comer árbol. Cada uno su gusto.",
	["COMP_SAY_EAT_V_giant_2"] = "Pausa. Yo amar pausas. Yo muy bueno en pausas.",
	["COMP_SAY_EAT_V_giant_3"] = "Descanso… Yo sentar. … Uy. Ya no hay roca.",
	["COMP_SAY_EAT_V_humanoid"] = "¡Hora de comer! Cuéntame algo mientras comes.",
	["COMP_SAY_EAT_V_humanoid_2"] = "Nada como una buena pausa. Los grandes aventureros duermen la siesta.",
	["COMP_SAY_EAT_V_humanoid_3"] = "¿Te queda queso? Para mí, digo. Para mí.",
	["COMP_SAY_EAT_V_mechanical"] = "Recargando. Tú también, por lo visto.",
	["COMP_SAY_EAT_V_mechanical_2"] = "Pausa detectada. Aprovecho para engrasarme las juntas.",
	["COMP_SAY_EAT_V_mechanical_3"] = "Combustible orgánico: elección rara, pero eficaz.",
	["COMP_SAY_EAT_V_metzen"] = "¿Una zanahoria? ¿No? Liquen, entonces. No soy exigente.",
	["COMP_SAY_EAT_V_metzen_2"] = "Come rápido. Tenemos un horario que cumplir.",
	["COMP_SAY_EAT_V_snowman"] = "¿Eso está caliente? Cómetelo un poco más lejos, por favor.",
	["COMP_SAY_EAT_V_snowman_2"] = "Yo solo como copos de nieve. Se derriten en mi carbón.",
	["COMP_SAY_EAT_V_undead"] = "¿Comes? Te miro. Ya no tengo estómago, pero tengo recuerdos.",
	["COMP_SAY_EAT_V_undead_2"] = "Descansa. Yo nunca duermo de verdad. Finjo.",
	["COMP_SAY_EAT_V_undead_3"] = "Buen provecho. Evita la carne pasada, me hiere los sentimientos.",
	["COMP_SAY_EAT__cuddly"] = "Comer juntos sabe todavía mejor.",
	["COMP_SAY_EAT__cuddly_2"] = "¿Comemos? Un bocado para ti, otro para mí.",
	["COMP_SAY_EAT__cuddly_3"] = "Come despacio, que te dará hipo.",
	["COMP_SAY_EAT__cuddly_4"] = "Tienes salsa en la barbilla. Qué mono.",
	["COMP_SAY_EAT__cuddly_5"] = "Comer juntos es el mejor momento.",
	["COMP_SAY_EAT__cuddly_6"] = "¿Otra vez picoteando? Vale, no digo nada. Comparto.",
	["COMP_SAY_EAT__cuddly_7"] = "Te hago compañía. Y vigilo las migas.",
	["COMP_SAY_EAT__curious"] = "¿Qué plato es ese? ¿De dónde es?",
	["COMP_SAY_EAT__curious_2"] = "¡Ñam! ¿Crees que lo venden en otro sitio?",
	["COMP_SAY_EAT__curious_3"] = "¿Qué comes? ¿A qué sabe? ¿Puedo olerlo?",
	["COMP_SAY_EAT__curious_4"] = "¿Es el pan de hace tres zonas? ¿Aún aguanta?",
	["COMP_SAY_EAT__curious_5"] = "¿Por qué comemos en el suelo? En las ciudades hay sillas, ¿sabes?",
	["COMP_SAY_EAT__curious_6"] = "Siempre comes lo mismo. ¿Has probado otra cosa?",
	["COMP_SAY_EAT__curious_7"] = "¿De dónde es ese queso? ¿Y por qué está verde?",
	["COMP_SAY_EAT__curious_8"] = "¡Pausa para comer! ¿Me cuentas la receta? ¿No la sabes?",
	["COMP_SAY_EAT__daring"] = "¡Un bocado rápido y de vuelta a la batalla!",
	["COMP_SAY_EAT__daring_2"] = "Come rápido, el enemigo no hace pausas para merendar.",
	["COMP_SAY_EAT__daring_3"] = "Un bocado de héroe y a seguir. No tres.",
	["COMP_SAY_EAT__daring_4"] = "Comes como si fuera tu última comida. Viendo cómo cargas…",
	["COMP_SAY_EAT__daring_5"] = "¡Fuerzas para la próxima batalla! Empieza en diez segundos.",
	["COMP_SAY_EAT__daring_6"] = "Come. Un guerrero con hambre pega flojo. Como tú esta mañana.",
	["COMP_SAY_EAT__daring_7"] = "¿Pausa para comer? Vale, pero de pie, como los valientes.",
	["COMP_SAY_EAT__fearful"] = "¿Comemos? Buena idea, recuperemos fuerzas. Por si acaso.",
	["COMP_SAY_EAT__fearful_2"] = "¡Come rápido, estamos al descubierto! Bueno, pero mastica bien.",
	["COMP_SAY_EAT__fearful_3"] = "¿Comer en el suelo, rodeados de monstruos? Qué valor.",
	["COMP_SAY_EAT__fearful_4"] = "Guárdame una miga. Los nervios me dan hambre.",
	["COMP_SAY_EAT__fearful_5"] = "¿Al menos está bien hecho? También me preocupa tu barriga.",
	["COMP_SAY_EAT__fearful_6"] = "Mientras comes, vigilo. Nada que informar. Por ahora.",
	["COMP_SAY_EAT__fearful_7"] = "Eso no es pollo, ¿verdad? Dime que no es pollo.",
	["COMP_SAY_EAT__glutton"] = "¡Por fin! ¡Pensaba que nunca ibas a comer!",
	["COMP_SAY_EAT__glutton_2"] = "¡Ñam ñam ñam! ¿La mitad para mí?",
	["COMP_SAY_EAT__glutton_3"] = "Huele tan bien… se me cae la baba, perdón.",
	["COMP_SAY_EAT__glutton_4"] = "¿Pan seco? ¿La mermelada es para los perros?",
	["COMP_SAY_EAT__glutton_5"] = "Masticas tan despacio… podría acabar yo antes. Déjame probar.",
	["COMP_SAY_EAT__glutton_6"] = "¿Otra vez esa manzana vieja? La llevas encima desde hace tres zonas.",
	["COMP_SAY_EAT__glutton_7"] = "¡Ñam! ¿Me dejas una miga? ¿Una miga grande?",
	["COMP_SAY_EAT__glutton_8"] = "¿Comiendo sin mí? Ah, no, estoy aquí. Uf.",
	["COMP_SAY_EAT__glutton_9"] = "Tú comes como un pajarito. Yo como un ogro. Nos compensamos.",
	["COMP_SAY_EAT__lazy"] = "Comer sentado es una gloria.",
	["COMP_SAY_EAT__lazy_2"] = "¿Comer de pie? Siéntate. Aprende de mí.",
	["COMP_SAY_EAT__lazy_3"] = "Mastica despacio, así la pausa dura más.",
	["COMP_SAY_EAT__lazy_4"] = "¡Una comida! El único momento en que paras. Me encanta.",
	["COMP_SAY_EAT__lazy_5"] = "Toma otra rebanada. Una rebanada lleva su tiempo.",
	["COMP_SAY_EAT__lazy_6"] = "Ñam… ¿y luego una siestecita digestiva? Es por salud.",
	["COMP_SAY_EAT__lazy_7"] = "Comes tan rápido como caminas. Demasiado rápido.",
	["COMP_SAY_EAT__mischievous"] = "Le eché polvo de hada a tu comida. Solo un poquito.",
	["COMP_SAY_EAT__mischievous_2"] = "Cuidado, puede que le haya puesto guindilla. Puede. Jiji.",
	["COMP_SAY_EAT__mischievous_3"] = "¿Comiendo otra vez? Tu bolsa de comida está llorando.",
	["COMP_SAY_EAT__mischievous_4"] = "Una miga para mí, o te hago cosquillas en la nariz mientras masticas.",
	["COMP_SAY_EAT__mischievous_5"] = "¿Ese pan sabe a purpurina? No fui yo. Vale, fui yo.",
	["COMP_SAY_EAT__mischievous_6"] = "¡Mastica con la boca cerrada, glotón! Jiji.",
	["COMP_SAY_EAT__mischievous_7"] = "Cambié tu queso por una piedra. ¡Que no! ¿O sí…?",
	["COMP_SAY_EAT__mischievous_8"] = "¿Pícnic entre monstruos? Me encanta tu valor. O tu despiste.",
	["COMP_SAY_EAT__mystic"] = "Hasta los espíritus tienen hambre, a veces.",
	["COMP_SAY_EAT__mystic_2"] = "Leo el futuro en tus migas: más migas.",
	["COMP_SAY_EAT__mystic_3"] = "Esta sopa tiene un aura… de sopa.",
	["COMP_SAY_EAT__mystic_4"] = "Come. Los espíritus dicen que el próximo combate será largo.",
	["COMP_SAY_EAT__mystic_5"] = "Ese pan ha viajado mucho en tu bolsa. Demasiado.",
	["COMP_SAY_EAT__mystic_6"] = "Hasta los oráculos pican algo entre visiones.",
	["COMP_SAY_EAT__mystic_7"] = "Veo… una indigestión. No, es broma.",
	["COMP_SAY_EAT__parrot"] = "¡Ñam! ¡Ñam! ¿Una semilla? ¿Una semilla?",
	["COMP_SAY_EAT__parrot_2"] = "¡Crac! ¡Crac! ¡Migas! ¡Migas!",
	["COMP_SAY_EAT__parrot_3"] = "¡Otra vez comiendo! ¡Otra vez comiendo! ¡Craac!",
	["COMP_SAY_EAT__parrot_4"] = "¡Comparte! ¡Comparte! ¡Lorito tiene hambre!",
	["COMP_SAY_EAT__parrot_5"] = "¡Pan duro! ¡Puaj! ¡Puaj! ¡Craac!",
	["COMP_SAY_EAT__parrot_6"] = "¡Mastica! ¡Mastica! ¡No te lo tragues entero!",
	["COMP_SAY_EAT__parrot_7"] = "¡Glotón! ¡Glotón! ¡Craac!",
	["COMP_SAY_EAT__sly"] = "Come. Con el estómago vacío salen malos planes.",
	["COMP_SAY_EAT__sly_2"] = "¿Pan de un cobre? Sss… valemos más que eso.",
	["COMP_SAY_EAT__sly_3"] = "Come, pero no todo. Lo que sobre, lo revendemos.",
	["COMP_SAY_EAT__sly_4"] = "Yo habría regateado ese queso a mitad de precio.",
	["COMP_SAY_EAT__sly_5"] = "¿Comida gratis? Ah, no, la pagaste. Qué pena.",
	["COMP_SAY_EAT__sly_6"] = "Come rápido. Los vendedores cierran, el oro no espera.",
	["COMP_SAY_EAT__sly_7"] = "Guárdame una miga. Es mi tarifa por vigilarte.",
	["COMP_SAY_EAT__teasing"] = "¿Comiendo otra vez? Acabarás tan redondo como yo.",
	["COMP_SAY_EAT__teasing_2"] = "Comes como un ogro. Un ogro educado, pero ogro.",
	["COMP_SAY_EAT__teasing_3"] = "¿Otra pausa? Hemos dado diez pasos.",
	["COMP_SAY_EAT__teasing_4"] = "Acuérdate de masticar, ayuda.",
	["COMP_SAY_EAT__teasing_5"] = "¿El pan duro del fondo de la bolsa? Qué valiente.",
	["COMP_SAY_EAT__teasing_6"] = "Come. El próximo combate te lo agradecerá.",
	["COMP_SAY_EAT__teasing_7"] = "Tienes migas por todas partes. Por todas.",
	["COMP_SAY_EAT__teasing_8"] = "Comiendo en el suelo. Muy elegante.",
	["COMP_SAY_EAT__teasing_9"] = "Si lucharas tan bien como comes…",
	["COMP_SAY_EAT__tinker"] = "Tú comes, yo me pongo aceite. Glu.",
	["COMP_SAY_EAT__tinker_2"] = "Recargando… 10%%, 20%%… masticas despacio.",
	["COMP_SAY_EAT__tinker_3"] = "¿Pan duro? Mal combustible. Pero bueno, funciona.",
	["COMP_SAY_EAT__tinker_4"] = "Mientras comes, te ajusto las hebillas del cinturón. Mmm, justito.",
	["COMP_SAY_EAT__tinker_5"] = "Ingesta detectada. Migas detectadas. Por todas partes.",
	["COMP_SAY_EAT__tinker_6"] = "Te inventaré una tostadora portátil. Apenas explotará.",
	["COMP_SAY_EAT__tinker_7"] = "¡Repostando! Yo, con una gota de aceite, listo.",
	["COMP_SAY_EAT__wise"] = "Barriga llena, mente clara.",
	["COMP_SAY_EAT__wise_2"] = "Quien come deprisa digiere mal. Hu.",
	["COMP_SAY_EAT__wise_3"] = "El sabio come antes del hambre. Tú, después.",
	["COMP_SAY_EAT__wise_4"] = "Una comida es una pausa. Una siesta, otra.",
	["COMP_SAY_EAT__wise_5"] = "Come. Hasta los héroes tienen estómago.",
	["COMP_SAY_EAT__wise_6"] = "El pan de ayer también alimenta. El tuyo es muy antiguo.",
	["COMP_SAY_EAT__wise_7"] = "Mastica despacio, como quien lee un viejo tomo.",
	["COMP_SAY_EAT__zen"] = "Come despacio. Cada bocado cuenta.",
	["COMP_SAY_EAT__zen_2"] = "Mastica. Nadie te robará ese queso. Salvo yo, quizá.",
	["COMP_SAY_EAT__zen_3"] = "Una comida en silencio. Bueno, casi. Masticas fuerte.",
	["COMP_SAY_EAT__zen_4"] = "Come sentado. Correr comiendo es cosa de goblins.",
	["COMP_SAY_EAT__zen_5"] = "Cada bocado es un momento. Este, un momento de pan duro.",
	["COMP_SAY_EAT__zen_6"] = "Pausa para comer. La aventura esperará. Se le da bien.",
	["COMP_SAY_EAT__zen_7"] = "Ese pan ha visto tres zonas en tu bolsa. Hónralo.",
	["COMP_SAY_EVOLVE"] = "¡Estoy creciendo! ¡Ahora soy %s!",
	["COMP_SAY_EVOLVE_2"] = "¡Mírame! ¡Me estoy convirtiendo en %s!",
	["COMP_SAY_EVOLVE_3"] = "¡Creciendo! Ahora soy %s, gracias a ti.",
	["COMP_SAY_EVOLVE_4"] = "Nuevo yo: ¡%s! Estoy bastante guapo.",
	["COMP_SAY_EVOLVE_5"] = "¡Ahora soy %s! Tú no has cambiado. Qué tierno.",
	["COMP_SAY_EVOLVE_6"] = "¡%s! Crezco más rápido que tu sentido de la orientación.",
	["COMP_SAY_EVOLVE_7"] = "Tachán: ¡%s! Admírame. Tómate tu tiempo.",
	["COMP_SAY_EVOLVE_8"] = "¡Soy %s! Ahora puedo llevarte cuando te caigas.",
	["COMP_SAY_EVOLVE__cuddly"] = "¡Ahora soy %s! Gracias a ti. ¡Gracias, gracias!",
	["COMP_SAY_EVOLVE__cuddly_2"] = "¡Ahora soy %s! ¿Me sigues queriendo igual?",
	["COMP_SAY_EVOLVE__cuddly_3"] = "¡Me convierto en %s! Igual de achuchable, prometido.",
	["COMP_SAY_EVOLVE__cuddly_4"] = "¡%s! Más grande, pero aún quepo en tu regazo.",
	["COMP_SAY_EVOLVE__curious"] = "¡Estoy creciendo! ¡Ahora soy %s! ¡Veré aún más lejos!",
	["COMP_SAY_EVOLVE__curious_2"] = "¡Ahora soy %s! ¿Por qué me pica? ¿Es normal?",
	["COMP_SAY_EVOLVE__curious_3"] = "¡%s! ¿Crees que cambiaré otra vez? ¿Hasta dónde?",
	["COMP_SAY_EVOLVE__curious_4"] = "¡Me convierto en %s! Tú, en cambio, no has cambiado. Qué raro.",
	["COMP_SAY_EVOLVE__daring"] = "¡Ahora soy %s! ¡Que tiemblen los monstruos!",
	["COMP_SAY_EVOLVE__daring_2"] = "¡Ahora soy %s! Más músculo. Bueno, más pelo.",
	["COMP_SAY_EVOLVE__daring_3"] = "¡%s! A partir de ahora, te protejo yo. Casi.",
	["COMP_SAY_EVOLVE__daring_4"] = "¡Me convierto en %s! Que tiemblen los jabalíes. Los pequeños, al menos.",
	["COMP_SAY_EVOLVE__fearful"] = "¡Ahora soy %s! Más grande… ¿más valiente? Ya veremos.",
	["COMP_SAY_EVOLVE__fearful_2"] = "¡Ahora soy %s! Más grande… más fácil de ver para los lobos. Genial.",
	["COMP_SAY_EVOLVE__fearful_3"] = "¿Yo, %s? ¡Cloc! No me atrevo a mirar mis plumas nuevas.",
	["COMP_SAY_EVOLVE__fearful_4"] = "¡Me convierto en %s! Tú, en cambio, mueres igual. Ji… perdón.",
	["COMP_SAY_EVOLVE__glutton"] = "¡Estoy creciendo! ¡Ahora soy %s! Necesitaré raciones más grandes.",
	["COMP_SAY_EVOLVE__glutton_2"] = "¡Ahora soy %s! Más grande, más estómago. Lógico.",
	["COMP_SAY_EVOLVE__glutton_3"] = "¡%s! Crecer da hambre. ¿Queda pan?",
	["COMP_SAY_EVOLVE__glutton_4"] = "¡Me convierto en %s! Tus provisiones deberían preocuparse.",
	["COMP_SAY_EVOLVE__lazy"] = "Ahora soy %s… crecer cansa.",
	["COMP_SAY_EVOLVE__lazy_2"] = "Ahora soy %s… más grande, así que más peso que cargar. Uf.",
	["COMP_SAY_EVOLVE__lazy_3"] = "%s… Crecí durante la siesta. Eficiente.",
	["COMP_SAY_EVOLVE__lazy_4"] = "Me convierto en %s. ¿Hacemos una pausa para recuperarme?",
	["COMP_SAY_EVOLVE__mischievous"] = "¡Ahora soy %s! ¡Aún más purpurina!",
	["COMP_SAY_EVOLVE__mischievous_2"] = "¡Ahora soy %s! ¡Más grande, más sitio para bromas!",
