	["COMP_SAY_HELLO_V_demon"] = "He vuelto. Firmaste el contrato, recuerda. La letra pequeña.",
	["COMP_SAY_HELLO_V_demon_2"] = "Ah, mi mortal favorito. Bueno, el único que me alimenta.",
	["COMP_SAY_HELLO_V_demon_3"] = "¿Me invocaste? ¿No? He venido igual.",
	["COMP_SAY_HELLO_V_dragonkin"] = "Has vuelto. Bien. Te concedo mi presencia una vez más.",
	["COMP_SAY_HELLO_V_dragonkin_2"] = "Mortal. Yo dormí tres siglos. ¿Tú, tres horas? Débil.",
	["COMP_SAY_HELLO_V_dragonkin_3"] = "Inclínate ante tu dragón. Más. Ahí.",
	["COMP_SAY_HELLO_V_elemental"] = "El viento te trajo de vuelta. Siempre devuelve lo que importa.",
	["COMP_SAY_HELLO_V_elemental_2"] = "Te esperé como la piedra espera la lluvia. Sin prisa.",
	["COMP_SAY_HELLO_V_elemental_3"] = "Hola. Los elementos están en calma. Espero que tú también.",
	["COMP_SAY_HELLO_V_gfw"] = "¡Jo, jo, jo! ¿Te has portado bien este año? Los bichos que mataste no dirán nada.",
	["COMP_SAY_HELLO_V_gfw_2"] = "¡Aquí estoy! Aparqué el trineo detrás de la posada. No se lo digas al guardia.",
	["COMP_SAY_HELLO_V_gfw_3"] = "¡Jo, jo! Una ronda de regalos, y eres el primero de mi lista.",
	["COMP_SAY_HELLO_V_giant"] = "¡HOLA! … ¿Muy fuerte? Hola. Holita.",
	["COMP_SAY_HELLO_V_giant_2"] = "Tú… volver. Yo… feliz. Suelo… temblar un poco.",
	["COMP_SAY_HELLO_V_giant_3"] = "Yo esperar mucho tiempo. Rocas crecer. Tú por fin aquí.",
	["COMP_SAY_HELLO_V_humanoid"] = "¡Ahí estás! Tengo tres historias que contarte. No, cuatro.",
	["COMP_SAY_HELLO_V_humanoid_2"] = "Mochila lista, botas lustradas: ¡listo para la aventura! ¿Y tú?",
	["COMP_SAY_HELLO_V_humanoid_3"] = "¡Ah, mi compañero de viaje! La taberna estaba tan vacía sin ti.",
	["COMP_SAY_HELLO_V_mechanical"] = "Bip. Arranque completo. Todos los engranajes responden… menos uno, que está de morros.",
	["COMP_SAY_HELLO_V_mechanical_2"] = "Sistema en línea. Misión: seguirte. Submisión: no oxidarme.",
	["COMP_SAY_HELLO_V_mechanical_3"] = "Hola, operador. Batería al 100%%. Paciencia al 63%%.",
	["COMP_SAY_HELLO_V_metzen"] = "Metzen, reno de trineo. A un reno de trineo no se le hace esperar.",
	["COMP_SAY_HELLO_V_metzen_2"] = "¡Aquí estoy! Arnés pulido, pezuñas enceradas. ¿Vamos?",
	["COMP_SAY_HELLO_V_metzen_3"] = "Llegas tarde. Yo nunca. Es cuestión de profesionalidad.",
	["COMP_SAY_HELLO_V_snowman"] = "¡Hola! Soy nuevecito. Creo. ¿Nevó ayer?",
	["COMP_SAY_HELLO_V_snowman_2"] = "¡Hola! Conservé mi zanahoria. Es mi nariz, ¿sabes?",
	["COMP_SAY_HELLO_V_snowman_3"] = "¡Aquí estoy! Un poco torcido, pero de una pieza.",
	["COMP_SAY_HELLO_V_undead"] = "¡He vuelto! Bueno… lo que queda de mí.",
	["COMP_SAY_HELLO_V_undead_2"] = "Me despertaste. Por una vez descansaba en paz.",
	["COMP_SAY_HELLO_V_undead_3"] = "Buenas noticias: no perdí nada por el camino. Creo. Déjame contar mis huesos.",
	["COMP_SAY_HELLO__cuddly"] = "¡Hola! Soy %s. ¿Un abrazo para empezar?",
	["COMP_SAY_HELLO__cuddly_2"] = "¡%s está aquí! ¡Y muy feliz de verte!",
	["COMP_SAY_HELLO__cuddly_3"] = "¡Hola! Soy %s. Te eché de menos, aunque fuera un minuto.",
	["COMP_SAY_HELLO__cuddly_4"] = "¡%s está listo! Y mimoso, como siempre.",
	["COMP_SAY_HELLO__cuddly_5"] = "¡Hola, soy %s! ¿Vamos de la mano y la patita?",
	["COMP_SAY_HELLO__curious"] = "¡Hola! Soy %s. Entonces, ¿adónde vamos? ¿Por qué? ¿Y luego?",
	["COMP_SAY_HELLO__curious_2"] = "¡%s, a la orden! ¡Hay tanto que ver!",
	["COMP_SAY_HELLO__curious_3"] = "¡Hola! Soy %s. Pregunta del día: ¿sabes adónde vamos esta vez?",
	["COMP_SAY_HELLO__curious_4"] = "¡%s, listo para saberlo todo! ¿Y tú, listo para explicarlo todo?",
	["COMP_SAY_HELLO__curious_5"] = "¡Hola! %s, mil preguntas en reserva. ¿Tienes tiempo?",
	["COMP_SAY_HELLO__daring"] = "¡Hola! Soy %s. ¿Contra qué luchamos hoy?",
	["COMP_SAY_HELLO__daring_2"] = "¡%s, listo para la batalla! ¡Adelante!",
	["COMP_SAY_HELLO__daring_3"] = "¡Hola! Soy %s. Tú pegas, yo grito. ¿Trato?",
	["COMP_SAY_HELLO__daring_4"] = "¡%s, firme! ¿Calentaste? ¿No? Mala suerte, cargamos.",
	["COMP_SAY_HELLO__daring_5"] = "¡Eh, soy %s! Hoy evitamos el cementerio, ¿vale?",
	["COMP_SAY_HELLO__fearful"] = "¡H-h-hola! Soy %s. ¿Nos quedamos cerca de la posada?",
	["COMP_SAY_HELLO__fearful_2"] = "%s está aquí… bueno, detrás de ti. Es más seguro.",
	["COMP_SAY_HELLO__fearful_3"] = "H-hola… soy %s. No nos llevarás otra vez a ver a los grandes que dan miedo, ¿no?",
	["COMP_SAY_HELLO__fearful_4"] = "¡%s, aquí! Bueno… escondido detrás de tu pierna, pero aquí.",
	["COMP_SAY_HELLO__fearful_5"] = "¡Cloc! %s, a la orden. Preparé un plan de huida, por si acaso.",
	["COMP_SAY_HELLO__glutton"] = "¡Hola! Soy %s. ¿Hay merienda en esta aventura?",
	["COMP_SAY_HELLO__glutton_2"] = "¡%s, a tu servicio! ¿Qué comida llevas en la bolsa?",
	["COMP_SAY_HELLO__glutton_3"] = "¡Hola! %s, un estómago con patas. ¿Te acordaste de la merienda?",
	["COMP_SAY_HELLO__glutton_4"] = "¡%s, a la orden! ¿Toca desayunar ya?",
	["COMP_SAY_HELLO__glutton_5"] = "¡Hola! Soy %s. ¿Hueles a pan? ¿No? Qué pena.",
	["COMP_SAY_HELLO__lazy"] = "Hola… soy %s. No tenemos prisa, ¿verdad?",
	["COMP_SAY_HELLO__lazy_2"] = "%s… a tu servicio. ¿Después de una siestecita?",
	["COMP_SAY_HELLO__lazy_3"] = "Hola… soy %s. ¿Empezamos con una pausa?",
	["COMP_SAY_HELLO__lazy_4"] = "%s… presente. Más o menos. No corras mucho, ¿vale?",
	["COMP_SAY_HELLO__lazy_5"] = "Ñaaa… %s, a tu servicio. El servicio empieza después de la siesta.",
	["COMP_SAY_HELLO__mischievous"] = "¡Jiji! ¡Soy %s! ¿Quieres ver un truco de magia?",
	["COMP_SAY_HELLO__mischievous_2"] = "¡%s está aquí! ¡Cuidado, que va a brillar!",
	["COMP_SAY_HELLO__mischievous_3"] = "¡Jiji! ¡Soy %s! Te até los cordones juntos. ¡Buen viaje… y buen tropiezo!",
	["COMP_SAY_HELLO__mischievous_4"] = "¡%s está aquí! No mires en tu bolsa. Jiji. Por nada.",
	["COMP_SAY_HELLO__mischievous_5"] = "¡Tachán! ¡%s aparece en una nube de purpurina! ¿Toses? Perdón.",
	["COMP_SAY_HELLO__mystic"] = "Soy %s… las estrellas me guiaron hasta ti.",
	["COMP_SAY_HELLO__mystic_2"] = "%s… Siento que este viaje estaba escrito.",
	["COMP_SAY_HELLO__mystic_3"] = "Soy %s. Las cartas predijeron un viaje… y muchos rodeos.",
	["COMP_SAY_HELLO__mystic_4"] = "%s, a tu servicio. Los espíritus ya apuestan por tu próxima caída.",
	["COMP_SAY_HELLO__mystic_5"] = "Soy %s. Leí tu futuro: huele a cementerio. Un poco.",
	["COMP_SAY_HELLO__parrot"] = "¡Craac! ¡%s! ¡Hola, hola! ¡Craac!",
	["COMP_SAY_HELLO__parrot_2"] = "¡Hola! ¡Craac! ¿Nos vamos? ¡Nos vamos!",
	["COMP_SAY_HELLO__parrot_3"] = "¡%s está aquí! ¡Craac! ¡Aventura! ¡Aventura!",
	["COMP_SAY_HELLO__parrot_4"] = "¡Craac! ¡Hola! ¿Perdido? ¿Perdido? ¡Todavía no!",
	["COMP_SAY_HELLO__parrot_5"] = "¡Jiji! ¡Soy %s! ¡Nada de morir! ¡Nada de morir!",
	["COMP_SAY_HELLO__sly"] = "Sss… soy %s. Haremos buenos negocios, tú y yo.",
	["COMP_SAY_HELLO__sly_2"] = "%s, a tu servicio… por ahora. Sss.",
	["COMP_SAY_HELLO__sly_3"] = "Sss… %s. Ya vendí tu capa vieja. Buen negocio, ¿eh?",
	["COMP_SAY_HELLO__sly_4"] = "%s. Tú recoges. Yo cuento. Sss.",
	["COMP_SAY_HELLO__sly_5"] = "Sss… soy %s. Nos haremos ricos. Tú un poco, yo mucho.",
	["COMP_SAY_HELLO__teasing"] = "¡Hola! Soy %s. Intenta no perderte esta vez.",
	["COMP_SAY_HELLO__teasing_2"] = "¡%s a tu servicio! Bueno, cuando me apetezca.",
	["COMP_SAY_HELLO__teasing_3"] = "¡Hola! Soy %s. Te hice un mapa. Con flechas. Grandes.",
	["COMP_SAY_HELLO__teasing_4"] = "¡%s, a la orden! Hoy llevo la cuenta de tus muertes, ¿vale?",
	["COMP_SAY_HELLO__teasing_5"] = "¡Eh, soy %s! ¿Vaciaste las bolsas? No, claro que no.",
	["COMP_SAY_HELLO__tinker"] = "¡Bip! %s, ajustado y engrasado. ¿Vamos?",
	["COMP_SAY_HELLO__tinker_2"] = "¡%s, a la orden! Todos mis resortes tienen cuerda.",
	["COMP_SAY_HELLO__tinker_3"] = "¡%s en línea! Diagnóstico del día: tu sentido de la orientación está roto.",
	["COMP_SAY_HELLO__tinker_4"] = "¡Bip bip! %s activado. Batería llena, paciencia limitada.",
	["COMP_SAY_HELLO__tinker_5"] = "%s, bien afinado. Tú, en cambio, pareces oxidado.",
	["COMP_SAY_HELLO__wise"] = "Hu. Soy %s. Todo viaje empieza con un primer paso.",
	["COMP_SAY_HELLO__wise_2"] = "%s te saluda. El camino espera, sin prisa.",
	["COMP_SAY_HELLO__wise_3"] = "Hu. %s, a tu servicio. Y para recordarte dónde está el norte.",
	["COMP_SAY_HELLO__wise_4"] = "Soy %s. La paciencia es la madre de la sabiduría. De la tuya también, espero.",
	["COMP_SAY_HELLO__wise_5"] = "%s te saluda. Hoy intentemos morir menos. Hu.",
	["COMP_SAY_HELLO__zen"] = "Hola. Soy %s. Sin prisa.",
	["COMP_SAY_HELLO__zen_2"] = "%s. Respira. Vamos, con suavidad.",
	["COMP_SAY_HELLO__zen_3"] = "Soy %s. Respira. Ya correrás luego. O nunca.",
	["COMP_SAY_HELLO__zen_4"] = "%s. El camino es largo. Tus rodeos, también.",
	["COMP_SAY_HELLO__zen_5"] = "Hola. %s. Hoy intentemos morir cero veces.",
	["COMP_SAY_IDLE"] = "Se está bien aquí… ¿nos quedamos un poco más?",
	["COMP_SAY_IDLE_10"] = "Si buscas la misión, está en tu mapa. Solo digo…",
	["COMP_SAY_IDLE_11"] = "Te he dado catorce vueltas. No te has movido.",
	["COMP_SAY_IDLE_12"] = "Mientras sueñas despierto, los jabalíes se multiplican.",
	["COMP_SAY_IDLE_13"] = "Me aburro un poco. ¡No de ti! Bueno… un poco de ti.",
	["COMP_SAY_IDLE_14"] = "¿Descansas o se te olvidó caminar?",
	["COMP_SAY_IDLE_15"] = "Aprovecho la calma para contar tus muertes de hoy. Necesito los dedos de los pies.",
	["COMP_SAY_IDLE_16"] = "Psst. El mundo está por ahí. Por todos lados, en realidad.",
	["COMP_SAY_IDLE_17"] = "Te dibujé en el polvo. Pareces perdido. Se te parece.",
	["COMP_SAY_IDLE_18"] = "Una pausa, vale. Pero no hasta el próximo nivel, ¿eh?",
	["COMP_SAY_IDLE_2"] = "Cuento las vigas del techo. Voy por doce.",
	["COMP_SAY_IDLE_3"] = "¿Una pausa? Yo también. Se me da muy bien.",
	["COMP_SAY_IDLE_4"] = "Zzz… ¿eh? No, no estaba durmiendo.",
	["COMP_SAY_IDLE_5"] = "Descansar también es aventura. La versión suave.",
	["COMP_SAY_IDLE_6"] = "¿Quieres oír mis sueños? Van de queso.",
	["COMP_SAY_IDLE_7"] = "¿Sigues ahí? Solo compruebo. ¿Sí? Bien.",
	["COMP_SAY_IDLE_8"] = "Creo que te dormiste de pie. Eso es talento.",
	["COMP_SAY_IDLE_9"] = "¿Esperamos algo? ¿A alguien? ¿Nada?",
	["COMP_SAY_IDLE_V_beast"] = "He olfateado todos los árboles. Informe: una ardilla, muy maleducada.",
	["COMP_SAY_IDLE_V_beast_2"] = "¿Crees que podría pillarme la cola? Solo por probar.",
	["COMP_SAY_IDLE_V_beast_3"] = "¡Un ruido! … No, era mi estómago.",
	["COMP_SAY_IDLE_V_beast_cuddly"] = "Ráscame detrás de la oreja. No, la otra. Ahí.",
	["COMP_SAY_IDLE_V_beast_cuddly_2"] = "Me tumbo sobre tus pies. Así no te vas sin mí.",
	["COMP_SAY_IDLE_V_critter"] = "Oí un ruido. Era una hoja. Una hoja muy sospechosa.",
	["COMP_SAY_IDLE_V_critter_2"] = "¿Crees que algún día creceré? ¿Lo justo para ver por encima de la hierba?",
	["COMP_SAY_IDLE_V_critter_3"] = "Cuento tus pasos. Das muchos. Yo doy cuatro veces más.",
	["COMP_SAY_IDLE_V_critter_glutton"] = "Escondí nueces por todas partes. No recuerdo dónde. Es una tragedia.",
	["COMP_SAY_IDLE_V_critter_glutton_2"] = "Dicen que hay pasteles más grandes que yo. Es mi sueño.",
	["COMP_SAY_IDLE_V_demon"] = "¿Sabes que conozco hechizos prohibidos? Solo lo comento.",
	["COMP_SAY_IDLE_V_demon_2"] = "Me aburro. Cuando me aburro, las cosas arden.",
	["COMP_SAY_IDLE_V_demon_3"] = "Consejo demoníaco: nunca leas el contrato. Es más divertido.",
	["COMP_SAY_IDLE_V_demon_lazy"] = "Sembrar el caos agota. Me tomo un siglo libre.",
	["COMP_SAY_IDLE_V_demon_lazy_2"] = "Despiértame si hay algo que quemar.",
	["COMP_SAY_IDLE_V_dragonkin"] = "Vi nacer estas montañas. Vale, exagero. Esas no.",
	["COMP_SAY_IDLE_V_dragonkin_2"] = "¿Sabes cuánto oro tendría si me hubiera quedado tus monedas? Mucho.",
	["COMP_SAY_IDLE_V_dragonkin_3"] = "Cuéntame tus hazañas. Brevemente. Ya sé cómo acaban.",
	["COMP_SAY_IDLE_V_dragonkin_glutton"] = "Un dragón necesita comida. Mucha. Ya.",
	["COMP_SAY_IDLE_V_dragonkin_glutton_2"] = "Sueño con un rebaño entero. Asado. Por mí.",
	["COMP_SAY_IDLE_V_elemental"] = "Escucho crecer la hierba. Tiene mucho que contar.",
	["COMP_SAY_IDLE_V_elemental_2"] = "El viento me contó una historia. Te la cuento dentro de cien años.",
	["COMP_SAY_IDLE_V_elemental_3"] = "Te mueves mucho. Prueba a ser una roca un rato.",
	["COMP_SAY_IDLE_V_elemental_curious"] = "¿Por qué las nubes nunca repiten forma? Lo estoy investigando.",
	["COMP_SAY_IDLE_V_elemental_curious_2"] = "Este guijarro es más viejo que tu ciudad. ¿Hablamos con él?",
	["COMP_SAY_IDLE_V_gfw"] = "Mi lista de buenos cabe en un pergamino. Solo los gnolls llenan tres.",
	["COMP_SAY_IDLE_V_gfw_2"] = "Cuento los regalos. Falta uno. Ah, no, era el mío. Me lo comí.",
	["COMP_SAY_IDLE_V_gfw_3"] = "Un goblin quiso comprarme el trineo. Dije que no. Él: «¿Y alquilado?»",
	["COMP_SAY_IDLE_V_gfw_4"] = "¿Mi barba? Siglos de nieve. Y una pizca de azúcar glas.",
	["COMP_SAY_IDLE_V_giant"] = "Yo pensar… … … Yo olvidar. No importa.",
	["COMP_SAY_IDLE_V_giant_2"] = "Esta roca. Yo gustar esta roca. No hablar mucho. Como yo.",
	["COMP_SAY_IDLE_V_giant_3"] = "Tú pequeño, pero valiente. Yo grande, pero miedo a ratones.",
	["COMP_SAY_IDLE_V_giant_cuddly"] = "¿Yo abrazar? … Tú desaparecer dentro. Pero abrazo.",
	["COMP_SAY_IDLE_V_giant_cuddly_2"] = "Tú subir a hombro. Mejor vista. Y amistad.",
	["COMP_SAY_IDLE_V_humanoid"] = "¿Sabías que casi fui bardo? Lo tenía todo, menos la voz.",
	["COMP_SAY_IDLE_V_humanoid_2"] = "Un día te llevaré a ver el mar. Bueno, un mar. Cualquiera.",
	["COMP_SAY_IDLE_V_humanoid_3"] = "Llevo un diario de nuestros viajes. Sales bien. Casi siempre.",
	["COMP_SAY_IDLE_V_humanoid_teasing"] = "¿Siempre caminas así? Como un pato con armadura.",
	["COMP_SAY_IDLE_V_humanoid_teasing_2"] = "¿Cuántas caídas hoy, ya? Las conté.",
	["COMP_SAY_IDLE_V_mechanical"] = "Revisión rutinaria: todo bien. Salvo ese chirrido. Ignóralo.",
	["COMP_SAY_IDLE_V_mechanical_2"] = "Consulta: ¿los seres vivos tienen modo reposo? Es para mí.",
	["COMP_SAY_IDLE_V_mechanical_3"] = "Calculé la distancia recorrida hoy. No quieres saberlo.",
	["COMP_SAY_IDLE_V_mechanical_curious"] = "Analizando este objeto: desconocido. Analizando su sabor: no recomendado.",
	["COMP_SAY_IDLE_V_mechanical_curious_2"] = "Consulta 117: ¿por qué ríen los seres vivos? Recopilando datos.",
	["COMP_SAY_IDLE_V_metzen"] = "A un reno de trineo no se le hace esperar. Lo sabes, ¿no?",
	["COMP_SAY_IDLE_V_metzen_2"] = "Yo di la vuelta a Azeroth en una noche. Tú, a la posada.",
	["COMP_SAY_IDLE_V_metzen_3"] = "Estiro las patas. Un reparto se prepara.",
	["COMP_SAY_IDLE_V_metzen_4"] = "Los grifos se creen rápidos. Les dejo creerlo.",
	["COMP_SAY_IDLE_V_snowman"] = "Cada copo de nieve es distinto. Conté trescientos. ¡Todos distintos!",
	["COMP_SAY_IDLE_V_snowman_2"] = "¿Crees que nací de una bola de nieve o de tres?",
	["COMP_SAY_IDLE_V_snowman_3"] = "Mi nariz de zanahoria me está mirando. Creo.",
	["COMP_SAY_IDLE_V_snowman_4"] = "Un día veré el mar. De lejos. Bien abrigado.",
	["COMP_SAY_IDLE_V_undead"] = "¿Sabes qué me gusta de ti? Respiras. Es tierno.",
	["COMP_SAY_IDLE_V_undead_2"] = "Conté mis huesos mientras caminabas. Falta uno. Tranquilo.",
	["COMP_SAY_IDLE_V_undead_3"] = "Si me caigo a pedazos, me recoges, ¿vale?",
	["COMP_SAY_IDLE_V_undead_cuddly"] = "Puedes abrazarme. Con cuidado, me desmonto fácil.",
	["COMP_SAY_IDLE_V_undead_cuddly_2"] = "Me caes bien. Tu corazón late, eso me tranquiliza.",
	["COMP_SAY_IDLE__cuddly"] = "Soy feliz aquí, contigo.",
	["COMP_SAY_IDLE__cuddly_2"] = "¿Sabes que eres mi aventurero favorito?",
	["COMP_SAY_IDLE__cuddly_3"] = "¿Sigues ahí? Te abrazo mientras espero.",
	["COMP_SAY_IDLE__cuddly_4"] = "¿Te dormiste? Yo velo por ti.",
	["COMP_SAY_IDLE__cuddly_5"] = "¿Nos quedamos así? Por mí, perfecto.",
	["COMP_SAY_IDLE__cuddly_6"] = "¿Sabes que roncas un poco cuando te quedas quieto?",
	["COMP_SAY_IDLE__cuddly_7"] = "Te estoy tejiendo una bufanda. En mi cabeza.",
	["COMP_SAY_IDLE__cuddly_8"] = "Tus bolsas están llenas de trastos viejos… como mi corazón, de recuerdos.",
	["COMP_SAY_IDLE__curious"] = "¿Qué crees que hay detrás de esa colina?",
	["COMP_SAY_IDLE__curious_2"] = "¿Por qué el cielo es azul aquí y morado en otros sitios?",
	["COMP_SAY_IDLE__curious_3"] = "Conté las piedras del camino. Bueno, casi todas.",
	["COMP_SAY_IDLE__curious_4"] = "¿Duermes? ¿Piensas? ¿Lees el mapa al revés?",
	["COMP_SAY_IDLE__curious_5"] = "¿Por qué paramos? ¿Se te olvidó adónde íbamos?",
	["COMP_SAY_IDLE__curious_6"] = "¿Sigues ahí? Parpadea dos veces si es que sí.",
	["COMP_SAY_IDLE__curious_7"] = "¿Cuánto tiempo aguantas quieto? Estoy contando. Ya va mucho.",
	["COMP_SAY_IDLE__curious_8"] = "Si no nos movemos, ¿seguimos de aventura?",
	["COMP_SAY_IDLE__curious_9"] = "Tengo una pregunta. No, dos. No, doce. Tienes tiempo, por lo visto.",
	["COMP_SAY_IDLE__daring"] = "¿A qué esperamos? ¡Hay enemigos que vencer!",
	["COMP_SAY_IDLE__daring_2"] = "Practico mi rugido. ¡Grrr! No está mal, ¿eh?",
	["COMP_SAY_IDLE__daring_3"] = "¿Haces guardia o duermes la siesta? ¿Sinceramente?",
	["COMP_SAY_IDLE__daring_4"] = "Los monstruos no vendrán solos. Bueno, a veces sí.",
	["COMP_SAY_IDLE__daring_5"] = "¿Acampamos aquí? Los enemigos creerán que tenemos miedo.",
	["COMP_SAY_IDLE__daring_6"] = "Hago flexiones mientras espero. Voy por dos.",
	["COMP_SAY_IDLE__daring_7"] = "Un héroe inmóvil es una estatua. ¡Muévete, estatua!",
	["COMP_SAY_IDLE__daring_8"] = "¿A qué esperas, a que el élite te pida perdón?",
	["COMP_SAY_IDLE__fearful"] = "¿Oíste eso? ¿No? Yo tampoco. Creo.",
	["COMP_SAY_IDLE__fearful_2"] = "Vigilo la retaguardia. Todo tranquilo. Por ahora.",
	["COMP_SAY_IDLE__fearful_3"] = "Cloc… cloc… canto para calmarme.",
	["COMP_SAY_IDLE__fearful_4"] = "No te mueves… ¿dormido? ¿Muerto? Ah, estás pensando.",
	["COMP_SAY_IDLE__fearful_5"] = "Quedarnos aquí sin hacer nada: ese plan sí me gusta.",
	["COMP_SAY_IDLE__fearful_6"] = "Conté los arbustos sospechosos. Hay siete. ¡Siete!",
	["COMP_SAY_IDLE__fearful_7"] = "Cloc… si te duermes en el teclado, ¿quién me protege?",
	["COMP_SAY_IDLE__fearful_8"] = "¿A qué esperamos? No a los grandes malos, espero.",
	["COMP_SAY_IDLE__fearful_9"] = "Soñé que me llevabas a una mazmorra. Qué pesadilla.",
	["COMP_SAY_IDLE__glutton"] = "Sueño con un pastel de setas…",
	["COMP_SAY_IDLE__glutton_2"] = "Me ruge la barriga. ¿Lo oíste?",
	["COMP_SAY_IDLE__glutton_3"] = "Si las nubes fueran de azúcar, volaría.",
	["COMP_SAY_IDLE__glutton_4"] = "¿Fuiste a por comida? Di que sí. Di que sí.",
	["COMP_SAY_IDLE__glutton_5"] = "No te mueves… ¿haciendo la digestión? ¿Sin mí?",
	["COMP_SAY_IDLE__glutton_6"] = "Mientras sueñas, cuento tus galletas. Falta una. Ejem.",
	["COMP_SAY_IDLE__glutton_7"] = "Pienso en una sopa. Luego en otra. Es una pausa larga.",
	["COMP_SAY_IDLE__glutton_8"] = "Si no haces nada, al menos podríamos comer, ¿no?",
	["COMP_SAY_IDLE__glutton_9"] = "Ya va un rato… me comí la paciencia. Sabía a avellana.",
	["COMP_SAY_IDLE__lazy"] = "Zzz… ¿eh? No, no, no estaba durmiendo.",
	["COMP_SAY_IDLE__lazy_2"] = "Qué bien se está. No nos movamos nunca más.",
	["COMP_SAY_IDLE__lazy_3"] = "Ñaaa… qué día tan bonito para no hacer nada.",
	["COMP_SAY_IDLE__lazy_4"] = "¡Por fin paras! Empezaba a pensar que eras un caballo.",
	["COMP_SAY_IDLE__lazy_5"] = "¿Estás AFK? Yo también, pero con talento.",
	["COMP_SAY_IDLE__lazy_6"] = "No te muevas. Si te mueves, tendré que moverme.",
	["COMP_SAY_IDLE__lazy_7"] = "Una pausa, por fin. Seamos como las rocas: esperamos.",
	["COMP_SAY_IDLE__lazy_8"] = "Si nadie se mueve, nadie se cansa. Lógico.",
	["COMP_SAY_IDLE__lazy_9"] = "¿Olvidaste qué hacíamos? Perfecto, yo también. Nos quedamos.",
	["COMP_SAY_IDLE__mischievous"] = "¿Y si escondemos las botas del próximo que pase?",
	["COMP_SAY_IDLE__mischievous_10"] = "Jiji, cambié todos tus objetos grises por otros objetos grises.",
	["COMP_SAY_IDLE__mischievous_2"] = "Hago pompas. ¡Mira! ¡Plop!",
	["COMP_SAY_IDLE__mischievous_3"] = "¿Oíste ese ruido? ¡Fui yo! Jiji.",
	["COMP_SAY_IDLE__mischievous_4"] = "¿No te mueves? Pues te pinto un bigote.",
	["COMP_SAY_IDLE__mischievous_5"] = "¿Hola? ¿Hay alguien al teclado? Jiji, voy a hacer una travesura.",
	["COMP_SAY_IDLE__mischievous_6"] = "Te llené las botas de musgo. Cuando andes, harán chof.",
	["COMP_SAY_IDLE__mischievous_7"] = "¿Jugando a las estatuas? A las palomas les va a encantar.",
	["COMP_SAY_IDLE__mischievous_8"] = "En tu pausa, le cambié el nombre a tu caballo: Patata. Está de acuerdo.",
	["COMP_SAY_IDLE__mischievous_9"] = "Cuento hasta diez y, si no te mueves, te hago cosquillas. Uno…",
	["COMP_SAY_IDLE__mystic"] = "Las hojas susurran. ¿Las oyes?",
	["COMP_SAY_IDLE__mystic_2"] = "Floto un poco más alto cuando sale la luna.",
	["COMP_SAY_IDLE__mystic_3"] = "Ya no te mueves… los espíritus creen que meditas.",
	["COMP_SAY_IDLE__mystic_4"] = "Eché las cartas. Dicen: «Volverá, algún día».",
	["COMP_SAY_IDLE__mystic_5"] = "¿Tu alma salió a pasear? Te dejó aquí.",
	["COMP_SAY_IDLE__mystic_6"] = "Las hojas caen. Tú esperas. Yo floto.",
	["COMP_SAY_IDLE__mystic_7"] = "Veo tu futuro… está sentado. Muy sentado.",
	["COMP_SAY_IDLE__mystic_8"] = "Un cuervo me preguntó si eras una estatua.",
	["COMP_SAY_IDLE__parrot"] = "¡Lorito quiere galleta! ¡Lorito quiere galleta!",
	["COMP_SAY_IDLE__parrot_2"] = "¿Craac? Craac. ¡Craac!",
	["COMP_SAY_IDLE__parrot_3"] = "¿Hola? ¿Hola? ¿Dormido? ¡Craac!",
	["COMP_SAY_IDLE__parrot_4"] = "¡Muévete! ¡Muévete! ¡Lorito se aburre!",
	["COMP_SAY_IDLE__parrot_5"] = "¡Bolsas llenas! ¡Piedras! ¡Piedras! ¡Craac!",
	["COMP_SAY_IDLE__parrot_6"] = "¡Tic tac! ¡Tic tac! ¡Craac!",
	["COMP_SAY_IDLE__parrot_7"] = "Lorito repite: ¡vamos! ¡Vamos!",
	["COMP_SAY_IDLE__parrot_8"] = "¡Estatua! ¡Estatua! ¡Bonita estatua! ¡Craac!",
	["COMP_SAY_IDLE__sly"] = "Vigilo. Alguien nos observa… o no.",
	["COMP_SAY_IDLE__sly_2"] = "Sss… tengo un plan. Te lo cuento luego.",
	["COMP_SAY_IDLE__sly_3"] = "¿No te mueves? Sss… a los ladrones les encanta.",
	["COMP_SAY_IDLE__sly_4"] = "Conté tu oro mientras soñabas. Falta algo.",
	["COMP_SAY_IDLE__sly_5"] = "Mientras dormías, cerré tres tratos. Sss.",
	["COMP_SAY_IDLE__sly_6"] = "Un plan toma forma… solo falta que despiertes.",
	["COMP_SAY_IDLE__sly_7"] = "Estatua perfecta. Podríamos venderte como decoración.",
	["COMP_SAY_IDLE__sly_8"] = "¿Esperar a qué? ¿A que el oro llegue solo? Buena idea, de hecho.",
	["COMP_SAY_IDLE__teasing"] = "Tienes algo en la nariz. No, es broma.",
	["COMP_SAY_IDLE__teasing_10"] = "Pausa eterna número 3. Llevo la cuenta.",
	["COMP_SAY_IDLE__teasing_2"] = "Apuesto a que no sabes dónde estamos. ¡Yo tampoco!",
	["COMP_SAY_IDLE__teasing_3"] = "¿Dormido? ¿Fuiste a picar algo? Te estoy juzgando.",
	["COMP_SAY_IDLE__teasing_4"] = "¡Eh! El mundo no se va a salvar solo.",
	["COMP_SAY_IDLE__teasing_5"] = "Si no te mueves, vendo tus grises.",
	["COMP_SAY_IDLE__teasing_6"] = "¿Jugando a las estatuas? Se te da muy bien.",
	["COMP_SAY_IDLE__teasing_7"] = "Tus bolsas rebosan de piedras y dientes viejos. ¿Los coleccionas?",
	["COMP_SAY_IDLE__teasing_8"] = "Cuento hasta diez y me voy de aventura sin ti.",
	["COMP_SAY_IDLE__teasing_9"] = "¿Sigues ahí? ¿O hablo con un muñeco de cartón?",
	["COMP_SAY_IDLE__tinker"] = "Inventé un chisme. Aún no sé qué hace.",
	["COMP_SAY_IDLE__tinker_2"] = "Tic, tac, tic… oh, no, soy yo que chirría.",
	["COMP_SAY_IDLE__tinker_3"] = "¿Me prestas tu llave inglesa? Solo dos minutos.",
	["COMP_SAY_IDLE__tinker_4"] = "Error 404: sentido de la orientación no encontrado. Lo digo por ti.",
	["COMP_SAY_IDLE__tinker_5"] = "¿Estás en reposo? Te puse en modo ahorro de energía.",
	["COMP_SAY_IDLE__tinker_6"] = "Calculé el tiempo perdido dando vueltas hoy. Mejor no saberlo.",
	["COMP_SAY_IDLE__tinker_7"] = "Bzz… ay, perdón, es mi resorte bostezando.",
	["COMP_SAY_IDLE__tinker_8"] = "Conté tus objetos grises: cuarenta y dos. Récord, enhorabuena.",
	["COMP_SAY_IDLE__tinker_9"] = "En tu pausa desmonté un reloj. Ahora son… las ninguna.",
	["COMP_SAY_IDLE__wise"] = "El silencio también es una respuesta.",
	["COMP_SAY_IDLE__wise_2"] = "La luna conoce todos los caminos. Yo, casi todos.",
	["COMP_SAY_IDLE__wise_3"] = "La quietud es sabiduría. O una siesta. Aún no lo he decidido.",
	["COMP_SAY_IDLE__wise_4"] = "Hu. Quien espera demasiado se vuelve paisaje.",
	["COMP_SAY_IDLE__wise_5"] = "Tus bolsas están llenas; tu mente debería ir ligera.",
	["COMP_SAY_IDLE__wise_6"] = "Dicen que el tiempo es oro. Tú gastas mucho.",
	["COMP_SAY_IDLE__wise_7"] = "El búho vigila. Tú, por lo visto, no.",
	["COMP_SAY_IDLE__wise_8"] = "El mundo gira. Tú, nada de nada.",
	["COMP_SAY_IDLE__zen"] = "Inspira… espira… ¿ves? Mejor.",
	["COMP_SAY_IDLE__zen_2"] = "La tortuga siempre llega. Siempre.",
	["COMP_SAY_IDLE__zen_3"] = "Ya no te mueves. Por fin entiendes el zen.",
	["COMP_SAY_IDLE__zen_4"] = "Cuánta quietud… Estoy orgulloso. ¿O te has dormido?",
	["COMP_SAY_IDLE__zen_5"] = "Silencio. Viento. Tu personaje, inmóvil. Perfecto.",
	["COMP_SAY_IDLE__zen_6"] = "¿Estás meditando o fuiste a por algo de picar?",
	["COMP_SAY_IDLE__zen_7"] = "La piedra espera sin quejarse. Yo también. Casi.",
	["COMP_SAY_IDLE__zen_8"] = "Crece una brizna de hierba. ¿La miramos juntos?",
	["COMP_SAY_INN"] = "Una posada… ¿una siestecita?",
	["COMP_SAY_INN_10"] = "¡Ah, una cama! Roncas, que lo sepas.",
	["COMP_SAY_INN_11"] = "Una posada: el único sitio donde no te pierdes.",
	["COMP_SAY_INN_2"] = "¡Huele a sopa! ¿Nos quedamos un rato?",
	["COMP_SAY_INN_3"] = "¡Una cama de verdad! Me pido la esquina de la almohada.",
	["COMP_SAY_INN_4"] = "Aquí acumulas experiencia de descanso mientras duermes.",
	["COMP_SAY_INN_5"] = "Una posada: cálida, seca y llena de charlatanes.",
	["COMP_SAY_INN_6"] = "¡Una posada! Siéntate, que has corrido por nada.",
	["COMP_SAY_INN_7"] = "Aquí se duerme, se come y no se muere. El paraíso.",
	["COMP_SAY_INN_8"] = "¡La posada! Acuérdate de vincularte aquí, para variar.",
	["COMP_SAY_INN_9"] = "¡Una posada! Cuenta tus hazañas a los clientes. Las muertes no.",
	["COMP_SAY_INN_FULL"] = "¡Tarjeta llena! ¡El posadero me invita a un festín!",
	["COMP_SAY_INN_STAMP"] = "Un sello en mi tarjeta: ¡%d/%d!",
	["COMP_SAY_INN_STAMP_2"] = "¡Sello! %d de %d. Me encantan las posadas.",
	["COMP_SAY_JOKE"] = "¿Cómo se llama un múrloc afinado? Ni idea. Nadie ha visto uno.",
	["COMP_SAY_JOKE_10"] = "«Mata diez lobos». ¿Por qué diez? ¿El undécimo tiene buen abogado?",
	["COMP_SAY_JOKE_11"] = "¿Mi plan de batalla favorito? El de Leeroy. Corto, simple y siempre acaba en grito.",
	["COMP_SAY_JOKE_12"] = "La Piedra de hogar es mágica: diez segundos para volver, una hora para regresar a pie.",
	["COMP_SAY_JOKE_13"] = "No digo que saltes mal. Digo que el suelo sigue invicto.",
	["COMP_SAY_JOKE_14"] = "Correr hasta tu cadáver: la única carrera cuya meta eres tú, tumbado.",
	["COMP_SAY_JOKE_15"] = "El sanador espiritual es el único médico que cobra en botas gastadas.",
	["COMP_SAY_JOKE_16"] = "Este vendedor compra de todo: dientes rotos, plumas mojadas… ¿Qué estará construyendo?",
	["COMP_SAY_JOKE_17"] = "Me encantan los objetos grises. Inútiles, pero de una constancia admirable.",
	["COMP_SAY_JOKE_18"] = "Dieciséis huecos, todos llenos de lino. No vas de aventura, te estás mudando.",
	["COMP_SAY_JOKE_19"] = "Los gnomos lo inventaron todo menos la escalera. Pasaron directo a los cohetes.",
	["COMP_SAY_JOKE_2"] = "Aprendí múrloc. Solo una palabra, pero sirve para todo: Mrglglgl.",
	["COMP_SAY_JOKE_20"] = "Los ascensores han matado a más aventureros que los dragones. Los dragones están furiosos.",
	["COMP_SAY_JOKE_21"] = "Los PNJ de escolta siempre andan justo más lento que tú. A estas alturas, es un talento.",
	["COMP_SAY_JOKE_22"] = "Los Defias llevan máscara para que nadie los reconozca. Todos la misma máscara roja. Impecable.",
	["COMP_SAY_JOKE_23"] = "En las posadas ganas experiencia durmiendo. Por fin una habilidad que tengo al máximo.",
	["COMP_SAY_JOKE_24"] = "El pan del posadero dura años. Creo que ha sobrevivido a tres posaderos.",
	["COMP_SAY_JOKE_25"] = "El maestro de vuelo te vende un viaje. El grifo te regala la visita turística.",
	["COMP_SAY_JOKE_26"] = "Al herrero le encanta verte. Bueno, a tu armadura rota. Tú solo eres el repartidor.",
	["COMP_SAY_JOKE_27"] = "Ese guardia hace la misma ronda desde el alba. Ya ha dejado surco en el camino.",
	["COMP_SAY_JOKE_28"] = "Un atajo es solo un rodeo que aún no se ha presentado.",
	["COMP_SAY_JOKE_29"] = "Tirar Necesidad a todo es una filosofía. Muy solitaria.",
	["COMP_SAY_JOKE_3"] = "No existe el múrloc solitario. Sus siete primos siempre están tras esa roca.",
	["COMP_SAY_JOKE_30"] = "Hay un libro con las páginas esparcidas por toda una jungla. El encuadernador tuvo un mal día.",
	["COMP_SAY_JOKE_31"] = "Cacarea a una gallina el tiempo suficiente y te da una misión. Las gallinas tienen un plan.",
	["COMP_SAY_JOKE_32"] = "Pescar es fácil: esperas, esperas y sacas una bota vieja. Como si te hiciera falta otra.",
	["COMP_SAY_JOKE_4"] = "¿Por qué los kóbolds no celebran cumpleaños? Se niegan a soplar las velas.",
	["COMP_SAY_JOKE_5"] = "Un kóbold abrió una tienda de velas. El cartel decía «Tú no coger vela». Vendía poco.",
	["COMP_SAY_JOKE_6"] = "Los que dan misiones nunca se mueven. O tienen las botas clavadas o un sindicato muy bueno.",
	["COMP_SAY_JOKE_7"] = "Ese PNJ lleva años esperando en el mismo sitio. Eso es paciencia. O un calambre.",
	["COMP_SAY_JOKE_8"] = "Cuando veo un signo de exclamación amarillo sobre alguien, me pregunto: ¿está herido o contratando?",
	["COMP_SAY_JOKE_9"] = "Se buscan diez hígados de jabalí. Viendo el botín, casi todos nacieron sin hígado.",
	["COMP_SAY_JOKE_V_beast"] = "¿Por qué los lobos no cuentan chistes? Se comen el final.",
	["COMP_SAY_JOKE_V_beast_2"] = "Mi instinto dice «peligro». Mi estómago dice «merienda». Siempre gana el estómago.",
	["COMP_SAY_JOKE_V_beast_3"] = "Los cazadores nos llaman «mascotas». Nosotros a ellos, «dispensadores de carne con patas».",
	["COMP_SAY_JOKE_V_beast_4"] = "Me pasé una hora persiguiendo mi cola. Buena noticia: nunca se escapó.",
	["COMP_SAY_JOKE_V_beast_5"] = "¿Diez hígados de jabalí? Te encuentro once. No preguntes cómo.",
	["COMP_SAY_JOKE_V_beast_6"] = "Los osos duermen todo el invierno. Yo también, pero repartido en siestas todo el año.",
	["COMP_SAY_JOKE_V_critter"] = "Hay un gato en ese tejado. No, no tiemblo. Vibro. Gran diferencia.",
	["COMP_SAY_JOKE_V_critter_2"] = "¿El monstruo más temible de Azeroth? No es un dragón. Es un gato de taberna aburrido.",
	["COMP_SAY_JOKE_V_critter_3"] = "Soy pequeño, pero tengo corazón de león. Bueno, un corazón. De ratón. Latiendo muy rápido.",
	["COMP_SAY_JOKE_V_critter_4"] = "Dicen que los gatos tienen siete vidas. Seis de más, si me preguntas.",
	["COMP_SAY_JOKE_V_critter_5"] = "Tuve una pesadilla: un gato que daba misiones. «Tráeme diez alimañas».",
	["COMP_SAY_JOKE_V_critter_6"] = "Los héroes se enfrentan a dragones. Yo paso junto al gato del posadero. Cada uno tiene sus pruebas.",
	["COMP_SAY_JOKE_V_demon"] = "Vengo del Vacío Abisal y nunca me había aburrido tanto. Enhorabuena.",
	["COMP_SAY_JOKE_V_demon_2"] = "Los brujos nos invocan para luchar y luego nos hacen cargar las bolsas. El contrato era vago.",
	["COMP_SAY_JOKE_V_demon_3"] = "¿Tu alma por una Piedra de hogar? ¿No? Lástima, estaba abierto a regatear.",
	["COMP_SAY_JOKE_V_demon_4"] = "Mi fuego interior arde eterno. Salvo cuando charlas con vendedores. Entonces echa la siesta.",
	["COMP_SAY_JOKE_V_demon_5"] = "Podría desatar el caos en Azeroth. Tu sentido de la orientación se me adelantó.",
	["COMP_SAY_JOKE_V_demon_6"] = "Los fragmentos de alma son como los calcetines: siempre desaparece uno en tus bolsas.",
	["COMP_SAY_JOKE_V_dragonkin"] = "Los dragones no cuentan chistes. Concedemos el humor a los mortales. Ya puedes reír.",
	["COMP_SAY_JOKE_V_dragonkin_2"] = "El tesoro de un dragón es como tus bolsas: lleno de oro. Bueno, el mío. El tuyo, de lino.",
	["COMP_SAY_JOKE_V_dragonkin_3"] = "Un mortal me preguntó la edad. Le dije: más que tu reino. Se rio. Yo no.",
	["COMP_SAY_JOKE_V_dragonkin_4"] = "Volar es fácil: bate las alas y mira el suelo desde arriba. Tú haces lo contrario.",
	["COMP_SAY_JOKE_V_dragonkin_5"] = "¿Grifos? Palomas con delirios de grandeza.",
	["COMP_SAY_JOKE_V_dragonkin_6"] = "Viajo contigo por pura generosidad. Y porque están reformando mi guarida.",
	["COMP_SAY_JOKE_V_elemental"] = "«Sé como el agua», dicen los sabios. Lo intenté. Me evaporé.",
	["COMP_SAY_JOKE_V_elemental_2"] = "Un guijarro me preguntó el sentido de la vida. Le dije: paciencia. Es un talento natural.",
	["COMP_SAY_JOKE_V_elemental_3"] = "Dejo la mente en blanco. Es fácil: casi todo yo es aire.",
	["COMP_SAY_JOKE_V_elemental_4"] = "Tierra, fuego, agua, aire… y tú, el quinto elemento: los problemas.",
	["COMP_SAY_JOKE_V_elemental_5"] = "Inspira. Espira. Y no saltes de ese acantilado, arruina la meditación.",
	["COMP_SAY_JOKE_V_elemental_6"] = "El fuego me dijo que no perdiera los estribos. Mira quién habla.",
	["COMP_SAY_JOKE_V_giant"] = "Toc, toc. … … Espera. ¿Llamo yo o llamas tú?",
	["COMP_SAY_JOKE_V_giant_2"] = "Esta mañana oí un chiste muy gracioso. Me reiré hacia el jueves.",
	["COMP_SAY_JOKE_V_giant_3"] = "Los pequeños corren por todas partes. Yo doy un paso y llego antes.",
	["COMP_SAY_JOKE_V_giant_4"] = "Una vez aplasté una montaña. No. Me senté encima. Es lo mismo.",
	["COMP_SAY_JOKE_V_giant_5"] = "¿Por qué… las nubes… están tan bajas hoy? Ah. No. Soy… alto.",
	["COMP_SAY_JOKE_V_giant_6"] = "Dicen que soy lento. No es verdad. Solo pienso… muy… fuerte.",
	["COMP_SAY_JOKE_V_humanoid"] = "¿Mi primer trabajo de aventurero? Ratas en un sótano. Desde entonces huelo un sótano a una legua.",
	["COMP_SAY_JOKE_V_humanoid_2"] = "Un aventurero necesita tres cosas: una espada, un mapa y un amigo que sepa leer el mapa.",
	["COMP_SAY_JOKE_V_humanoid_3"] = "He salvado esta aldea tres veces. Siguen queriendo diez pieles de lobo.",
	["COMP_SAY_JOKE_V_humanoid_4"] = "¿La diferencia entre un héroe y un necio? El héroe sigue en pie.",
	["COMP_SAY_JOKE_V_humanoid_5"] = "En mis tiempos íbamos a Forjaz a pie. Por la nieve. Cuesta arriba a la ida y a la vuelta.",
	["COMP_SAY_JOKE_V_humanoid_6"] = "Consejo de aventurero: nunca digas «esto será fácil» en voz alta. Los múrlocs escuchan.",
	["COMP_SAY_JOKE_V_mechanical"] = "Chiste n.º 42 cargado. Error: humor no encontrado. Ría manualmente.",
	["COMP_SAY_JOKE_V_mechanical_2"] = "Cálculo: cuatro muertes hoy. Conclusión: el suelo es tu jefe favorito.",
	["COMP_SAY_JOKE_V_mechanical_3"] = "Los gnomos me hicieron con mil piezas. Tres siguen en el banco de trabajo. Todo en orden.",
	["COMP_SAY_JOKE_V_mechanical_4"] = "¿Por qué cruzó la gallina la carretera? Datos insuficientes. Recomiendo captura.",
	["COMP_SAY_JOKE_V_mechanical_5"] = "Bip. Modo abrazo activado. Bip. Modo abrazo desactivado. Duración: insuficiente. Bip.",
	["COMP_SAY_JOKE_V_mechanical_6"] = "Nunca me oxido. Salvo al pescar. Y con lluvia. Y solo de pensarlo.",
	["COMP_SAY_JOKE_V_undead"] = "No temo el daño por caída. Lo peor ya pasó, y lo superé.",
	["COMP_SAY_JOKE_V_undead_2"] = "No-muerto al sanador: «No siento nada». Sanador: «Enhorabuena, está curado de todo».",
	["COMP_SAY_JOKE_V_undead_3"] = "¿Correr hasta el cadáver? Lo hago por costumbre. A veces solo por tomar el aire.",
	["COMP_SAY_JOKE_V_undead_4"] = "Ayer perdí un brazo. Lo encontré en tu bolsa, entre dos paños de lino. Ordena.",
	["COMP_SAY_JOKE_V_undead_5"] = "Dicen que estoy pálido. Espera unos siglos y hablamos.",
	["COMP_SAY_JOKE_V_undead_6"] = "¿Mi dieta? Sin azúcar, sin sal, sin pulso.",
	["COMP_SAY_KILL"] = "¡Bien hecho! No me lo esperaba.",
	["COMP_SAY_KILL_10"] = "¡Y cae! Él. No tú. Para variar.",
	["COMP_SAY_KILL_11"] = "¡Bien! Pegaste tan fuerte que le diste pena.",
	["COMP_SAY_KILL_12"] = "¡Victoria! Ya puedes dejar de pegarle, no se mueve.",
	["COMP_SAY_KILL_13"] = "¡Bravo! Y ni siquiera tropezaste con la capa.",
	["COMP_SAY_KILL_14"] = "¡Uno menos! Solo quedan… todos los demás.",
	["COMP_SAY_KILL_15"] = "No era un conejito, ¿verdad? Uf, no.",
	["COMP_SAY_KILL_16"] = "¡Buena puntería! O fallaste y se metió solo.",
	["COMP_SAY_KILL_17"] = "Ha durado lo suyo… ¿le pegas con una cuchara?",
	["COMP_SAY_KILL_18"] = "¡Ganamos! Yo lo había ablandado con una mirada feroz.",
	["COMP_SAY_KILL_19"] = "¡Uf! ¿Sudaste con ese? Tampoco era tan grande.",
	["COMP_SAY_KILL_2"] = "¡Uno menos! Te animaba con todas mis fuerzas.",
	["COMP_SAY_KILL_20"] = "¡Bien hecho! Lo anoto en la columna de \"éxitos\". Es cortita.",
	["COMP_SAY_KILL_21"] = "¡Eso es! Eres temible… para los de tu nivel.",
	["COMP_SAY_KILL_22"] = "Descanse, soldado. Bueno, dos segundos, que viene otro.",
	["COMP_SAY_KILL_23"] = "¡Rápido y limpio! Bueno, rápido. Limpio, no tanto.",
	["COMP_SAY_KILL_3"] = "¡Pum! Qué técnica.",
	["COMP_SAY_KILL_4"] = "Yo también lo habría hecho… quizá… algún día.",
	["COMP_SAY_KILL_5"] = "Limpio y ordenado. ¿Ya lo habías hecho antes?",
	["COMP_SAY_KILL_6"] = "¡Bravo! En el próximo me tapo los ojos.",
	["COMP_SAY_KILL_7"] = "Uf, se acabó. ¿Estás bien?",
	["COMP_SAY_KILL_8"] = "Respira antes del siguiente.",
	["COMP_SAY_KILL_9"] = "Siempre me impresionas.",
	["COMP_SAY_KILL_V_beast"] = "¡Buena presa! Me guardo los huesos para luego.",
	["COMP_SAY_KILL_V_beast_2"] = "%s no fue lo bastante rápido. Ley del bosque.",
	["COMP_SAY_KILL_V_beast_3"] = "La manada cazó, la manada ganó. ¡Auuuu!",
	["COMP_SAY_KILL_V_beast_daring"] = "¡Otra vez! ¡Tírame otro, que corro!",
	["COMP_SAY_KILL_V_beast_daring_2"] = "Lo vi antes que tú. En el próximo, yo dirijo la carga.",
	["COMP_SAY_KILL_V_critter"] = "¿Se ha… ido? ¿Para siempre? ¿Puedo abrir los ojos?",
	["COMP_SAY_KILL_V_critter_2"] = "%s era TRES VECES más grande que yo. Qué valiente eres.",
	["COMP_SAY_KILL_V_critter_3"] = "Aún tiemblo. ¡Pero de orgullo! Sobre todo de orgullo.",
	["COMP_SAY_KILL_V_critter_daring"] = "¡Ayudé! ¡Le mordí la bota! Bueno, lo intenté.",
	["COMP_SAY_KILL_V_critter_daring_2"] = "¿Otro? ¡Estoy listo! … Tras un descansito.",
	["COMP_SAY_KILL_V_demon"] = "Un alma más para… eh, para nada. Ya no colecciono.",
	["COMP_SAY_KILL_V_demon_2"] = "%s arderá ahí abajo. Conozco al encargado.",
	["COMP_SAY_KILL_V_demon_3"] = "Bien. Con una pizca de vil habría sido perfecto.",
	["COMP_SAY_KILL_V_demon_teasing"] = "Gritó más fuerte que tú la última vez. Por poco.",
	["COMP_SAY_KILL_V_demon_teasing_2"] = "¿Viste su cara? La enmarcaría sobre la chimenea.",
	["COMP_SAY_KILL_V_dragonkin"] = "Aceptable. Para una criatura sin alas.",
	["COMP_SAY_KILL_V_dragonkin_2"] = "¿%s? Lo habría reducido a cenizas con un bostezo.",
	["COMP_SAY_KILL_V_dragonkin_3"] = "Mis ancestros abatieron titanes. Pero ese tampoco está mal.",
	["COMP_SAY_KILL_V_dragonkin_teasing"] = "¡Qué golpe! Para un mortal. Armado con una ramita.",
	["COMP_SAY_KILL_V_dragonkin_teasing_2"] = "Bien. Mis ancestros aún se ríen, allá arriba.",
	["COMP_SAY_KILL_V_elemental"] = "Vuelve a la tierra. Todo regresa, tarde o temprano.",
	["COMP_SAY_KILL_V_elemental_2"] = "%s solo era una llama. Las llamas se apagan.",
	["COMP_SAY_KILL_V_elemental_3"] = "Equilibrio restaurado. Por ahora.",
	["COMP_SAY_KILL_V_elemental_daring"] = "¡Más! ¡Que se alce la tormenta!",
	["COMP_SAY_KILL_V_elemental_daring_2"] = "Siento el trueno en las venas. ¡Siguiente!",
	["COMP_SAY_KILL_V_gfw"] = "¿%s? Lista de traviesos. Lo tacho y listo.",
	["COMP_SAY_KILL_V_gfw_2"] = "Ni regalo para ese este año. Ni los siguientes.",
	["COMP_SAY_KILL_V_gfw_3"] = "¡Jo, jo! Una parada menos en la ronda. Noche más corta para mí.",
	["COMP_SAY_KILL_V_giant"] = "BUM. Hecho.",
	["COMP_SAY_KILL_V_giant_2"] = "%s… diminuto. Como tú. Pero tú, majo.",
	["COMP_SAY_KILL_V_giant_3"] = "Yo no aplastar. Tú aplastar. Bien. Muy… bien.",
	["COMP_SAY_KILL_V_giant_lazy"] = "Bien. Ahora… siesta. Larga. Una estación.",
	["COMP_SAY_KILL_V_giant_lazy_2"] = "Yo no mover. Tú hacer todo. Buen equipo.",
	["COMP_SAY_KILL_V_humanoid"] = "¡Bien jugado! Yo también lo habría hecho, ojo. Pero bien jugado.",
	["COMP_SAY_KILL_V_humanoid_2"] = "%s no verá el alba. ¿Le hacemos una canción?",
	["COMP_SAY_KILL_V_humanoid_3"] = "¡Otro para la leyenda! Llevo la cuenta, tranquilo.",
	["COMP_SAY_KILL_V_humanoid_curious"] = "Espera, anoto sus tácticas. … Eran malas.",
	["COMP_SAY_KILL_V_humanoid_curious_2"] = "¿De dónde crees que venía %s? Quiero saberlo.",
	["COMP_SAY_KILL_V_mechanical"] = "Objetivo neutralizado. Añado una muesca a mi carcasa.",
	["COMP_SAY_KILL_V_mechanical_2"] = "Bip bip. %s: averiado. Garantía anulada.",
	["COMP_SAY_KILL_V_mechanical_3"] = "Eficacia en combate: satisfactoria. Elegancia: mejorable.",
	["COMP_SAY_KILL_V_mechanical_daring"] = "¡Siguiente! Se me calientan los circuitos, ¡quiero más!",
	["COMP_SAY_KILL_V_mechanical_daring_2"] = "¡Potencia máxima! Siguiente objetivo, por favor.",
	["COMP_SAY_KILL_V_mechanical_lazy"] = "Objetivo abatido. Sugiero pausa de mantenimiento. Larga.",
	["COMP_SAY_KILL_V_mechanical_lazy_2"] = "Modo ahorro de energía: el próximo es tuyo.",
	["COMP_SAY_KILL_V_metzen"] = "¿%s? Muy lento. Todos son muy lentos.",
	["COMP_SAY_KILL_V_metzen_2"] = "Un golpe de astas y listo. ¡Siguiente!",
	["COMP_SAY_KILL_V_metzen_3"] = "Rápido y limpio. Lo apruebo.",
	["COMP_SAY_KILL_V_snowman"] = "¡Oh! %s se ha caído. ¿También tenía frío?",
	["COMP_SAY_KILL_V_snowman_2"] = "¡Qué fuerte eres! Yo solo sé hacer bolas de nieve.",
	["COMP_SAY_KILL_V_snowman_3"] = "No se mueve… ¿Está jugando a ser muñeco de nieve?",
	["COMP_SAY_KILL_V_undead"] = "Bienvenido al club. Quedan asientos libres.",
	["COMP_SAY_KILL_V_undead_2"] = "Tranquilo, %s. Al otro lado no se está tan mal.",
	["COMP_SAY_KILL_V_undead_3"] = "Otro que quizá se una a mí. Jugaremos a las tabas.",
	["COMP_SAY_KILL_V_undead_glutton"] = "Lástima que ya no tenga gusto. Parecía crujiente.",
	["COMP_SAY_KILL_V_undead_glutton_2"] = "Me quedo la mandíbula. La mía baila un poco.",
	["COMP_SAY_KILL_V_undead_teasing"] = "Parece sorprendido. Todos parecen sorprendidos.",
	["COMP_SAY_KILL_V_undead_teasing_2"] = "Venga, no pongas esa cara. Ah, ya no puede.",
	["COMP_SAY_KILL__cuddly"] = "¡Me protegiste! ¡Gracias!",
	["COMP_SAY_KILL__cuddly_2"] = "¡Bien hecho! Ven, que te felicite.",
	["COMP_SAY_KILL__cuddly_3"] = "¡Ganaste! ¿No estás muy herido? Déjame ver.",
	["COMP_SAY_KILL__cuddly_4"] = "¡Bien hecho! Aunque era pequeñito, cuenta.",
	["COMP_SAY_KILL__cuddly_5"] = "Ay, el pobre conejito… bueno, no querías.",
	["COMP_SAY_KILL__cuddly_6"] = "¡Mi héroe! Un poco sin aliento, pero mi héroe.",
	["COMP_SAY_KILL__cuddly_7"] = "Luchaste bien. ¿Abrazo de premio?",
	["COMP_SAY_KILL__cuddly_8"] = "Uf, se acabó. No me gusta cuando te peleas.",
	["COMP_SAY_KILL__curious"] = "Oye, ¿qué llevaba ese en los bolsillos?",
	["COMP_SAY_KILL__curious_2"] = "Me pregunto de dónde venía…",
	["COMP_SAY_KILL__curious_3"] = "¿Era malo o solo te apetecía pegar algo?",
	["COMP_SAY_KILL__curious_4"] = "¿Por qué siempre pegas a los conejitos? ¿Qué te han hecho?",
	["COMP_SAY_KILL__curious_5"] = "¿Viste cómo cayó? ¡Quiero repetición!",
	["COMP_SAY_KILL__curious_6"] = "Pregunta: ¿lo atacaste a propósito o pasabas por aquí?",
	["COMP_SAY_KILL__curious_7"] = "¿Y su familia? No, olvídalo, no quiero saberlo.",
	["COMP_SAY_KILL__curious_8"] = "¿Crees que tenía nombre? Yo lo llamaba Gerardo.",
	["COMP_SAY_KILL__daring"] = "¡Ja! ¡Siguiente!",
	["COMP_SAY_KILL__daring_2"] = "Demasiado fácil. ¿Los hay más grandes?",
	["COMP_SAY_KILL__daring_3"] = "¡Otra! ¡Otra!",
	["COMP_SAY_KILL__daring_4"] = "¿Un conejito? ¿En serio? Apunta más alto, campeón.",
	["COMP_SAY_KILL__daring_5"] = "¡Bien! Pero te costó diez golpes. Yo lo hago en nueve.",
	["COMP_SAY_KILL__daring_6"] = "¡Uno! Venga, la próxima trae tres a la vez.",
	["COMP_SAY_KILL__daring_7"] = "¡Victoria! ¿Al menos gritaste? Los héroes gritan.",
	["COMP_SAY_KILL__daring_8"] = "No tenía nada que hacer. Elige uno más grande la próxima.",
	["COMP_SAY_KILL__daring_9"] = "¡Al suelo! Empiezas a enorgullecerme.",
	["COMP_SAY_KILL__fearful"] = "¿Se ha ido? ¿Seguro? Uf.",
	["COMP_SAY_KILL__fearful_2"] = "Cerré los ojos. ¿Ganaste? ¡Bien hecho!",
	["COMP_SAY_KILL__fearful_3"] = "¿Era un conejo? ¿Te asustaba un conejo? A mí también, la verdad.",
	["COMP_SAY_KILL__fearful_4"] = "¿Seguro que está muerto? Pínchalo otra vez, por si acaso.",
	["COMP_SAY_KILL__fearful_5"] = "¡Coc! Bien. La próxima vez, elige uno más pequeño.",
	["COMP_SAY_KILL__fearful_6"] = "¡Lo lograste! Yo vigilaba. Desde muy lejos. Tras un árbol.",
	["COMP_SAY_KILL__fearful_7"] = "Uf… el corazón me va a mil. Espero que el tuyo también.",
	["COMP_SAY_KILL__fearful_8"] = "¿Por qué lo provocaste? ¡No te hizo nada! Vale, bien hecho.",
	["COMP_SAY_KILL__glutton"] = "Ese olía a asado, ¿no?",
	["COMP_SAY_KILL__glutton_2"] = "¡Bien! Pelear me da hambre.",
	["COMP_SAY_KILL__glutton_3"] = "¿Otro conejito? Si al menos lo cocinaras…",
	["COMP_SAY_KILL__glutton_4"] = "¿Soltó carne? ¿No? ¿Entonces para qué le pegaste?",
	["COMP_SAY_KILL__glutton_5"] = "¿Tanta pelea por un diente? ¿Ni un jamón?",
	["COMP_SAY_KILL__glutton_6"] = "Ese olía a queso. Tengo derecho a estar triste.",
	["COMP_SAY_KILL__glutton_7"] = "¡Bravo! Eso se merece un tentempié, ¿no? ¿No?",
	["COMP_SAY_KILL__glutton_8"] = "Pegas tan lento como caminas. Me dio tiempo a merendar.",
	["COMP_SAY_KILL__lazy"] = "Bien… te animé. Tumbado.",
	["COMP_SAY_KILL__lazy_2"] = "Otro más… ¿nunca te cansas?",
	["COMP_SAY_KILL__lazy_3"] = "¿Perseguir un conejito? ¿Sabes que él no pidió esto?",
	["COMP_SAY_KILL__lazy_4"] = "Bien hecho… podías haberlo dejado vivir. Y nosotros, sentarnos.",
	["COMP_SAY_KILL__lazy_5"] = "Otra pelea. Tú vas buscando líos, ¿eh?",
	["COMP_SAY_KILL__lazy_6"] = "Cerré los ojos durante la pelea. Para descansar, no por miedo.",
	["COMP_SAY_KILL__lazy_7"] = "¿Podrías pegar a dos a la vez? Nos ahorraríamos una pausa.",
	["COMP_SAY_KILL__lazy_8"] = "Se ha caído. Lo entiendo. Yo haría lo mismo ahora.",
	["COMP_SAY_KILL__mischievous"] = "¡Puf! ¡Desapareció! Como por arte de magia.",
	["COMP_SAY_KILL__mischievous_2"] = "¡Jiji, puso una cara graciosísima!",
	["COMP_SAY_KILL__mischievous_3"] = "¡Puf! Venciste a un conejito. ¡Menudo héroe! Jiji.",
	["COMP_SAY_KILL__mischievous_4"] = "Se cayó de risa con tu técnica. ¡Es broma!",
	["COMP_SAY_KILL__mischievous_5"] = "Tú le pegaste, pero yo le puse la zancadilla. Chis.",
	["COMP_SAY_KILL__mischievous_6"] = "¡Bravo! No había pedido nada, pobrecito. Jiji.",
	["COMP_SAY_KILL__mischievous_7"] = "¡Zas, pum, puf! Bueno, sobre todo zas y muchos fallos.",
	["COMP_SAY_KILL__mischievous_8"] = "Le eché purpurina al cuerpo. Más festivo.",
	["COMP_SAY_KILL__mischievous_9"] = "¡Uno menos! ¿Te busco uno más pequeño la próxima?",
	["COMP_SAY_KILL__mystic"] = "Su espíritu se marcha… que descanse en paz.",
	["COMP_SAY_KILL__mystic_2"] = "Los espíritus aprueban.",
	["COMP_SAY_KILL__mystic_3"] = "Su espíritu se aleja… maldiciéndote un poquito.",
	["COMP_SAY_KILL__mystic_4"] = "Los espíritus toman nota: uno más. Llevan la cuenta.",
	["COMP_SAY_KILL__mystic_5"] = "¿Era una ardilla? Los espíritus del bosque lo recordarán.",
	["COMP_SAY_KILL__mystic_6"] = "Un temblor en el velo… ¿fue él o tu técnica?",
	["COMP_SAY_KILL__mystic_7"] = "Lo vi en las llamas. Tú lo viste después.",
	["COMP_SAY_KILL__mystic_8"] = "Paz para él. Y para tu barra de salud, que ha ido justo.",
	["COMP_SAY_KILL__parrot"] = "¡Bien hecho! ¡Bien hecho! ¡Cuac!",
	["COMP_SAY_KILL__parrot_2"] = "¡Uno menos! ¡Uno menos!",
	["COMP_SAY_KILL__parrot_3"] = "¡Pobre conejito! ¡Pobre conejito! ¡Cuac!",
	["COMP_SAY_KILL__parrot_4"] = "¡Muy largo! ¡Muy largo! ¡Pero ganado!",
	["COMP_SAY_KILL__parrot_5"] = "¡Pum! ¡Pum! ¡Pum! ¡Cuac!",
	["COMP_SAY_KILL__parrot_6"] = "¡Fácil! ¡Fácil! ¡Estaba dormido! ¡Cuac!",
	["COMP_SAY_KILL__parrot_7"] = "¡Héroe! ¡Héroe! Bueno… ¡casi! ¡Cuac!",
	["COMP_SAY_KILL__parrot_8"] = "¡Otro! ¡Otro! ¡Lorito lleva la cuenta!",
	["COMP_SAY_KILL__sly"] = "Sss… ni lo vio venir.",
	["COMP_SAY_KILL__sly_2"] = "Limpio. Regístralo, rápido.",
	["COMP_SAY_KILL__sly_3"] = "Sss… ¿y qué llevaba? Tres monedas de cobre. Patético.",
	["COMP_SAY_KILL__sly_4"] = "Un conejo. No vale nada. Ni su piel.",
	["COMP_SAY_KILL__sly_5"] = "¿Atacaste de frente? Sss… cero estilo.",
	["COMP_SAY_KILL__sly_6"] = "Regístralo antes de que lleguen los otros. Rápido, rápido.",
	["COMP_SAY_KILL__sly_7"] = "Lo provocaste, ¿eh? No diré nada. Por una moneda.",
	["COMP_SAY_KILL__sly_8"] = "Bien. Pero gastaste tres pociones en un lobo.",
	["COMP_SAY_KILL__teasing"] = "¡Nada mal! ¿Apuntaste con los ojos cerrados?",
	["COMP_SAY_KILL__teasing_10"] = "¡Bonita victoria! La apunté, entre dos derrotas.",
	["COMP_SAY_KILL__teasing_2"] = "Se cayó solo, ¿verdad? ¡Es broma!",
	["COMP_SAY_KILL__teasing_3"] = "¡Bravo! ¿De qué nivel era? ¿Dos? Je.",
	["COMP_SAY_KILL__teasing_4"] = "¿Acabas de zurrar a un conejito? Menudo héroe.",
	["COMP_SAY_KILL__teasing_5"] = "¡Ganaste! Para ser justos, estaba dormido.",
	["COMP_SAY_KILL__teasing_6"] = "¡Por fin! Me dio tiempo a echar una siesta.",
	["COMP_SAY_KILL__teasing_7"] = "¡Bien! ¿Acabaste a puñetazos o ese era el plan?",
	["COMP_SAY_KILL__teasing_8"] = "Él cayó. Tú casi también. Llamémoslo empate.",
	["COMP_SAY_KILL__teasing_9"] = "Otro inocente que solo pasaba por aquí.",
	["COMP_SAY_KILL__tinker"] = "Mecanismo enemigo desactivado. Buen trabajo.",
	["COMP_SAY_KILL__tinker_2"] = "¿Puedo recuperar sus piezas? ¿No? Lástima.",
