	["COMP_SAY_KILL__wise"] = "La victoria es de quien sabe esperar. Bien.",
	["COMP_SAY_KILL__wise_2"] = "Una pelea más. ¿Qué te ha enseñado?",
	["COMP_SAY_KILL__wise_3"] = "Quien golpea a un conejo no crece por ello.",
	["COMP_SAY_KILL__wise_4"] = "Bien. Pero una victoria fácil no enseña nada.",
	["COMP_SAY_KILL__wise_5"] = "El lobo ha caído. El orgullo sigue en pie.",
