	["COMP_SAY_LEVEL_V_critter_3"] = "Nivel %s… ¿Me seguirás protegiendo cuando seas muy fuerte?",
	["COMP_SAY_LEVEL_V_demon"] = "Nivel %s. Tu poder crece. Excelente… digo, bien hecho.",
