	["COMP_SAY_LEVEL_V_elemental_3"] = "Nivel %s. La tierra se ha dado cuenta. Se da cuenta de todo.",
	["COMP_SAY_LEVEL_V_gfw"] = "¡Nivel %s! Jo, jo, jo, lo escribo en oro en mi lista.",
	["COMP_SAY_LEVEL_V_gfw_2"] = "¡Estás creciendo! El año que viene necesitaré una caja más grande.",
