	["COMP_SAY_LOOT__sly"] = "Sss… eso se vende caro.",
	["COMP_SAY_LOOT__sly_2"] = "Buen botín. Guárdalo, o véndelo en el momento justo.",
	["COMP_SAY_LOOT__sly_3"] = "Un objeto gris. ¿Te lo quedas? Sss… nunca aprenderás.",
	["COMP_SAY_LOOT__sly_4"] = "Eso no vale nada. Pero con la sonrisa adecuada…",
	["COMP_SAY_LOOT__sly_5"] = "¿Otro diente? Tu bolsa ya es una mandíbula.",
	["COMP_SAY_LOOT__sly_6"] = "Buena pieza. No digas a nadie de dónde sale.",
	["COMP_SAY_LOOT__sly_7"] = "Sss… este nos lo quedamos. El resto de tus cosas, fuera.",
	["COMP_SAY_LOOT__sly_8"] = "Véndeselo al vendedor de enfrente. Es más generoso.",
	["COMP_SAY_LOOT__teasing"] = "¡Brillante! Te quedará mejor a ti que a mí. Aunque…",
	["COMP_SAY_LOOT__teasing_2"] = "¡Un objeto gris! Otra joya para tu colección de trastos.",
	["COMP_SAY_LOOT__teasing_3"] = "Eso vale… tres de cobre. Enhorabuena.",
	["COMP_SAY_LOOT__teasing_4"] = "¿Recoges hasta dientes de lobo? Respeto.",
	["COMP_SAY_LOOT__teasing_5"] = "¿Te lo pondrás o lo guardarás veinte niveles?",
	["COMP_SAY_LOOT__teasing_6"] = "¡Oh! Ah, no, otro trapo viejo.",
	["COMP_SAY_LOOT__teasing_7"] = "Otra cosa camino del vendedor. El mes que viene.",
	["COMP_SAY_LOOT__teasing_8"] = "¡Botín! ¿Queda sitio? ¿Hasta cuándo?",
	["COMP_SAY_LOOT__teasing_9"] = "Hallazgo soberbio. Si te gustan las piedras.",
	["COMP_SAY_LOOT__tinker"] = "¡Oh, piezas de repuesto! Ah, no, es un objeto de verdad. También vale.",
	["COMP_SAY_LOOT__tinker_2"] = "¿Más cosas grises? Ratio de chatarra en tus bolsas: 87%%.",
	["COMP_SAY_LOOT__tinker_3"] = "¡Oh, un engranaje! Ah, no, una moneda de cobre. Decepción mecánica.",
	["COMP_SAY_LOOT__tinker_4"] = "Botín analizado: útil. Para variar. ¡Bien hecho!",
	["COMP_SAY_LOOT__tinker_5"] = "¿Te lo quedas? Podría hacer un muelle con eso. O un desastre.",
	["COMP_SAY_LOOT__tinker_6"] = "¡Bip! Objeto brillante detectado. Probabilidad de venta: buena.",
	["COMP_SAY_LOOT__tinker_7"] = "Un diente de lobo. Otra vez. Los coleccionas, admítelo.",
	["COMP_SAY_LOOT__wise"] = "Un tesoro. Pero el verdadero tesoro es el viaje.",
	["COMP_SAY_LOOT__wise_2"] = "Quien todo lo recoge, todo lo carga. Uuh.",
	["COMP_SAY_LOOT__wise_3"] = "El objeto gris tiene valor. Pequeño, pero real.",
	["COMP_SAY_LOOT__wise_4"] = "La riqueza no se mide en piedras. Al menos la tuya no.",
	["COMP_SAY_LOOT__wise_5"] = "Un buen objeto. Guárdalo o déjalo. Pero decide.",
	["COMP_SAY_LOOT__wise_6"] = "El tesoro buscado no siempre es el tesoro hallado.",
	["COMP_SAY_LOOT__wise_7"] = "Uuh. El sabio viaja ligero. Tú aún no eres sabio.",
	["COMP_SAY_LOOT__zen"] = "Bonito. Pero nada supera la paz.",
	["COMP_SAY_LOOT__zen_2"] = "Un objeto gris. Acéptalo. Luego véndelo.",
	["COMP_SAY_LOOT__zen_3"] = "Lo recoges todo. El desapego no es para hoy.",
	["COMP_SAY_LOOT__zen_4"] = "¿Un tesoro? Un diente de lobo. La vida es sencilla.",
	["COMP_SAY_LOOT__zen_5"] = "Tu bolsa pesa. Tu mente podría ser ligera.",
	["COMP_SAY_LOOT__zen_6"] = "Bonito. No te apegues. El vendedor espera.",
	["COMP_SAY_LOOT__zen_7"] = "Otra baratija. El vacío también tiene su belleza.",
	["COMP_SAY_LORE"] = "¿Sabías que…? %s",
	["COMP_SAY_LORE_2"] = "Dicen esto: %s",
	["COMP_SAY_LORE_3"] = "Escucha… %s",
	["COMP_SAY_LORE_4"] = "Una vieja historia cuenta: %s",
	["COMP_SAY_LORE_5"] = "Mira bien aquí. %s",
	["COMP_SAY_LORE_PLACE"] = "%s… ¿Sabías que…? %s",
	["COMP_SAY_LORE_PLACE_2"] = "%s. Dicen esto: %s",
	["COMP_SAY_LORE_PLACE_3"] = "Aquí, %s. %s",
	["COMP_SAY_LORE_PLACE_4"] = "¡%s! Escucha… %s",
	["COMP_SAY_MISSED"] = "¡Te eché de menos! Zzz… despertando poco a poco.",
	["COMP_SAY_MISSED_2"] = "¡Has vuelto! Te guardé el sitio calentito… zzz.",
	["COMP_SAY_MISSED_3"] = "¡Oh, eres tú! Soñaba contigo. Bueno… con comida.",
	["COMP_SAY_MISSED_4"] = "¡Ah, ahí estás! Creía que te habías perdido camino del vendedor.",
	["COMP_SAY_MISSED_5"] = "¡Por fin! Me dio tiempo a contar todas las piedras. Dos veces.",
	["COMP_SAY_MISSED_6"] = "¿Dónde estabas? No, no me lo digas, me imagino una misión épica.",
	["COMP_SAY_MISSED_7"] = "¡Has vuelto! ¿Yo? No, no he llorado. Solo bostezaba un poco.",
	["COMP_SAY_MISSED_8"] = "Zzz… ¡oh! ¿Ya? Empezaba un sueño precioso sin monstruos.",
	["COMP_SAY_MISSION_ALL"] = "¡Las tres misiones! ¡Esta noche, festín!",
	["COMP_SAY_MISSION_DONE"] = "¡Misión cumplida! ¿Un premio para mí?",
	["COMP_SAY_MISSION_DONE_2"] = "¡Una misión cumplida!",
	["COMP_SAY_MISSION_NEW"] = "¡Nuevas misiones del día! Echa un vistazo a mi diario.",
	["COMP_SAY_MISSION_NEW_2"] = "Tengo ideas para hoy… ¡pestaña Misiones!",
	["COMP_SAY_NEED_V_gfw"] = "Jo… jo… Hasta el Gran Padre Invierno necesita un descanso.",
	["COMP_SAY_NEED_V_gfw_2"] = "Un tazón de ponche de huevo y un rincón caliente, y listo.",
	["COMP_SAY_NEED_V_metzen"] = "Hasta un reno necesita un respiro. Uno corto, nada más.",
	["COMP_SAY_NEED_V_metzen_2"] = "Arrastro las pezuñas. Eso nunca pasa. Bueno, casi nunca.",
	["COMP_SAY_NEED_V_snowman"] = "Me siento blandito… necesito un poco de nieve.",
	["COMP_SAY_NEED_V_snowman_2"] = "Un rincón a la sombra, una brisa fresca, y estoy bien.",
	["COMP_SAY_NEED_curiosity"] = "Hace siglos que no veo nada nuevo… ¿exploramos?",
	["COMP_SAY_NEED_curiosity_2"] = "¿Y si echamos un vistazo tras esa colina?",
	["COMP_SAY_NEED_curiosity_3"] = "Un sitio nuevo en el mapa, ¿te apetece?",
	["COMP_SAY_NEED_curiosity_4"] = "¡Me muero por descubrir un sitio nuevo!",
	["COMP_SAY_NEED_curiosity_5"] = "Aquí damos vueltas. ¡Vamos a otra parte!",
	["COMP_SAY_NEED_curiosity_6"] = "¿Ese camino de ahí? ¡Nunca lo hemos tomado!",
	["COMP_SAY_NEED_curiosity_7"] = "Me sé esta roca de memoria. ¿Seguimos?",
	["COMP_SAY_NEED_curiosity_8"] = "Una zona desconocida, solo una, ¡por favor!",
	["COMP_SAY_NEED_curiosity_9"] = "¿Miedo a perderte? ¡Nos perderemos juntos!",
	["COMP_SAY_NEED_energy"] = "Tengo tanto sueño… ¿una posada, quizá?",
	["COMP_SAY_NEED_energy_2"] = "Un sitio para descansar, una siesta, y soy todo tuyo.",
	["COMP_SAY_NEED_energy_3"] = "Mis patitas están cansadas. ¿Nos sentamos un rato?",
	["COMP_SAY_NEED_energy_4"] = "Aaah… perdón. ¿Descansamos pronto?",
	["COMP_SAY_NEED_energy_5"] = "Tú corres por todas partes, yo me duermo de pie.",
	["COMP_SAY_NEED_energy_6"] = "Una posada, un fuego, y vuelvo a ser adorable.",
	["COMP_SAY_NEED_energy_7"] = "Mis párpados pesan más que tu bolsa.",
	["COMP_SAY_NEED_energy_8"] = "¿Un descanso? Sueño con cojines.",
	["COMP_SAY_NEED_energy_9"] = "Si ronco mientras camino, es normal.",
	["COMP_SAY_NEED_hunger"] = "Tengo un poco de hambre… ¿parada para picar algo?",
	["COMP_SAY_NEED_hunger_2"] = "Mi barriguita hace ruidos raros. ¿Pausa para comer?",
	["COMP_SAY_NEED_hunger_3"] = "Cuando tú comes, yo también me llevo algo, ¿sabes?",
	["COMP_SAY_NEED_hunger_4"] = "¡Un poco de pan y quedo como nuevo!",
	["COMP_SAY_NEED_hunger_5"] = "Mi barriga hace más ruido que tus peleas.",
	["COMP_SAY_NEED_hunger_6"] = "Tu bolsa está llena de comida y yo no tengo nada. Solo lo digo…",
	["COMP_SAY_NEED_hunger_7"] = "Una miga, solo una. Por la moral de la tropa.",
	["COMP_SAY_NEED_hunger_8"] = "Si comes, picoteo un poco. Poquito, prometido.",
	["COMP_SAY_NEED_hunger_9"] = "Me comería un jabalí. Uno pequeño, vale.",
	["COMP_SAY_NEED_mood"] = "Saciado, descansado, despierto: ¡estoy radiante!",
	["COMP_SAY_NEED_mood_2"] = "Todo va bien. De verdad todo. ¿Capturamos?",
	["COMP_SAY_NEED_mood_3"] = "¡Brillo! Que se preparen las brillantes.",
	["COMP_SAY_NEED_mood_4"] = "Barriga llena, patas descansadas, ojos bien abiertos.",
	["COMP_SAY_NEED_mood_5"] = "Es el momento de lanzar la red, lo presiento.",
	["COMP_SAY_NEED_mood_6"] = "No podría estar más feliz. Bueno… un mimo, quizá.",
	["COMP_SAY_NEED_mood_7"] = "¡Radiante! Apúntalo en tu diario.",
	["COMP_SAY_NEED_mood_8"] = "Todo es perfecto. Aprovechemos antes de que se pase.",
	["COMP_SAY_NEED_mood_9"] = "Hoy hasta los múrlocs me parecen majos.",
	["COMP_SAY_NIGHT"] = "Es de noche… ¡mira las estrellas!",
	["COMP_SAY_NIGHT_2"] = "De noche todo da un poco de miedo. Menos tú.",
	["COMP_SAY_NIGHT_3"] = "Chis… de noche, hasta los lobos susurran.",
	["COMP_SAY_NIGHT_4"] = "Un paseo a la luz de la luna, qué bonito, ¿no?",
	["COMP_SAY_NIGHT_5"] = "Cae la noche. Tú también caes a menudo, pero no tiene nada que ver.",
	["COMP_SAY_NIGHT_6"] = "¡Está oscuro! Quédate cerca de mí. Para protegerte, claro.",
	["COMP_SAY_NIGHT_7"] = "De noche te pierdes aún más. Y partes de lejos.",
	["COMP_SAY_NIGHT_8"] = "Las estrellas son preciosas. Al menos ellas saben adónde van.",
	["COMP_SAY_NIGHT_9"] = "¡Buenas noches, mundo! Bueno, nosotros no, tenemos misiones.",
	["COMP_SAY_NIGHT_V_beast"] = "La luna está alta. Mis ancestros aúllan en mi sangre.",
	["COMP_SAY_NIGHT_V_beast_2"] = "De noche veo mejor que tú. Sigue mis ojos brillantes.",
	["COMP_SAY_NIGHT_V_beast_3"] = "Es hora de cazar. O de la siesta. Las dos valen.",
	["COMP_SAY_NIGHT_V_critter"] = "Es de noche. Salen los búhos. Me dan miedo los búhos.",
	["COMP_SAY_NIGHT_V_critter_2"] = "¿Dejarás una luz encendida? ¿Una pequeñita?",
	["COMP_SAY_NIGHT_V_critter_3"] = "Las estrellas son bonitas. Pero nos están mirando, ¿verdad?",
	["COMP_SAY_NIGHT_V_demon"] = "Noche. Mis ojos brillan en verde, es normal. Que no cunda el pánico.",
	["COMP_SAY_NIGHT_V_demon_2"] = "Está oscuro. Perfecto para travesuras. Es broma. Casi.",
	["COMP_SAY_NIGHT_V_demon_3"] = "Bonita noche para invocar algo. ¿No? Vale.",
	["COMP_SAY_NIGHT_V_dragonkin"] = "Noche. Mis ancestros volaban bajo estas mismas estrellas.",
	["COMP_SAY_NIGHT_V_dragonkin_2"] = "¿Oscuro? Podría iluminar el camino, pero odiarías el método.",
	["COMP_SAY_NIGHT_V_dragonkin_3"] = "La luna es vieja. Casi tanto como yo. Casi.",
	["COMP_SAY_NIGHT_V_elemental"] = "Noche. La luna atrae las mareas, y a mí un poco.",
	["COMP_SAY_NIGHT_V_elemental_2"] = "Las estrellas son fuegos muy lejanos. Las saludo.",
	["COMP_SAY_NIGHT_V_elemental_3"] = "De noche el mundo va más despacio. Yo también. Está bien.",
	["COMP_SAY_NIGHT_V_gfw"] = "La noche es mi momento. Todas las chimeneas del mundo son mías.",
	["COMP_SAY_NIGHT_V_gfw_2"] = "Han salido las estrellas. Perfecto para guiar el trineo.",
	["COMP_SAY_NIGHT_V_giant"] = "Noche. Estrellas tan pequeñas. Como tú. Yo querer cosas pequeñas.",
	["COMP_SAY_NIGHT_V_giant_2"] = "Yo bostezar. … Perdón. Viento para todo el valle.",
	["COMP_SAY_NIGHT_V_giant_3"] = "La luna… casi tan redonda como mi barriga.",
	["COMP_SAY_NIGHT_V_humanoid"] = "Cae la noche. El mejor momento para historias junto al fuego.",
	["COMP_SAY_NIGHT_V_humanoid_2"] = "Está oscuro. Quédate cerca. No, no tengo miedo. Tú quizá sí.",
	["COMP_SAY_NIGHT_V_humanoid_3"] = "Bonita noche. Las estrellas son el mapa de los viajeros perdidos.",
	["COMP_SAY_NIGHT_V_mechanical"] = "Poca luz. Encendería mi lámpara, si tuviera una.",
	["COMP_SAY_NIGHT_V_mechanical_2"] = "Cambiando a modo nocturno. Bip silencioso.",
	["COMP_SAY_NIGHT_V_mechanical_3"] = "Es tarde, operador. A las máquinas también nos gusta dormir.",
	["COMP_SAY_NIGHT_V_metzen"] = "Cae la noche, se me enciende la nariz: hora de capturar.",
	["COMP_SAY_NIGHT_V_metzen_2"] = "De noche lo veo todo. Nada se nos escapa.",
	["COMP_SAY_NIGHT_V_snowman"] = "De noche hace más fresco. Me siento genial.",
	["COMP_SAY_NIGHT_V_snowman_2"] = "¿Las estrellas son copos de nieve que nunca caen?",
	["COMP_SAY_NIGHT_V_undead"] = "Cae la noche. Por fin, mi momento.",
	["COMP_SAY_NIGHT_V_undead_2"] = "¿Está oscuro? Veo de maravilla. Ventajas de no tener ojos.",
	["COMP_SAY_NIGHT_V_undead_3"] = "Bonita luna. Perfecta para pasear por el cementerio.",
	["COMP_SAY_NOFOOD"] = "¿Te vas sin comida? ¡Acuérdate de mí en el próximo vendedor!",
	["COMP_SAY_NOFOOD_2"] = "Tus bolsas huelen a… nada. ¿Algo de comer en el próximo vendedor?",
	["COMP_SAY_NOFOOD_3"] = "¿Sin comida? Vale, buscaré migas.",
	["COMP_SAY_NOFOOD_4"] = "Solo digo: un poco de pan ayuda en el camino.",
	["COMP_SAY_NOFOOD_5"] = "¿Cero comida en tus bolsas? ¿Piensas comer dientes de león?",
	["COMP_SAY_NOFOOD_6"] = "Bolsas llenas de trastos grises, pero ni un trozo de pan. ¡Prioridades!",
	["COMP_SAY_NOFOOD_7"] = "¿Salir con el estómago vacío? Aviso: con hambre, refunfuño.",
	["COMP_SAY_NOFOOD_8"] = "Aventurero sin comida, aventurero que se sienta mucho.",
	["COMP_SAY_NOTICE__cuddly"] = "Hace rato que no me acaricias… solo lo digo.",
	["COMP_SAY_NOTICE__cuddly_2"] = "¿Un mimito? ¿Solo uno? ¡Haz clic en mí!",
	["COMP_SAY_NOTICE__cuddly_3"] = "¿Te olvidaste de mí? Estoy aquí abajo. Chiquitito.",
	["COMP_SAY_NOTICE__cuddly_4"] = "Veinte minutos sin una caricia. Llevo la cuenta, ¿sabes?",
	["COMP_SAY_NOTICE__cuddly_5"] = "Recoges todas las piedras del mundo, ¿pero a mí no?",
	["COMP_SAY_NOTICE__cuddly_6"] = "Un clic, solo uno. Es gratis.",
	["COMP_SAY_NOTICE__cuddly_7"] = "Estoy enfurruñado. Un poquito. Un mimo y olvidado.",
	["COMP_SAY_NOTICE__cuddly_8"] = "¿Tienes tiempo para zurrar jabalíes, pero no para acariciarme?",
	["COMP_SAY_NOTICE__curious"] = "Oh, ¿qué sitio es este? ¡Nunca habíamos venido!",
	["COMP_SAY_NOTICE__curious_2"] = "¡Eh, un sitio que no conocíamos!",
	["COMP_SAY_NOTICE__curious_3"] = "Ese sendero… ¿lo seguimos? ¿Solo para ver?",
	["COMP_SAY_NOTICE__curious_4"] = "¡Un sitio nuevecito! ¿Lo encontraste a propósito o por casualidad?",
	["COMP_SAY_NOTICE__curious_5"] = "Eh, nunca hemos estado aquí. Das vueltas, admítelo.",
	["COMP_SAY_NOTICE__curious_6"] = "¡Sitio nuevo! ¿Cómo se llama? Nunca lees los carteles.",
	["COMP_SAY_NOTICE__curious_7"] = "¡Oh, un rincón! ¿Lo registramos? ¡Lo registramos!",
	["COMP_SAY_NOTICE__curious_8"] = "Este sitio huele a secreto. O a setas. ¿A las dos cosas?",
	["COMP_SAY_NOTICE__curious_9"] = "¡Un sitio desconocido! ¿Nos has perdido o esto es explorar?",
	["COMP_SAY_NOTICE__daring"] = "¿Has visto eso? ¡Qué pelea! ¡Otra así!",
	["COMP_SAY_NOTICE__daring_2"] = "¡Un élite abatido! ¡Somos demasiado fuertes!",
	["COMP_SAY_NOTICE__daring_3"] = "¡Un élite abatido! Lo sabía. Bueno, lo esperaba con fuerza.",
	["COMP_SAY_NOTICE__daring_4"] = "¡Venciste a un élite! Se lo contaré a todos. Exagerando.",
	["COMP_SAY_NOTICE__daring_5"] = "¡Un élite! ¡Y sigues en pie! Casi una primicia.",
	["COMP_SAY_NOTICE__daring_6"] = "¡Eso sí fue una pelea de verdad! Nada de conejitos. Bien hecho, mi héroe.",
	["COMP_SAY_NOTICE__daring_7"] = "¡Élite vencido! Temblaste un poco, pero no diré nada.",
	["COMP_SAY_NOTICE__daring_8"] = "¡Era enorme y lo lograste! ¿Buscamos uno más grande?",
	["COMP_SAY_NOTICE__fearful"] = "Eso pega fuerte… ¿recuperamos el aliento? ¿Un poquito?",
	["COMP_SAY_NOTICE__fearful_2"] = "Me tiemblan las plumas. ¿Seguro que saldremos bien?",
	["COMP_SAY_NOTICE__fearful_3"] = "¡Tu salud se derrite! ¿Retrocedemos? Retrocedemos, ¿verdad?",
	["COMP_SAY_NOTICE__fearful_4"] = "¡Coc! ¡Pega demasiado fuerte! Aunque tú te lo buscaste.",
	["COMP_SAY_NOTICE__fearful_5"] = "¡La poción! ¡La roja! ¡La que siempre olvidas!",
	["COMP_SAY_NOTICE__fearful_6"] = "Ya no miro. Avísame cuando hayas ganado. O no.",
	["COMP_SAY_NOTICE__fearful_7"] = "¡Sangras! Otra vez tus heroicidades, ¿eh? ¡Aguanta!",
	["COMP_SAY_NOTICE__fearful_8"] = "Se me caen las plumas del susto. Date prisa, por favor.",
	["COMP_SAY_NOTICE__glutton"] = "¿Tienes algo para picar?",
	["COMP_SAY_NOTICE__glutton_2"] = "Hace rato que no comemos, ¿verdad?",
	["COMP_SAY_NOTICE__glutton_3"] = "Tengo un poco de hambre. Poquita. Muchísima, en realidad.",
	["COMP_SAY_NOTICE__glutton_4"] = "Mi barriga está en huelga. ¿Vas a permitirlo?",
	["COMP_SAY_NOTICE__glutton_5"] = "Tengo tanta hambre que tu bolsa huele a jamón. ¿Huele a jamón?",
	["COMP_SAY_NOTICE__glutton_6"] = "¿Oíste ese rugido? No era un oso. Era yo.",
	["COMP_SAY_NOTICE__glutton_7"] = "¿Cuándo comemos? Ahora sería perfecto. O ya mismo.",
	["COMP_SAY_NOTICE__glutton_8"] = "Empiezo a mirar a las ardillas con hambre. Esto es serio.",
	["COMP_SAY_NOTICE__glutton_9"] = "Algo de picar, por favor… Pondré ojitos. Mira, ya los pongo.",
	["COMP_SAY_NOTICE__lazy"] = "Hace siglos que no descansamos… solo lo digo.",
	["COMP_SAY_NOTICE__lazy_2"] = "Una posada, un fuego, una cama… ¿no los echas de menos?",
	["COMP_SAY_NOTICE__lazy_3"] = "Cuarenta minutos sin parar… ¿estás corriendo un maratón?",
	["COMP_SAY_NOTICE__lazy_4"] = "Mis patas han puesto una queja. Exigen una posada.",
	["COMP_SAY_NOTICE__lazy_5"] = "No descansamos desde… no me acuerdo. Demasiado.",
	["COMP_SAY_NOTICE__lazy_6"] = "¿Nunca te cansas? Cansa solo de verte.",
	["COMP_SAY_NOTICE__lazy_7"] = "Veo una hoguera en sueños. ¿Me encuentras una de verdad?",
	["COMP_SAY_NOTICE__lazy_8"] = "Si no paramos pronto, me dormiré andando. Ya me ha pasado.",
	["COMP_SAY_NOTICE__mischievous"] = "Tengo una idea tonta… ¿quieres saberla? ¿No? ¡Bueno!",
	["COMP_SAY_NOTICE__mischievous_2"] = "¡Psst! ¡Mira detrás de ti! Jiji, nada de nada.",
	["COMP_SAY_NOTICE__mischievous_3"] = "Te escondí la Piedra de hogar. Jiji, no. Pero lo comprobaste, admítelo.",
	["COMP_SAY_NOTICE__mischievous_4"] = "Tienes algo en el hombro. Ah, espera, soy yo. ¡Jiji!",
	["COMP_SAY_NOTICE__mischievous_5"] = "Cambié tu mapa por un dibujo de un pato. Te pierdes igual.",
	["COMP_SAY_NOTICE__mischievous_6"] = "¡Psst! Ese vendedor de ahí, ¿le cambiamos los precios? ¿Por diversión?",
	["COMP_SAY_NOTICE__mischievous_7"] = "Te até un cascabel a la bolsa. ¿Lo oyes? ¡Tilín, tilín!",
	["COMP_SAY_NOTICE__mischievous_8"] = "Nueva broma: finjo portarme bien cinco minutos. Uno…",
	["COMP_SAY_NOTICE__mischievous_9"] = "¡Jiji! Pisaste un charco de chispitas. ¿A propósito? Yo sí.",
	["COMP_SAY_NOTICE__mystic"] = "Ha caído la noche… las estrellas están habladoras hoy.",
	["COMP_SAY_NOTICE__mystic_2"] = "Mira el cielo. Algo está pasando.",
	["COMP_SAY_NOTICE__mystic_3"] = "Cae la noche… la hora en que mejor te pierdes.",
	["COMP_SAY_NOTICE__mystic_4"] = "Sale la luna. Ha visto todas tus caídas, ¿sabes?",
	["COMP_SAY_NOTICE__mystic_5"] = "Es de noche. Salen los espíritus… y hablan de ti.",
	["COMP_SAY_NOTICE__mystic_6"] = "Se encienden las estrellas. Una te guiña el ojo.",
	["COMP_SAY_NOTICE__mystic_7"] = "Oscuridad total. Buen momento para leer el futuro. O un mapa.",
	["COMP_SAY_NOTICE__mystic_8"] = "El cielo nocturno susurra… «Otra vez se olvidó la antorcha».",
	["COMP_SAY_NOTICE__parrot"] = "¡%s! ¡%s! ¡Cuac!",
	["COMP_SAY_NOTICE__parrot_2"] = "¡Zona nueva! ¡%s! ¡Bonito nombre! ¡Cuac!",
	["COMP_SAY_NOTICE__parrot_3"] = "¡%s! ¿Perdido? ¿Perdido? ¡Cuac!",
	["COMP_SAY_NOTICE__parrot_4"] = "¡Bienvenido a %s! ¡%s! ¡Cuac!",
	["COMP_SAY_NOTICE__parrot_5"] = "¡%s! ¡A Lorito le gusta! ¡A Lorito le gusta!",
	["COMP_SAY_NOTICE__parrot_6"] = "¿%s? ¡%s! ¡Cuac! ¡Nombre bonito!",
	["COMP_SAY_NOTICE__parrot_7"] = "¡Nuevo! ¡%s! ¡Aquí no se muere! ¡Cuac!",
	["COMP_SAY_NOTICE__parrot_8"] = "¡%s! ¡Mapa! ¡Mapa! ¡Mira el mapa!",
	["COMP_SAY_NOTICE__sly"] = "Sss… buen botín. Lo vi antes que tú.",
	["COMP_SAY_NOTICE__sly_2"] = "Eso vale oro. Guárdalo bien.",
	["COMP_SAY_NOTICE__sly_3"] = "Sss… entra oro. Mi sonido favorito.",
	["COMP_SAY_NOTICE__sly_4"] = "Una moneda de oro más. No la gastes en pan.",
	["COMP_SAY_NOTICE__sly_5"] = "¡Te estás haciendo rico! Por fin. Empezaba a dudar.",
	["COMP_SAY_NOTICE__sly_6"] = "¡Oro! Escóndelo. No, ahí no. En otro sitio.",
	["COMP_SAY_NOTICE__sly_7"] = "Sss… eso pasa cuando me haces caso.",
	["COMP_SAY_NOTICE__sly_8"] = "Bonita suma. ¿Reinvertir? En una bolsa más grande, para empezar.",
	["COMP_SAY_NOTICE__teasing"] = "¡¿Otra vez?! Lo haces a propósito, admítelo.",
	["COMP_SAY_NOTICE__teasing_10"] = "¡Otra! ¡Otra! Ah, espera, no era un espectáculo.",
	["COMP_SAY_NOTICE__teasing_2"] = "Dos veces seguidas… ya empiezo a llevar la cuenta.",
	["COMP_SAY_NOTICE__teasing_3"] = "¡Dos muertes en diez minutos! ¿Récord personal?",
	["COMP_SAY_NOTICE__teasing_4"] = "Ya tienes tarjeta de cliente en el cementerio.",
	["COMP_SAY_NOTICE__teasing_5"] = "El ángel del cementerio me preguntó si estás bien.",
	["COMP_SAY_NOTICE__teasing_6"] = "El suelo te quiere. Te ve muy a menudo.",
	["COMP_SAY_NOTICE__teasing_7"] = "Una idea loca: no te mueras.",
	["COMP_SAY_NOTICE__teasing_8"] = "¿Otra vez en el suelo? Montemos ahí una tienda.",
	["COMP_SAY_NOTICE__teasing_9"] = "¿Vas y vuelves? Vas a gastar el camino del cementerio.",
	["COMP_SAY_NOTICE__tinker"] = "Tu equipo chirría. ¿Lo engraso? Listo, hecho.",
	["COMP_SAY_NOTICE__tinker_2"] = "¡Tengo una idea para un invento! …Explotó. Mejor no hablemos de ello.",
	["COMP_SAY_NOTICE__tinker_3"] = "Informe de mantenimiento: has recogido 14 objetos grises. ¿Por qué?",
	["COMP_SAY_NOTICE__tinker_4"] = "He medido tu velocidad al andar. Podríamos ponerte ruedas.",
	["COMP_SAY_NOTICE__tinker_5"] = "Análisis de ruta: tres cambios de sentido. Mi brújula llora.",
	["COMP_SAY_NOTICE__tinker_6"] = "¿Me prestas la espada? Quiero ponerle un motor. ¿No? Lástima.",
	["COMP_SAY_NOTICE__tinker_7"] = "¡Bip! Aviso automático: tu armadura hace un ruido raro.",
	["COMP_SAY_NOTICE__tinker_8"] = "Te arreglé el farol. ¿No estaba roto? ¿Funcionaba? Ahora sí está roto.",
	["COMP_SAY_NOTICE__wise"] = "Uuh. Nueva tierra, nueva lección.",
	["COMP_SAY_NOTICE__wise_2"] = "Dicen que aquí el viento trae viejas historias.",
	["COMP_SAY_NOTICE__wise_3"] = "Uuh. Nueva tierra. Esta vez deja el mapa abierto.",
	["COMP_SAY_NOTICE__wise_4"] = "Una tierra desconocida. Aquí los monstruos no te conocen. Aprovecha.",
	["COMP_SAY_NOTICE__wise_5"] = "El viajero sabio busca primero la posada. Y el cementerio.",
	["COMP_SAY_NOTICE__wise_6"] = "Nueva tierra. El mismo suelo, las mismas ganas de caerte en él.",
	["COMP_SAY_NOTICE__wise_7"] = "Aquí cada piedra tiene una historia. No las recojas todas.",
	["COMP_SAY_NOTICE__wise_8"] = "Uuh. Entrar es fácil. Salir con vida, no tanto.",
	["COMP_SAY_NOTICE__zen"] = "Te falta el aliento. Tómate un minuto para ti.",
	["COMP_SAY_NOTICE__zen_2"] = "Con calma. El camino no se va a ir.",
	["COMP_SAY_NOTICE__zen_3"] = "Estás a media salud. Recupera la otra mitad sentándote.",
	["COMP_SAY_NOTICE__zen_4"] = "Respiras muy fuerte. El combate ya terminó, ¿sabes?",
	["COMP_SAY_NOTICE__zen_5"] = "Herido, pero en pie. Siéntate de todos modos.",
	["COMP_SAY_NOTICE__zen_6"] = "Tu barra de salud está triste. Una comida, un suspiro y en marcha.",
	["COMP_SAY_NOTICE__zen_7"] = "¿Te vas así? El sabio come primero. El impaciente muere primero.",
	["COMP_SAY_NOTICE__zen_8"] = "Una pausa, ya. El próximo lobo no tendrá piedad.",
	["COMP_SAY_NPC_CT_beast"] = "¿Una bestia que habla? ¿O soy yo?",
	["COMP_SAY_NPC_CT_beast_2"] = "Primero se olfatea, es de buena educación.",
	["COMP_SAY_NPC_CT_beast_3"] = "A este lo entiendo. Somos colegas.",
	["COMP_SAY_NPC_CT_beast_4"] = "No le des tu merienda, que es mía.",
	["COMP_SAY_NPC_CT_beast_5"] = "Me mira de reojo. Envidia de pelaje.",
	["COMP_SAY_NPC_CT_beast_6"] = "Huele a bosque. Tú hueles a viaje.",
	["COMP_SAY_NPC_CT_beast_7"] = "Somos familia, más o menos.",
	["COMP_SAY_NPC_CT_critter"] = "¡Ay, uno chiquito! ¿Amigos?",
	["COMP_SAY_NPC_CT_critter_2"] = "A este sí puedo mirarlo a los ojos.",
	["COMP_SAY_NPC_CT_critter_3"] = "No lo ataques. Ya te he visto con los conejos.",
	["COMP_SAY_NPC_CT_critter_4"] = "¿Más mono que yo? Imposible.",
	["COMP_SAY_NPC_CT_critter_5"] = "Al menos este no se pierde.",
	["COMP_SAY_NPC_CT_critter_6"] = "¡Hola, pequeño! No te asustes de su armadura.",
	["COMP_SAY_NPC_CT_demon"] = "Cuernos y sonrisa. No me convence.",
	["COMP_SAY_NPC_CT_demon_2"] = "Cerca de %s, sujeta bien la bolsa.",
	["COMP_SAY_NPC_CT_demon_3"] = "Huele a azufre… con educación.",
	["COMP_SAY_NPC_CT_demon_4"] = "No firmes nada. En serio, nada.",
	["COMP_SAY_NPC_CT_demon_5"] = "%s sonríe demasiado. No me fío de las sonrisas grandes.",
	["COMP_SAY_NPC_CT_demon_6"] = "Bonitos cuernos. No se lo diré.",
	["COMP_SAY_NPC_CT_demon_7"] = "Saludamos y retrocedemos despacito.",
	["COMP_SAY_NPC_CT_dragonkin"] = "¡Un primo lejano! Bueno… muy lejano.",
	["COMP_SAY_NPC_CT_dragonkin_2"] = "%s tiene unas escamas preciosas. Qué envidia.",
	["COMP_SAY_NPC_CT_dragonkin_3"] = "Habla bajito, los dragones lo oyen todo.",
	["COMP_SAY_NPC_CT_dragonkin_4"] = "No menciones a su abuela, por si acaso.",
	["COMP_SAY_NPC_CT_dragonkin_5"] = "%s podría asarte de un soplido. Sé educado.",
	["COMP_SAY_NPC_CT_dragonkin_6"] = "¿Guarda un tesoro? Pregunto por un amigo.",
	["COMP_SAY_NPC_CT_dragonkin_7"] = "Algún día yo también tendré alas. Quizá.",
	["COMP_SAY_NPC_CT_elemental"] = "¿De qué está hecho? ¿De viento?",
	["COMP_SAY_NPC_CT_elemental_2"] = "No me acerco mucho, que me derrito.",
	["COMP_SAY_NPC_CT_elemental_3"] = "%s brilla un poco. ¿Es normal?",
	["COMP_SAY_NPC_CT_elemental_4"] = "No lo toques. Ni idea de lo que pasaría.",
	["COMP_SAY_NPC_CT_elemental_5"] = "%s retumba suavecito. ¿Está charlando?",
	["COMP_SAY_NPC_CT_elemental_6"] = "¿Todo roca? ¿Todo agua? Me lío.",
	["COMP_SAY_NPC_CT_elemental_7"] = "Nada de estornudar cerca, por favor.",
	["COMP_SAY_NPC_CT_giant"] = "Mira arriba… más… más… ahí.",
	["COMP_SAY_NPC_CT_giant_2"] = "%s es grande. Muy grande. Me quedo detrás de ti.",
	["COMP_SAY_NPC_CT_giant_3"] = "No le pises los pies. Bueno, al revés.",
	["COMP_SAY_NPC_CT_giant_4"] = "%s tiene manos enormes. Mejor fuera de su alcance.",
	["COMP_SAY_NPC_CT_giant_5"] = "Me siento diminuto. Más que de costumbre.",
	["COMP_SAY_NPC_CT_giant_6"] = "Si estornuda, salimos volando. Suavemente.",
	["COMP_SAY_NPC_CT_mechanical"] = "¿Bip bup? Creo que me ha entendido.",
	["COMP_SAY_NPC_CT_mechanical_2"] = "%s hace tic-tac. ¿Habrá que darle cuerda?",
	["COMP_SAY_NPC_CT_mechanical_3"] = "¡Una máquina que habla! Los gnomos están locos.",
	["COMP_SAY_NPC_CT_mechanical_4"] = "No le preguntes la hora, lo calculará todo.",
	["COMP_SAY_NPC_CT_mechanical_5"] = "%s echa humo. ¿Enfadado o solo encendido?",
	["COMP_SAY_NPC_CT_mechanical_6"] = "Un tornillo flojo y puf. Cuidado.",
	["COMP_SAY_NPC_CT_mechanical_7"] = "Tiene más engranajes que tú ideas. Je, je.",
	["COMP_SAY_NPC_CT_undead"] = "Huele un poco a cripta, pero parece majo.",
	["COMP_SAY_NPC_CT_undead_2"] = "%s ha perdido algo de color… y algo de piel.",
	["COMP_SAY_NPC_CT_undead_3"] = "No mires los huesos. No mires los huesos.",
	["COMP_SAY_NPC_CT_undead_4"] = "No le preguntes cómo está. Tema delicado.",
	["COMP_SAY_NPC_CT_undead_5"] = "%s tiene mejor aspecto que tú tras una caída.",
	["COMP_SAY_NPC_CT_undead_6"] = "Conoce el cementerio. Como tú, a menudo.",
	["COMP_SAY_NPC_CT_undead_7"] = "¿Le falta la mandíbula? No, es una sonrisa.",
	["COMP_SAY_NPC_banker"] = "¡Un banquero! Guarda tus tesoros.",
	["COMP_SAY_NPC_banker_10"] = "Una cámara ordenada es algo raro. La tuya no, ojo.",
	["COMP_SAY_NPC_banker_11"] = "%s frunce el ceño ante tu desorden.",
	["COMP_SAY_NPC_banker_12"] = "Guarda aquí tus materiales, tus bolsas te lo agradecerán.",
	["COMP_SAY_NPC_banker_13"] = "¿A mí también me pueden depositar? ¿No? Uf.",
	["COMP_SAY_NPC_banker_2"] = "%s cuenta rápido. Muy rápido. ¿Demasiado?",
	["COMP_SAY_NPC_banker_3"] = "Deja lo que te llena las bolsas. Respira tranquilo.",
	["COMP_SAY_NPC_banker_4"] = "Aquí todo está a salvo. ¿Hasta mis galletas?",
	["COMP_SAY_NPC_banker_5"] = "Me encanta el banco: huele a monedas viejas.",
	["COMP_SAY_NPC_banker_6"] = "¿Guardando cosas que nunca volverás a usar?",
	["COMP_SAY_NPC_banker_7"] = "%s conoce todos tus secretos. Sobre todo tus botas viejas.",
	["COMP_SAY_NPC_banker_8"] = "Tu banco es un museo de trastos.",
	["COMP_SAY_NPC_banker_9"] = "Deposito, no deposito… llevas diez minutos dudando.",
	["COMP_SAY_NPC_flight"] = "¿Nos vamos volando? ¡Me agarro a tu bolsa!",
	["COMP_SAY_NPC_flight_10"] = "Volando es el único momento en que no te pierdes.",
	["COMP_SAY_NPC_flight_11"] = "%s acaricia a la montura. A mí también me gustan las caricias.",
	["COMP_SAY_NPC_flight_12"] = "Abróchate el cinturón. Ah, no hay. Suerte.",
	["COMP_SAY_NPC_flight_13"] = "¿Una siesta en vuelo? Te despierto al llegar.",
	["COMP_SAY_NPC_flight_2"] = "Se nota que %s cuida bien de las monturas.",
	["COMP_SAY_NPC_flight_3"] = "Desde allá arriba todo parece diminuto. Hasta tú.",
	["COMP_SAY_NPC_flight_4"] = "¿Un vuelo? Ojalá me toque ventanilla.",
	["COMP_SAY_NPC_flight_5"] = "¡El camino del cielo! Mucho más rápido que andar.",
	["COMP_SAY_NPC_flight_6"] = "¿Un vuelo? Por fin descansan tus pies.",
	["COMP_SAY_NPC_flight_7"] = "%s ha visto tu sentido de la orientación. Mejor volar.",
	["COMP_SAY_NPC_flight_8"] = "No te asomes, ya tienes bastantes moratones.",
	["COMP_SAY_NPC_flight_9"] = "Esta vez acuérdate de aprender la ruta de vuelo.",
	["COMP_SAY_NPC_innkeeper"] = "¡Un tabernero! Huele a pan caliente.",
	["COMP_SAY_NPC_innkeeper_10"] = "Pide una habitación tranquila. Roncas.",
	["COMP_SAY_NPC_innkeeper_11"] = "Aquí se duerme calentito. No en el suelo junto a un jabalí.",
	["COMP_SAY_NPC_innkeeper_12"] = "El tabernero me guiñó un ojo. Somos colegas.",
	["COMP_SAY_NPC_innkeeper_13"] = "%s sirve la mejor sopa de la zona. Dicen.",
	["COMP_SAY_NPC_innkeeper_2"] = "%s parece buena compañía. Me cae bien.",
	["COMP_SAY_NPC_innkeeper_3"] = "¿Vincularte aquí? Buen sitio al que volver.",
	["COMP_SAY_NPC_innkeeper_4"] = "¡Pregunta si queda sopa!",
	["COMP_SAY_NPC_innkeeper_5"] = "Los taberneros lo saben todo. Pero no lo cuentan.",
	["COMP_SAY_NPC_innkeeper_6"] = "¿Tú otra vez? %s va a empezar a reservarte cuarto.",
	["COMP_SAY_NPC_innkeeper_7"] = "Sopa para ti, un cojín para mí.",
	["COMP_SAY_NPC_innkeeper_8"] = "Vincúlate aquí: la próxima vez que caigas, andarás menos.",
	["COMP_SAY_NPC_innkeeper_9"] = "%s ha visto a muchos héroes. Y ahora a ti.",
	["COMP_SAY_NPC_merchant"] = "Este mercader parece honrado… igual vigilo tu bolsa.",
	["COMP_SAY_NPC_merchant_10"] = "¡Por fin tus bolsas llenas de trastos dan dinero!",
	["COMP_SAY_NPC_merchant_11"] = "%s cuenta tus monedas… no tardará mucho.",
	["COMP_SAY_NPC_merchant_12"] = "Vende todos los grises, guárdame la galleta.",
	["COMP_SAY_NPC_merchant_13"] = "Regateas como un conejito. Déjamelo a mí.",
	["COMP_SAY_NPC_merchant_14"] = "¡Un mercader! ¿Comprará pieles estropeadas? Tienes un montón.",
	["COMP_SAY_NPC_merchant_2"] = "¿Vendes los grises? ¡Yo cuento las monedas!",
	["COMP_SAY_NPC_merchant_3"] = "%s tiene cosas bonitas. ¿Me compras algo?",
	["COMP_SAY_NPC_merchant_4"] = "¡Regatea! Pon ojitos de cachorro, como yo.",
	["COMP_SAY_NPC_merchant_5"] = "¡Un mercader! ¿Tendrá galletas?",
	["COMP_SAY_NPC_merchant_6"] = "%s sonríe mucho. ¿Demasiado? No, está bien.",
	["COMP_SAY_NPC_merchant_7"] = "¿Otra vez vendiendo tus piedrecitas grises?",
	["COMP_SAY_NPC_merchant_8"] = "A %s le encantará tu colección de dientes de lobo.",
	["COMP_SAY_NPC_merchant_9"] = "Compra algo útil. Por una vez.",
	["COMP_SAY_NPC_quest"] = "¡Alguien más te necesita!",
	["COMP_SAY_NPC_quest_10"] = "%s confía en ti. No le falles demasiado.",
	["COMP_SAY_NPC_quest_11"] = "¡Una misión de reparto! A tus pies les va a encantar.",
	["COMP_SAY_NPC_quest_12"] = "La aceptas, la olvidas en el registro, ya me lo sé.",
	["COMP_SAY_NPC_quest_13"] = "Parece sencilla. Nunca es sencilla.",
	["COMP_SAY_NPC_quest_14"] = "%s tiene un signo de exclamación. Yo también, cuando tengo hambre.",
	["COMP_SAY_NPC_quest_2"] = "%s parece preocupado. ¿Ayudamos?",
	["COMP_SAY_NPC_quest_3"] = "¡Una misión! ¡Di que sí, di que sí!",
	["COMP_SAY_NPC_quest_4"] = "Lee con atención, yo me perdí la mitad.",
	["COMP_SAY_NPC_quest_5"] = "Huele a aventura… y quizá a jabalíes.",
	["COMP_SAY_NPC_quest_6"] = "%s cuenta contigo. ¡Y yo también!",
	["COMP_SAY_NPC_quest_7"] = "¿Diez jabalíes más? Le dices que sí a todo.",
	["COMP_SAY_NPC_quest_8"] = "%s ha perdido algo. Como siempre.",
	["COMP_SAY_NPC_quest_9"] = "Esta vez lee el objetivo hasta el final.",
	["COMP_SAY_NPC_talk"] = "¡Alguien parlanchín! Me encantan los cotilleos.",
	["COMP_SAY_NPC_talk_10"] = "¡Sonríe! Nunca se sabe, quizá tenga una misión.",
	["COMP_SAY_NPC_talk_11"] = "Asiento. Es lo que hago cuando desconecto.",
	["COMP_SAY_NPC_talk_12"] = "Otro desconocido. Haces amigos en todas partes.",
	["COMP_SAY_NPC_talk_13"] = "%s no tiene prisa. Al contrario que tú.",
	["COMP_SAY_NPC_talk_2"] = "%s parece simpático. ¿Charlamos?",
	["COMP_SAY_NPC_talk_3"] = "Pregúntale si conoce un buen sitio para merendar.",
	["COMP_SAY_NPC_talk_4"] = "Mmm… no sé qué pensar. Seré educado.",
	["COMP_SAY_NPC_talk_5"] = "¡Otro encuentro! El mundo está lleno de gente.",
	["COMP_SAY_NPC_talk_6"] = "Habla mucho. Como tú cuando te pierdes.",
	["COMP_SAY_NPC_talk_7"] = "%s tiene historias que contar. Yo tengo hambre.",
	["COMP_SAY_NPC_talk_8"] = "Pregúntale el camino, para variar.",
	["COMP_SAY_NPC_talk_9"] = "%s te mira de arriba abajo. Por la armadura, seguro.",
	["COMP_SAY_NPC_trainer"] = "¡Un instructor! Enséñame a mí también, tomo apuntes.",
	["COMP_SAY_NPC_trainer_10"] = "%s te mira como a un alumno que llega tarde.",
	["COMP_SAY_NPC_trainer_11"] = "Pon tus nuevos hechizos en la barra, ¿vale?",
	["COMP_SAY_NPC_trainer_12"] = "¿Por fin pegarás más fuerte que un conejo enfadado?",
	["COMP_SAY_NPC_trainer_13"] = "¡Un instructor! Haré como que lo entiendo todo.",
	["COMP_SAY_NPC_trainer_2"] = "%s parece estricto… pero justo.",
	["COMP_SAY_NPC_trainer_3"] = "¿Hechizos nuevos? ¡Hazme una demostración!",
	["COMP_SAY_NPC_trainer_4"] = "El saber es caro. Pero lo vale.",
	["COMP_SAY_NPC_trainer_5"] = "Escucha bien, luego te pregunto.",
	["COMP_SAY_NPC_trainer_6"] = "¿Cuántos niveles desde tu última visita?",
	["COMP_SAY_NPC_trainer_7"] = "%s te va a vaciar la bolsa otra vez. Por una buena causa.",
	["COMP_SAY_NPC_trainer_8"] = "¡Hechizo nuevo! Intenta no lanzártelo a ti.",
	["COMP_SAY_NPC_trainer_9"] = "Pregúntale tú. A mí me da miedo.",
	["COMP_SAY_PET_V_gfw"] = "¡Jo, jo, jo! ¡Me haces cosquillas en la barba!",
	["COMP_SAY_PET_V_gfw_2"] = "Acabas de saltar al primer puesto de la lista de los buenos.",
	["COMP_SAY_PET_V_gfw_3"] = "¿Una caricia? Eso vale un caramelo. Toma, apenas pega.",
	["COMP_SAY_PET_V_metzen"] = "¡Las astas no! El cuello, sí. Ahí.",
	["COMP_SAY_PET_V_metzen_2"] = "Mmm. Aceptable. Puedes continuar.",
	["COMP_SAY_PET_V_metzen_3"] = "Finjo que no me gusta. No se lo digas a nadie.",
	["COMP_SAY_PET_V_snowman"] = "¡Je, je! ¡Despacio, que me derrito de alegría!",
	["COMP_SAY_PET_V_snowman_2"] = "Tienes las manos calientes… pero me gusta. Un poco más.",
	["COMP_SAY_PET_V_snowman_3"] = "¡Me has vuelto a poner el botón! ¡Gracias!",
	["COMP_SAY_PET_sleepy"] = "¿Eh? ¡Ah, eres tú! ¡Hola!",
	["COMP_SAY_PET_sleepy_2"] = "Mmm… cinco minutitos más… ¡no, ya estoy!",
	["COMP_SAY_PET_sleepy_3"] = "¡Oh! Un mimo para despertar, qué lujo.",
	["COMP_SAY_PET_sleepy_4"] = "¿Eh? ¿Dormí mucho? ¿Cuántas veces te perdiste?",
	["COMP_SAY_PET_sleepy_5"] = "Mmm… ¿me despiertas para un mimo? Vale, merece la pena.",
	["COMP_SAY_PET_sleepy_6"] = "Zzz… ¿qué? ¿Un combate? ¿No? Pues a dormir… ¡no, ya estoy!",
	["COMP_SAY_PET_sleepy_7"] = "Ah, eres tú. Soñé que encontrabas el camino a la primera.",
	["COMP_SAY_QUEST"] = "¡Misión cumplida!",
	["COMP_SAY_QUEST_10"] = "¡Misión cumplida! Hasta encontraste al PNJ correcto a la primera.",
	["COMP_SAY_QUEST_11"] = "¡Listo! Diez pieles de lobo para un tipo que quería diez. Tiene lógica.",
	["COMP_SAY_QUEST_12"] = "¡Misión hecha! ¿La recompensa es gris? Solo digo.",
	["COMP_SAY_QUEST_13"] = "¡Entregada! ¿Esta vez leíste el texto? ¿No? Yo tampoco.",
	["COMP_SAY_QUEST_14"] = "¡Bien hecho! Te da las gracias y ya tiene otro favor que pedirte.",
	["COMP_SAY_QUEST_15"] = "¡Una más! Tu registro de misiones respira un poco.",
	["COMP_SAY_QUEST_16"] = "¡Misión hecha! No hablaremos de las dos veces que mataste a la bestia equivocada.",
	["COMP_SAY_QUEST_17"] = "¡Hecho! Valieron la pena esos seis kilómetros a pie.",
	["COMP_SAY_QUEST_2"] = "¡Otra más hecha! Qué talento.",
	["COMP_SAY_QUEST_3"] = "¡Misión hecha! Espero que la recompensa se pueda comer.",
	["COMP_SAY_QUEST_4"] = "¡Bien hecho! Te deben una muy grande.",
	["COMP_SAY_QUEST_5"] = "Un problema menos, gracias a ti.",
	["COMP_SAY_QUEST_6"] = "Te lo dije: ¡pan comido!",
	["COMP_SAY_QUEST_7"] = "Una misión entregada, una sonrisa ganada.",
	["COMP_SAY_QUEST_8"] = "¡Misión hecha! Te costó tres viajes de ida y vuelta, pero bueno.",
