	["COMP_SAY_TUTO_3"] = "Come, descansa en la ciudad, explora: cada uno dura 45 minutos. ¡Los tres, y estoy radiante!",
	["COMP_SAY_TUTO_4"] = "Crezco con tus niveles: 10, 20, 40 y 60. Nunca hacia atrás.",
	["COMP_SAY_TUTO_5"] = "Completa una zona al 100%% (diario, /qc): se abre un cofre, con un aspecto o un adorno para mí.",
	["COMP_SAY_TUTO_6"] = "En el camino te avisaré: bolsas llenas, comida, reparaciones, munición, un élite cerca…",
	["COMP_SAY_TUTO_7"] = "¿Hablo demasiado? ¿Poco? Ajústame con el control \"Locuacidad\", página Compañero.",
	["COMP_SAY_TUTO_8"] = "Para personalizarme: ajustes, página Compañero. ¡Y en cuanto derrotes a un monstruo, te explico la red!",
	["COMP_SAY_UNLOCK"] = "Mira: ¡%s!",
	["COMP_SAY_UNLOCK_2"] = "¿Para mí? ¡%s! ¡Gracias!",
	["COMP_SAY_UNLOCK_3"] = "Nuevo: ¡%s! Me siento tan elegante.",
	["COMP_SAY_UNLOCK_4"] = "¡%s! ¿Se lo enseñamos a todos?",
	["COMP_SAY_UNLOCK_5"] = "¡%s! Por fin algo de clase en este dúo.",
	["COMP_SAY_UNLOCK_6"] = "¡Oh, %s! Más elegante que tu armadura desparejada.",
	["COMP_SAY_UNLOCK_7"] = "¡%s para mí! Los otros compañeros tendrán envidia.",
	["COMP_SAY_UNLOCK_8"] = "Desbloqueado: ¡%s! Soy el más guapo, es oficial.",
	["COMP_SAY_VIEW"] = "¡Qué vistas!",
	["COMP_SAY_VIEW_10"] = "Aquí todo es nuevo. Hasta las formas de perderse.",
	["COMP_SAY_VIEW_11"] = "¡Región nueva! Localizo el cementerio más cercano, por si acaso.",
	["COMP_SAY_VIEW_12"] = "¡Guau! ¿Vinimos aquí a propósito o por accidente?",
	["COMP_SAY_VIEW_13"] = "¡Qué paisaje! Para dos segundos, no muerde.",
	["COMP_SAY_VIEW_14"] = "¡Tierra inexplorada! Bueno, para ti. Yo leí la guía.",
	["COMP_SAY_VIEW_2"] = "¡Oh! ¡Un lugar nuevecito!",
	["COMP_SAY_VIEW_3"] = "Nunca había estado aquí. ¿Tú tampoco?",
	["COMP_SAY_VIEW_4"] = "Por aquí huele a aventura.",
	["COMP_SAY_VIEW_5"] = "¡Mira el cielo! Aquí es distinto.",
	["COMP_SAY_VIEW_6"] = "¡Nueva región, nuevas historias!",
	["COMP_SAY_VIEW_7"] = "¡Zona nueva! ¿Tienes mapa? ¿Sabes usarlo?",
	["COMP_SAY_VIEW_8"] = "¡Oh, qué bonito! Intenta no morir enseguida, disfrútalo.",
	["COMP_SAY_VIEW_9"] = "¡Un sitio nuevo! Los monstruos de aquí aún no te conocen. Qué suerte tienen.",
	["COMP_SAY_VIEW_V_gfw"] = "¡Una tierra nueva! La añado a mi ruta.",
	["COMP_SAY_VIEW_V_gfw_2"] = "Bonitas vistas. Me pregunto si aquí las chimeneas son anchas.",
	["COMP_SAY_VIEW_V_metzen"] = "¡Ruta nueva! Me la aprendo para el reparto.",
	["COMP_SAY_VIEW_V_metzen_2"] = "Buen tramo. Perfecto para coger carrerilla.",
	["COMP_SAY_VIEW_V_snowman"] = "¡Un sitio nuevo! ¿Hay nieve? ¿No? Aun así es bonito.",
	["COMP_SAY_VIEW_V_snowman_2"] = "¡Guau! Nunca había visto esto. Nunca había visto nada, la verdad.",
	["COMP_SAY_VIEW__cuddly"] = "Es precioso… y más contigo.",
	["COMP_SAY_VIEW__cuddly_2"] = "¡Un sitio nuevo! Abrázame fuerte, por si acaso.",
	["COMP_SAY_VIEW__cuddly_3"] = "Qué bonito es esto. ¿Una foto de los dos?",
	["COMP_SAY_VIEW__cuddly_4"] = "¡Lo descubrimos juntos! No te pierdas, ¿vale?",
	["COMP_SAY_VIEW__cuddly_5"] = "Aquí no conozco a nadie… salvo a ti. Me basta.",
	["COMP_SAY_VIEW__cuddly_6"] = "¡Oh, estas vistas! Casi tan bonitas como tu sonrisa.",
	["COMP_SAY_VIEW__cuddly_7"] = "¿Otro rodeo? No me quejo, me gusta seguirte.",
	["COMP_SAY_VIEW__curious"] = "¡Oh! ¡Nunca había visto esto! ¿Echamos un vistazo?",
	["COMP_SAY_VIEW__curious_2"] = "¡Un sitio nuevo! ¡Quiero verlo todo, ya!",
	["COMP_SAY_VIEW__curious_3"] = "¡Mira! ¡Y ahí! ¡Y allá! ¿Qué hay allá?",
	["COMP_SAY_VIEW__curious_4"] = "¡Zona nueva! ¿Sabes dónde estamos o vamos a ciegas otra vez?",
	["COMP_SAY_VIEW__curious_5"] = "¡Guau! ¿Llegamos a propósito o nos perdimos?",
	["COMP_SAY_VIEW__curious_6"] = "¿Quién construyó eso? ¿Cuándo? ¿Por qué? ¿No lo sabes? Vale.",
	["COMP_SAY_VIEW__curious_7"] = "¡Un sitio nuevo! ¿Lo exploramos todo, hasta los rincones raros?",
	["COMP_SAY_VIEW__curious_8"] = "¿Ves esa torre? ¿Subimos? Te dan miedo las alturas, ¿eh?",
	["COMP_SAY_VIEW__curious_9"] = "¿Qué es ese ruido? ¿Y ese olor? ¿Y esa cosa que se mueve?",
	["COMP_SAY_VIEW__daring"] = "¡Zona nueva! ¿Hay monstruos a los que enfrentarse?",
	["COMP_SAY_VIEW__daring_2"] = "¡Por aquí huele a aventura!",
	["COMP_SAY_VIEW__daring_3"] = "¡Zona nueva! ¿Quién es el más grande aquí? Vamos a saludar.",
	["COMP_SAY_VIEW__daring_4"] = "Bonitas vistas. Bonitas vistas de enemigos, sobre todo. ¡Perfecto!",
	["COMP_SAY_VIEW__daring_5"] = "¡Nuevo patio de juegos! Intenta no morir en él enseguida.",
	["COMP_SAY_VIEW__daring_6"] = "¡Un sitio nuevo! Huelo monstruos. Y un poco de miedo. El tuyo.",
	["COMP_SAY_VIEW__daring_7"] = "¿Conquistamos esta tierra? Tú delante, yo justo detrás.",
	["COMP_SAY_VIEW__daring_8"] = "Aquí todo quiere comernos. ¡Me encanta este sitio!",
	["COMP_SAY_VIEW__fearful"] = "Es bonito… y seguro que hay lobos. ¿Verdad?",
	["COMP_SAY_VIEW__fearful_2"] = "¡Un sitio nuevo! Me quedo pegadito a ti.",
	["COMP_SAY_VIEW__fearful_3"] = "Sitio nuevo… ¿dónde está la salida más cercana? Solo pregunto.",
	["COMP_SAY_VIEW__fearful_4"] = "Es bonito. Demasiado. Ahí suelen esconderse los monstruos.",
	["COMP_SAY_VIEW__fearful_5"] = "¿Sabes siquiera dónde estamos? No me digas que te has vuelto a perder.",
	["COMP_SAY_VIEW__fearful_6"] = "¡Coc! ¡Sombras por todas partes! Ah, no, son árboles. Perdón.",
	["COMP_SAY_VIEW__fearful_7"] = "Acabamos de llegar y ya quiero volver a casa.",
	["COMP_SAY_VIEW__fearful_8"] = "Aquí parece todo tranquilo. No hagas enfadar a nadie, ¿vale?",
	["COMP_SAY_VIEW__glutton"] = "¡Buen sitio! ¿Hay una posada por aquí?",
	["COMP_SAY_VIEW__glutton_2"] = "¡Qué vistas! Perfecto para un pícnic.",
	["COMP_SAY_VIEW__glutton_3"] = "¡Zona nueva! ¿Especialidad local? Quiero probarla.",
	["COMP_SAY_VIEW__glutton_4"] = "Precioso paisaje. Solo falta un bufé.",
	["COMP_SAY_VIEW__glutton_5"] = "¿Ese árbol da fruta? ¿No? ¿Y entonces para qué sirve?",
	["COMP_SAY_VIEW__glutton_6"] = "Nos has perdido, pero huelo una panadería. Sigue a mi nariz.",
	["COMP_SAY_VIEW__glutton_7"] = "¡Oh, setas! ¿Se comen? Mejor preguntemos antes.",
	["COMP_SAY_VIEW__glutton_8"] = "Buen sitio. Volvemos a la hora de la merienda, ¿vale?",
	["COMP_SAY_VIEW__lazy"] = "Bonitas vistas… perfectas para una siesta.",
	["COMP_SAY_VIEW__lazy_2"] = "Un sitio nuevo… ¿nos sentamos a mirarlo?",
	["COMP_SAY_VIEW__lazy_3"] = "Zona nueva. ¿Cuántas colinas hay que subir? No me lo digas.",
	["COMP_SAY_VIEW__lazy_4"] = "Bonito… ¿podemos mirarlo desde aquí, sin andar?",
	["COMP_SAY_VIEW__lazy_5"] = "Otro sitio nuevo. No puedes estarte quieto, ¿eh?",
	["COMP_SAY_VIEW__lazy_6"] = "Nos has traído lejos. Muy lejos. Demasiado, para mis patas.",
	["COMP_SAY_VIEW__lazy_7"] = "Bonito paisaje. Con una hamaca, sería perfecto.",
	["COMP_SAY_VIEW__lazy_8"] = "¿Nos hemos perdido? Bien, sentémonos mientras nos encontramos.",
	["COMP_SAY_VIEW__mischievous"] = "¡Oh! ¡Aquí tenemos que hacer alguna travesura sí o sí!",
	["COMP_SAY_VIEW__mischievous_2"] = "¡Sitio nuevo, bromas nuevas!",
	["COMP_SAY_VIEW__mischievous_3"] = "¡Sitio nuevo! ¿Vinimos a propósito o te has vuelto a perder?",
	["COMP_SAY_VIEW__mischievous_4"] = "Voy a esconder sorpresas por todas partes. Ya verás. ¡O no!",
	["COMP_SAY_VIEW__mischievous_5"] = "¡Bonito! Solo le falta purpurina. Listo, mejor.",
	["COMP_SAY_VIEW__mischievous_6"] = "¡Una zona nueva! ¿Cuántas veces morirás aquí? Apuesto a que tres.",
	["COMP_SAY_VIEW__mischievous_7"] = "Oh, esta gente parece seria. Perfecta para una broma.",
	["COMP_SAY_VIEW__mischievous_8"] = "¿Ves eso? ¡Un cartel! ¿Sabes leer carteles? Je, je.",
	["COMP_SAY_VIEW__mischievous_9"] = "Acabamos de llegar y ya veo tres travesuras que hacer. Cuatro.",
	["COMP_SAY_VIEW__mystic"] = "Este lugar vibra… algo antiguo duerme aquí.",
	["COMP_SAY_VIEW__mystic_2"] = "Siento una presencia… amable, creo.",
	["COMP_SAY_VIEW__mystic_3"] = "Los antiguos caminaron por aquí. Ellos sabían adónde iban.",
	["COMP_SAY_VIEW__mystic_4"] = "Este lugar susurra tu nombre. Pregunta por qué te has perdido.",
	["COMP_SAY_VIEW__mystic_5"] = "Una tierra nueva… los espíritus del lugar te están evaluando.",
	["COMP_SAY_VIEW__mystic_6"] = "Siento ruinas, secretos… y lobos. Sobre todo lobos.",
	["COMP_SAY_VIEW__mystic_7"] = "Las estrellas me mostraron este lugar. Más bonito, eso sí.",
	["COMP_SAY_VIEW__mystic_8"] = "Un escalofrío ancestral. O una corriente de aire. Cuidado.",
	["COMP_SAY_VIEW__parrot"] = "¡Nuevo! ¡Nuevo! ¡Bonito! ¡Cuac!",
	["COMP_SAY_VIEW__parrot_2"] = "¡Mira! ¡Mira! ¡Cuac!",
	["COMP_SAY_VIEW__parrot_3"] = "¿Perdido? ¿Perdido? ¡Cuac!",
	["COMP_SAY_VIEW__parrot_4"] = "¡Mapa! ¡Mapa! ¡Mira el mapa!",
	["COMP_SAY_VIEW__parrot_5"] = "¡Oh! ¡Oh! ¡Nuevecito! ¡Cuac!",
	["COMP_SAY_VIEW__parrot_6"] = "¡Lejos! ¡Lejos! ¿Demasiado lejos? ¡Cuac!",
	["COMP_SAY_VIEW__parrot_7"] = "¿Monstruos? ¿Monstruos? ¡Lorito se esconde!",
	["COMP_SAY_VIEW__parrot_8"] = "¡Bonito! ¡Bonito! ¡Muy bonito! ¡Cuac!",
	["COMP_SAY_VIEW__sly"] = "Zona nueva… localiza las salidas. Siempre.",
	["COMP_SAY_VIEW__sly_2"] = "Sss… aquí tiene que haber tesoros escondidos.",
	["COMP_SAY_VIEW__sly_3"] = "Zona nueva. ¿Dónde están los cofres? ¿Y las salidas?",
	["COMP_SAY_VIEW__sly_4"] = "Sss… los vendedores de aquí aún no nos conocen.",
	["COMP_SAY_VIEW__sly_5"] = "¿Perdidos otra vez? Diré que tomamos un atajo.",
	["COMP_SAY_VIEW__sly_6"] = "Buen sitio. Seguro que alguien escondió oro aquí.",
	["COMP_SAY_VIEW__sly_7"] = "Sitio nuevo, presas nuevas. Digo: amigos nuevos.",
	["COMP_SAY_VIEW__sly_8"] = "Busca al vendedor más ingenuo. Del resto me encargo yo.",
	["COMP_SAY_VIEW__teasing"] = "¡Una zona nueva! Sabes leer un mapa, ¿verdad?",
	["COMP_SAY_VIEW__teasing_10"] = "Respira el aire fresco. Y mira el mapa, por una vez.",
	["COMP_SAY_VIEW__teasing_2"] = "¡Bien! Por una vez no damos vueltas en círculo.",
	["COMP_SAY_VIEW__teasing_3"] = "¡Zona nueva! ¿Teníamos que venir aquí o nos hemos perdido?",
	["COMP_SAY_VIEW__teasing_4"] = "Bonito sitio. ¿Dónde está el cementerio más cercano, por cierto?",
	["COMP_SAY_VIEW__teasing_5"] = "¿Abriste el mapa? ¿No? Eso lo explica todo.",
	["COMP_SAY_VIEW__teasing_6"] = "¡Precioso! Parece que los monstruos de aquí te esperaban.",
	["COMP_SAY_VIEW__teasing_7"] = "¡Descubriendo un lugar! ¿O es otro rodeo de tres horas?",
	["COMP_SAY_VIEW__teasing_8"] = "¡Ah, paisaje! Para variar de tus saltos desde acantilados.",
	["COMP_SAY_VIEW__teasing_9"] = "Nueva región. El mismo aventurero. Crucemos los dedos.",
	["COMP_SAY_VIEW__tinker"] = "¡Qué vistas! A ese acantilado le hace falta un ascensor.",
	["COMP_SAY_VIEW__tinker_2"] = "¡Un sitio nuevo! Anotado: cero talleres. Hay que arreglarlo.",
	["COMP_SAY_VIEW__tinker_3"] = "Zona nueva cartografiada. Tomaste el camino equivocado, pero bueno.",
	["COMP_SAY_VIEW__tinker_4"] = "Escaneo del terreno: muchos árboles, cero talleres. Inaceptable.",
	["COMP_SAY_VIEW__tinker_5"] = "¿Qué sostiene ese puente? ¿Cuerdas? Primitivo. Crucemos rápido.",
	["COMP_SAY_VIEW__tinker_6"] = "Altitud, temperatura, humedad: todo anotado. Tu ruta: mejorable.",
	["COMP_SAY_VIEW__tinker_7"] = "¡Un molino! ¡Por fin una máquina! ¿Puedo desmontarlo?",
	["COMP_SAY_VIEW__tinker_8"] = "A este sitio le hace falta un teleférico. Ya dibujo los planos.",
	["COMP_SAY_VIEW__wise"] = "Uuh… cada tierra tiene su historia. Escúchala.",
	["COMP_SAY_VIEW__wise_2"] = "Quien mira, ve lejos. Miremos.",
	["COMP_SAY_VIEW__wise_3"] = "Uuh. Quien conoce el camino no da rodeos. Nosotros sí.",
	["COMP_SAY_VIEW__wise_4"] = "Una tierra nueva. Primero mira, luego corre.",
	["COMP_SAY_VIEW__wise_5"] = "Perderse también es descubrir. Tú descubres mucho.",
	["COMP_SAY_VIEW__wise_6"] = "La colina oculta el valle. El valle oculta problemas.",
	["COMP_SAY_VIEW__wise_7"] = "El viajero con prisa no ve nada. Frena.",
	["COMP_SAY_VIEW__wise_8"] = "Esta tierra es antigua. Más que tus trastos grises.",
	["COMP_SAY_VIEW__zen"] = "Un sitio nuevo. Tomémonos tiempo para mirarlo.",
	["COMP_SAY_VIEW__zen_2"] = "Un sitio nuevo. No hace falta correr de un lado a otro. Mira.",
	["COMP_SAY_VIEW__zen_3"] = "Aquí el viento está en calma. Tú, no tanto. Respira.",
	["COMP_SAY_VIEW__zen_4"] = "Zona nueva. Intentemos no morir aquí enseguida.",
	["COMP_SAY_VIEW__zen_5"] = "El paisaje está quieto. Toma nota.",
	["COMP_SAY_VIEW__zen_6"] = "¿Te perdiste para llegar aquí? No importa. Estamos aquí.",
	["COMP_SAY_VIEW__zen_7"] = "Mira el horizonte. No el mapa. El horizonte.",
	["COMP_SAY_VILLAGE"] = "¡Un pueblo! Huele a pan y a heno.",
	["COMP_SAY_VILLAGE_10"] = "Parada en %s. Ya que estás, vacía las bolsas, que rebosan.",
	["COMP_SAY_VILLAGE_11"] = "Un pueblo tranquilo. Bueno, hasta que llegaste tú.",
	["COMP_SAY_VILLAGE_2"] = "%s: sitio tranquilo, me gusta.",
	["COMP_SAY_VILLAGE_3"] = "¿Un respiro aquí? Seguro que hay posada.",
	["COMP_SAY_VILLAGE_4"] = "Gente amable, casas… y misiones, apuesto.",
	["COMP_SAY_VILLAGE_5"] = "¡Parada en %s! Voy a saludar a todo el mundo.",
	["COMP_SAY_VILLAGE_6"] = "¡%s! Aquí la gente tiene los bolsillos llenos de misiones.",
	["COMP_SAY_VILLAGE_7"] = "¡Un pueblo! Saluda y no le pegues a nadie.",
	["COMP_SAY_VILLAGE_8"] = "%s: tres casas, dos gallinas y un tipo que ha perdido algo.",
	["COMP_SAY_VILLAGE_9"] = "¡Un pueblecito! De esos sitios a los que vuelves como fantasma.",
	["COMP_SAY_WEEKLY_ALL"] = "¡Las tres misiones semanales! ¡Nada menos que un silbato de domador!",
	["COMP_SAY_WEEKLY_DONE"] = "¡Misión semanal hecha! Toma, un lazo.",
	["COMP_SAY_WEEKLY_DONE_2"] = "¡Una semanal menos! Empiezo a estar orgulloso de ti. Un poco.",
	["COMP_SAY_WEEKLY_NEW"] = "¡Nueva semana, nuevas misiones! Están en el diario.",
	["COMP_SAY_WEEKLY_NEW_2"] = "Tres grandes misiones esta semana. ¿Podrás seguir el ritmo? Lo dudo.",
	["COMP_SAY_WINTER_BYE_gfw"] = "El Gran Padre Invierno vuelve al norte… ¡Jo, jo, jo, hasta el año que viene!",
	["COMP_SAY_WINTER_BYE_metzen"] = "Metzen vuelve al norte a tirar del trineo. Sin despedirse: tenía prisa.",
	["COMP_SAY_WINTER_BYE_snowman"] = "El muñequito de nieve vuelve al norte, donde hace un frío estupendo. Te dejó su bufanda.",
	["COMP_SAY_WINTER_COLD"] = "¡Nieve! ¡Por todas partes! ¡Estoy en casa!",
	["COMP_SAY_WINTER_COLD_2"] = "Este frío… es maravilloso. Me siento como nuevo.",
	["COMP_SAY_WINTER_COLD_3"] = "¡Mira, nieva! Puedo hacerme un brazo nuevo.",
	["COMP_SAY_WINTER_HOT"] = "Estoy… goteando.",
	["COMP_SAY_WINTER_HOT_2"] = "Aquí hace calor. Mucho calor. Se me resbala la zanahoria.",
	["COMP_SAY_WINTER_HOT_3"] = "Tranquilo, solo me derrito un poco. Mucho. Un poco mucho.",
	["COMP_SAY_WINTER_SACK"] = "¡Jo, jo, jo! En el saco esta mañana: %s. ¡Para ti!",
	["COMP_SAY_WINTER_SACK_2"] = "Ayer te portaste bien. Toma, %s. No se lo digas a los gnolls.",
	["COMP_SAY_WINTER_SACK_3"] = "Un regalo al día, es la regla. Hoy: ¡%s!",
	["COMP_SAY_WINTER_VISIT"] = "¡Jo, jo, jo! Solo estoy de paso. Te has portado bien, ¿verdad?",
	["COMP_SAY_WINTER_VISIT_2"] = "No me hagas caso, solo reviso mi lista.",
	["COMP_SAY_WINTER_VISIT_3"] = "¡Feliz Festival de Invierno! Deja una galleta junto a tu Piedra de hogar.",
	["COMP_SAY_WINTER_VISIT_4"] = "Metzen me espera en el tejado. ¡Me voy tan rápido como vine!",
	["COMP_SAY_WINTER_VISIT_5"] = "¡Jo, jo! Matas muchos kóbolds. No juzgo. Tomo notas.",
	["COMP_SAY_WINTER_VISIT_6"] = "¡Un saludito desde el norte! Abrígate, que en Cuna del Invierno hiela.",
	["COMP_SAY_WINTER_VISIT_7"] = "Tu registro de misiones es más largo que mi lista. ¡Ánimo!",
	["COMP_SAY_WINTER_VISIT_8"] = "¡Jo, jo, jo! Los goblins me volvieron a cobrar por aparcar el trineo.",
