	["DISC_aids"] = "En la ficha de captura, elige una ayuda: cebo, lazo o silbato. Luego Lanzar, u Omitir.",
	["DISC_announce"] = "En grupo, anuncio tus brillantes y capturas de 3 estrellas. Ajústalo en la página Diario de viaje.",
	["DISC_batch"] = "¿Varias criaturas en la red? Ctrl + clic en la red, o /qc filet tout: las capturas todas.",
	["DISC_chests"] = "Página Exploración: cada zona tiene hitos, y un cofre para mí al 100%%. Haz clic en el bocadillo para verlo.",
