	["GUIDE_SEC_titles"] = "Títulos de entrenador",
	["GUIDE_card_1"] = "Tu ficha de entrenador muestra tu título, tu compañero en 3D con sus efectos, una vitrina de 3 criaturas a tu elección, tus cifras (especies, brillantes capturados y conocidos, sellos, puntos de logro) y tus insignias de sello por continente. Nada privado.",
	["GUIDE_card_2"] = "/qc fiche abre la tuya (ahí eliges tu vitrina); /qc fiche <nombre> pide la de otro jugador. Los jugadores que tienen el addon ven \"%s\" en el menú de clic derecho (solo para jugadores que se sabe que lo tienen) y una línea \"%s\" en su descripción emergente.",
	["GUIDE_card_3"] = "Se comparte por defecto; desactiva \"%s\" en los ajustes (página Día a día): tu ficha no se envía a nadie y el addon guarda silencio. Los intercambios van por mensajes de addon invisibles, nunca en combate.",
	["GUIDE_card_4"] = "Tus proezas también llegan a tu hermandad: brillante, élite, raro o jefe capturado, sello de zona, hito y título de especies, gran logro (25 puntos o más, o un título). Los compañeros de hermandad con QuestCompanion ven un cartel \"HERMANDAD\"; un clic abre tu ficha. Ajustes: \"Anunciar mis proezas a la hermandad\", \"Mostrar las proezas de la hermandad\".",
	["GUIDE_card_5"] = "Compartir: en los carteles de los grandes momentos (brillante, 3 estrellas, élite, raro o jefe, especie nueva, logro, sello, título), el botoncito de chat abre un menú: %s, %s o %s, %s, o %s (el texto va a tu caja de chat, para leerlo antes de pulsar Intro; para canales públicos). Nada se envía sin tu clic. Más tarde: el botón en la tarjeta de un ejemplar de la Reserva, o clic derecho en un logro conseguido. Ajuste \"%s\" (página Diario de viaje). Y por sí solo: un brillante o un ejemplar de 3 estrellas se anuncia en el chat de tu grupo o banda (nada en solitario, nunca en combate: sale al acabar el combate, como mucho una línea cada 30 segundos, una tanda de \"Capturar todo\" en una línea). Ajustes \"%s\" y \"%s\".",
	["GUIDE_effects_1"] = "Una criatura capturada que llevas contigo da dos efectos ligados a su tipo: un efecto de caza y un efecto de confort. Los valores de abajo son los de una criatura normal de 1 estrella con fuerza completa; entre paréntesis, el tope.",
	["GUIDE_effects_2"] = "Multiplica los efectos: rango normal ×%s, élite ×%s, raro y élite raro ×%s, jefe ×%s; +%s si es brillante; +%s por estrella por encima de la primera; +%s por hito de tu colección de ese tipo (ver Títulos de entrenador).",
	["GUIDE_effects_3"] = "Los efectos de un compañero siempre cuentan enteros: sus necesidades son bonificaciones, nunca una pérdida. Tres estados de 45 minutos (Saciado, Descansado, Despierto) forman su humor; con los tres está Radiante: probabilidad de captura +%d%%, brillantes +%d%%. Las mascotas (los compañeros que no capturaste) son el compañero del corazón: una bonificación general modesta que crece con su etapa de evolución.",
	["GUIDE_effects_4"] = "Cambiar de compañero pide confirmación (efectos antiguos y nuevos lado a lado), y los efectos se activan tras %d minutos: eliges un compañero para una salida, no para cada objetivo. La página Compañero muestra sus efectos y la cuenta atrás; la descripción del monstruo, tus probabilidades con la bonificación.",
	["GUIDE_effects_H"] = "Fuerza",
	["GUIDE_missions_1"] = "Cada día, tres misiones: una de captura (capturar una especie nunca capturada de la zona, %d criaturas de un tipo, un élite o un raro), una de exploración (lugares, recolección, misiones) y la misión de carácter de tu compañero. Cada una da %s; las tres, %s.",
	["GUIDE_missions_2"] = "Cada semana, tres misiones más largas, renovadas con el reinicio semanal: siempre una caza de brillante (derrotar uno o capturar uno) y, cuando se puede, una misión por tipo (\"lleva un No-muerto y captura %d No-muertos\": solo cuenta una captura hecha con un compañero de ese tipo). Cada una da %s; las tres, %s.",
	["GUIDE_missions_3"] = "Todo se sigue en la página Misiones del diario, con el kit de captura (cebos, lazos, silbatos) junto a la despensa. También se da un %s cada %d capturas.",
	["GUIDE_net_1"] = "Se acabaron las ventanas emergentes. Cuando un monstruo derrotado merece la captura (una especie que falta en tu colección, un brillante, o un ejemplar que podría superar al tuyo), cae en la red junto a tu compañero.",
	["GUIDE_net_2"] = "Las manadas enteras hacen cola (%d monstruos como máximo); cada uno se queda %d s desde el final del combate. El botón muestra cuántos hay, se vuelve dorado cuando espera un brillante y late unos segundos cuando llega un monstruo. Sigue en pantalla aunque el compañero esté oculto.",
	["GUIDE_net_3"] = "Captura exprés (por defecto): un clic en la red lanza al momento al mejor candidato, incluso en combate; no se abre nada, el resultado es una línea encima de la red. Mayús-clic: toda la red. Ctrl-clic: la tarjeta de preparación (ayudas, Lanzar, Pasar). Clic derecho: la lista (\"×\" o Escape). /qc filet, /qc filet tout, /qc filet auto (la red se lanza sola; un brillante espera tu clic). El chat solo menciona las capturas que importan.",
	["GUIDE_net_4"] = "Captura exprés desactivada (/qc filet express): el cartel \"Captura posible\" nombra la criatura y tus probabilidades; el clic abre la tarjeta de preparación y luego la escena; con dos criaturas o más ofrece \"Capturar todo (N)\". Siempre: Silenciar calla el anuncio y los sonidos durante %s (/qc filet sourdine [min|off]); lo acompaña un tintineo (ajuste %s).",
	["GUIDE_net_5"] = "La escena de captura se reproduce (ajuste %s) y se cierra sola tras el veredicto; un clic o Escape la cierra antes. Tus probabilidades dependen del rango (normal %d%%, élite %d%%, raro %d%%, jefe %d%%) y de la diferencia de nivel; las ayudas las multiplican: %s, %s, %s. Salen de los sellos del diario, los hitos de zona y las misiones.",
	["GUIDE_seals_1"] = "Desde la 2.0, el porcentaje de una zona (página Exploración) solo cuenta la exploración: lugares, recolección y misiones. Las criaturas viven en la página Criaturas. Los hitos y cofres ya ganados siguen siendo tuyos.",
	["GUIDE_seals_2"] = "Captura todas las especies de una zona (versión normal; los jefes del mundo no cuentan) y recibe un sello, para siempre: un marco con los colores de su paisaje al primer sello de un bioma, un fondo al segundo, y brillantes ×%s en la zona.",
	["GUIDE_seals_3"] = "La página Criaturas muestra el sello de la zona elegida y su progreso (especies capturadas sobre las especies de la zona); la página Exploración guarda una línea sobre ello. Los sellos forman también las insignias de tu ficha de entrenador.",
	["GUIDE_settings_1"] = "Página Día a día: %s (lo apaga todo, descripción incluida) · %s · %s · %s · %s · %s · %s.",
	["GUIDE_settings_2"] = "Página Compañero de ruta: %s (%s), para que la criatura llene su marco en pantalla, incluso una bestia capturada a tamaño real; el control %s (Silencioso también desactiva los tutoriales).",
	["GUIDE_settings_3"] = "Comandos: /qc filet (captura al mejor candidato), /qc filet tout (capturar todo), /qc filet sourdine [min|off], /qc capture (tu colección y ayudas), /qc fiche [nombre] (ficha de entrenador), /qc tuto [capture|carnet|reset] (los tutoriales guiados), /qc compagnon tuto (el tutorial básico del compañero), /qc joke (un chiste de tu compañero).",
	["GUIDE_settings_4"] = "Dos tutoriales guiados, una vez por cuenta: primeras capturas (en tu primera ocasión de captura, de la red al veredicto) y el diario (la primera vez que lo abres, pestaña por pestaña). Nunca en combate; Escape o \"Saltar tutorial\" los detiene. Los botones \"%s\" y \"%s\", abajo a la izquierda, los repiten. Sobre el compañero: clic derecho, el diario; Mayús + clic derecho, el modo caza.",
	["GUIDE_settings_5"] = "Estilo de interfaz (página Compañero de ruta): %s (marco dorado, botones biselados) o %s (plano), para toda la interfaz. /qc style azeroth|sobre.",
	["GUIDE_settings_6"] = "Logros (página del diario): /qc hf los abre, /qc hf diag indica qué estadísticas del cliente se pueden leer; lo que aún espera verificación sale en gris. Los logros de colección cuentan para toda tu cuenta, los de hazañas para este personaje. /qc title elige tu título. Tecla Y (si estaba libre): logros. Cartel, chat, fanfarria, forma del título y atajos de teclado: página Diario de viaje.",
	["GUIDE_settings_7"] = "Historia de los lugares (ajuste \"%s\"): texto de Warcraft Wiki (warcraft.wiki.gg), licencia CC BY-SA 4.0, seleccionado y traducido por Spoken de Rusty Key (github.com/rusty-key/spoken-wow). ¡Gracias a ellos!",
	["GUIDE_settings_8"] = "Consejos de descubrimiento: de vez en cuando tu compañero te enseña una función que aún no usas (cambiar de aspecto, despensa, modo caza, Reserva, jukebox…); como mucho uno cada 20 minutos, nunca en combate, en instancias ni durante una captura, cada uno una vez por cuenta. Clic en la burbuja: la página correspondiente. Ajuste \"%s\" (página Compañero de ruta), /qc astuces on|off|reset.",
	["GUIDE_shiny_1"] = "Cualquier especie puede ser brillante. La primera vez que seleccionas o pasas el ratón por un monstruo, tiene 1 posibilidad entre %d de serlo, ×%d para un élite o un raro.",
	["GUIDE_shiny_2"] = "Cuantos más ejemplares de una especie hayas derrotado, más altas tus probabilidades: hasta 1 entre %d tras %d muertes. Un compañero Dragonante o No-muerto, y una zona sellada (×%s), las mejoran aún más.",
	["GUIDE_shiny_3"] = "Un brillante avistado lleva un rombo dorado sobre su nombre (ajuste %s) y queda conocido para siempre: la página Criaturas lo muestra, capturado o no, con su filtro Brillante.",
	["GUIDE_shiny_4"] = "Cada especie tiene dos versiones por capturar, normal y brillante, cada una con sus propias estrellas. Un brillante capturado se convierte en un aspecto propio: tu compañero se ilumina en dorado y destella, y su fuerza gana +%s.",
	["GUIDE_stars_1"] = "Cada monstruo derrotado ya tiene su calidad, de 1 a 3 estrellas, decidida en el golpe final: %d%% de probabilidad de 1 estrella, %d%% de 2, %d%% de 3 en un monstruo corriente (los élites y raros son buenos ejemplares más a menudo). Un buen ejemplar se resiste más: cuesta más capturarlo.",
	["GUIDE_stars_2"] = "Cada captura es un ejemplar: el mejor de cada especie va al Códice, los demás a tu Reserva. La red solo vuelve a una especie que ya tienes por un ejemplar mejor que el tuyo, un brillante, una especie fijada, o en modo caza (/qc hunt).",
	["GUIDE_stars_3"] = "Las estrellas se ven en la escena de captura, en el cartel, en la lista de la red y en la tarjeta de Criaturas. También cuentan para la fuerza de tu compañero: +%s por estrella por encima de la primera.",
	["GUIDE_titles_1"] = "Cada tipo de criatura tiene sus hitos de captura: %s especies para los tipos comunes, %s para los más raros (%s). Cada hito alcanzado refuerza el efecto de un compañero de ese tipo (+%s de fuerza).",
	["GUIDE_titles_2"] = "Las capturas de antes de la 2.0 se recuperan con la actualización: los sellos, hitos y títulos ya merecidos se conceden al instante. Tu título se ve en tu ficha de entrenador y en la página Criaturas.",
	["GUIDE_titles_3"] = "Desde la 2.7, estos hitos son logros, y %d títulos en total se ganan con logros (\"%s\", \"%s\"…). Elige el tuyo en tu ficha de entrenador o con /qc title; \"%s\" (página Diario de viaje): según tu personaje, masculino o femenino.",
	["GUIDE_titles_H"] = "Los títulos",
