	["OPT_COMP_JOKES"] = "El compañero cuenta chistes",
	["OPT_COMP_JOKES_DESC"] = "De vez en cuando, en descanso, un chiste en lugar de charla (según su tipo de criatura). Nunca en combate; sigue el control de Locuacidad. /qc joke pide uno cuando quieras, aunque esto esté desactivado.",
	["OPT_COMP_LORE"] = "El compañero cuenta la historia de los lugares",
	["OPT_COMP_LORE_DESC"] = "Una línea de historia al llegar por primera vez a una zona o un lugar destacado, a veces en descanso. Nunca en combate; sigue el control de Locuacidad. Se calla si el addon Spoken Places está cargado (ya la cuenta él). Texto: Warcraft Wiki (CC BY-SA 4.0), vía Spoken de Rusty Key.",
	["OPT_COMP_MOVE"] = "Mover al compañero",
	["OPT_COMP_MOVE_DESC"] = "Para que no lo muevas cuando querías acariciarlo.",
	["OPT_COMP_NET_SHOW"] = "Mostrar la red de captura",
	["OPT_COMP_NET_SHOW_DESC"] = "El botón de la red junto al compañero, separado de él. Oculto: las criaturas por capturar esperan en la cola (tecla \"Lanzar la red\" o /qc filet).",
	["OPT_COMP_SHOUTS"] = "El compañero grita",
	["OPT_COMP_SHOUTS_DESC"] = "En mayúsculas: peligro en rojo (agro con Ready2Quest, enjambre, poca salud, huidizo, ahogo, calavera…), grandes alegrías en dorado (por los pelos, objeto azul o morado, nivel).",
	["OPT_COMP_SHOW"] = "Mostrar el compañero",
	["OPT_COMP_SIZE"] = "Tamaño",
	["OPT_COMP_TUTO"] = "Repetir el tutorial",
	["OPT_COMP_WINTER_VISIT"] = "Visita sorpresa del Gran Padre Invierno",
	["OPT_COMP_WINTER_VISIT_DESC"] = "Durante el Festival de Invierno (15 de diciembre - 2 de enero), a veces se asoma en una esquina de la pantalla: una vez por sesión como mucho, nunca en combate ni en mazmorra. Un clic lo despide.",
	["OPT_DAILY_CAPTURE"] = "Capturar monstruos derrotados",
	["OPT_DAILY_CAPTURE_AIDAUTO"] = "Ayuda recomendada automática",
	["OPT_DAILY_CAPTURE_AIDAUTO_DESC"] = "En captura exprés, tu mejor ayuda acompaña a la red en un 3 estrellas o un brillante. Desactivado: nunca se gasta una ayuda si no la eliges.",
	["OPT_DAILY_CAPTURE_ANIM"] = "Captura animada",
	["OPT_DAILY_CAPTURE_AUTO"] = "Captura automática",
	["OPT_DAILY_CAPTURE_AUTO_DESC"] = "La red se lanza sola en cuanto un monstruo derrotado merece la pena. Un brillante espera tu clic, salvo que vaya con una ayuda. Requiere la captura exprés.",
	["OPT_DAILY_CAPTURE_DESC"] = "Los monstruos derrotados que valen la pena esperan 30 s tras el combate: una red sobre tu compañero los captura (clic derecho: la lista). Se convierten en aspectos del compañero.",
	["OPT_DAILY_CAPTURE_DIRECT"] = "Lanzar al instante con un clic",
	["OPT_DAILY_CAPTURE_DIRECT_DESC"] = "Al hacer clic en la red se lanza al instante (con la ayuda elegida en la lista), sin la ficha de preparación. Mayús-clic siempre lanza al instante.",
	["OPT_DAILY_CAPTURE_EXPRESS"] = "Captura exprés",
	["OPT_DAILY_CAPTURE_EXPRESS_DESC"] = "Al hacer clic en la red se lanza al instante, incluso en combate: sin aviso, sin ficha, sin escena. El resultado aparece en una línea bajo el compañero. Mayús-clic: toda la red. Ctrl-clic: la ficha de preparación.",
	["OPT_DAILY_CAPTURE_SOUND"] = "Sonidos de captura",
	["OPT_DAILY_CAPTURE_SOUND_DESC"] = "Un tintineo cuando se puede capturar, una melodía cuando sale bien (una fanfarria para un brillante).",
	["OPT_DAILY_CAPTURE_TOAST"] = "Aviso \"Captura posible\"",
	["OPT_DAILY_CAPTURE_TOAST_DESC"] = "Un aviso en cuanto se puede capturar un monstruo derrotado (tras el combate). Haz clic: la red.",
