	["TOUR_A1"] = "La red solo aparece cuando vale la pena: especie nueva, brillante o un ejemplar mejor que el tuyo. La insignia de estrellas indica su calidad. Haz clic en la red.",
	["TOUR_A1_T"] = "¡Ejemplar a la vista!",
	["TOUR_A2"] = "Arriba, la calidad (de 1 a 3 estrellas): cuanto mejor es el ejemplar, más se resiste. Debajo, tus probabilidades. Elige una ayuda: las probabilidades se actualizan.",
	["TOUR_A2_T"] = "La ficha de preparación",
	["TOUR_A3"] = "Lanzar: la red vuela. Pasar: el monstruo sale de la red (clic derecho: dejar de ofrecer la especie). Atajo: Mayús + clic en la red lanza al instante.",
	["TOUR_A3_T"] = "Lanzar o pasar",
	["TOUR_A4_T"] = "¿Adónde va?",
	["TOUR_A4_codex"] = "¡Capturado! Es tu mejor ejemplar de la especie: va al Códice. Los siguientes, salvo que lo superen, irán a tu Reserva. Clic derecho en tu compañero: el diario.",
	["TOUR_A4_fail"] = "Se escapó, pasa. Cuando sale bien, una captura va al Códice (tu mejor ejemplar de cada especie) o a tu Reserva. Clic derecho en tu compañero: el diario.",
	["TOUR_A4_reserve"] = "¡Capturado! Tu Códice ya tenía uno mejor: este ejemplar se une a tu Reserva. Clic derecho en tu compañero: el diario, para ver Códice y Reserva.",
	["TOUR_A5"] = "Mayús + clic derecho en tu compañero: modo caza. De 5 min a 1 h, cada monstruo derrotado va a la red. Recelo: cada captura de la misma especie en un día dificulta la siguiente.",
	["TOUR_A5_T"] = "Modo caza",
	["TOUR_B_addons"] = "El otro addon del proyecto, Ready2Quest: si está instalado y lo que hacen los dos juntos.",
	["TOUR_B_day"] = "Tres misiones al día y tres a la semana: golosinas, ayudas y purpurina de recompensa.",
	["TOUR_B_evolution"] = "Tu compañero: su humor, sus tres estados (Saciado, Descansado, Despierto), su deseo del momento y sus efectos. \"Elegir…\" cambia su aspecto.",
	["TOUR_B_feats"] = "Tus logros y sus puntos: algunos dan títulos y aspectos para tu compañero.",
	["TOUR_B_guide"] = "Aquí se explica todo, con las cifras. Abajo a la izquierda, dos botones repiten estos tutoriales.",
	["TOUR_B_juke"] = "La música del juego: escucha, añade favoritas, crea tu lista.",
	["TOUR_B_menagerie"] = "El Códice: tu mejor ejemplar de cada especie. \"Por completar\" muestra lo que falta; fija una especie para que siempre llegue a la red, \"Localizar\" te dice dónde encontrarla.",
	["TOUR_B_progress"] = "Cada zona: lugares, recolección, misiones. \"n por completar\" cuenta las especies de la zona sin 3 estrellas en el Códice.",
	["TOUR_B_reserve"] = "Tus ejemplares de más. \"Poner en el Códice\" hace de uno tu referencia; \"Liberar\" da purpurina, para gastar en el Puesto del instructor (pestaña siguiente). Cada ejemplar tiene su propio carácter (un pequeño efecto cuando tu compañero lo lleva) y tamaño: ¡uno diminuto o gigante es raro! Y para intercambiar con otro jugador: /qc trade <nombre> (vista Intercambios).",
	["TOUR_B_shop"] = "Gasta aquí tu purpurina: ayudas de captura, huecos de Reserva, el aspecto de tu compañero. Tu saldo está arriba a la derecha; un artículo fuera de alcance te dice lo que falta.",
	["TOUR_DONE"] = "Hecho",
	["TOUR_GIFT"] = "Elige hasta %d criaturas para tu Reserva: una copia de cada una (versión normal, mismas estrellas que tu Códice), algo para intercambiar más adelante. \"Más tarde\": el botón se queda en la página Reserva.",
	["TOUR_GIFT_GO"] = "Elegir mis criaturas",
	["TOUR_GIFT_T"] = "Regalo 3.0",
	["TOUR_MIG"] = "Tus criaturas capturadas antes de la 3.0 (%d especies) se han convertido en %d ejemplares en el Códice, incluidos %d brillantes, guardados aparte. No se pierde nada: aspectos, logros y Colección siguen igual; estos ejemplares van marcados \"%s\".\n\nA partir de ahora, la calidad se decide al matar y la red solo aparece cuando vale la pena: las opciones de \"Recapturas\" desaparecen. Una captura nueva va al Códice si supera la tuya, si no a tu Reserva. Míralo en el diario: Criaturas y Reserva.",
	["TOUR_MIG_GIFT"] = "Y te espera un regalo: elige hasta %d de tus criaturas, una copia de cada una va a tu Reserva.",
	["TOUR_MIG_GO"] = "Ver el diario",
	["TOUR_MIG_LATER"] = "Más tarde",
	["TOUR_MIG_T"] = "Tu colección pasa a la 3.0",
	["TOUR_MSG_ARMED"] = "El tutorial de capturas te guiará en tu próxima ocasión de captura.",
